/* =========================================================
   PREGUNTAS DE: Software y Estándares para la Web (3º)
   ---------------------------------------------------------
   Cada pregunta:
     origen:  "campus" (tests del campus), "examen" (exámenes de otros años)
              o "ia" (creadas por Claude a partir de los apuntes)
     tema:    igual que en data/cursos.js
     fuente:  opcional (nombre del control o del examen)
     correcta: posición de la respuesta buena, empezando en 0
     explicacion: opcional
   Para añadir preguntas de exámenes, copia una línea, cambia los datos
   y pon origen: "examen" y fuente: "Junio 2025" (por ejemplo).
   ========================================================= */

registrarPreguntas("3", "sew", [

  /* ===== CAMPUS VIRTUAL: controles (respuestas oficiales del campus) ===== */
  // T7 · XML: introducción
  {"id":"xml-2","origen":"campus","tema":"T7 · XML: introducción","fuente":"Control Teoría · XML","pregunta":"Sobre el contenido de los elementos en XML se puede decir:","opciones":["Son uno o más caracteres sin espacios en blanco","Pueden incluir caracteres Unicode","No pueden contener números","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":1,"explicacion":"El contenido de un elemento es texto que puede incluir cualquier carácter Unicode, con espacios y números. Las restricciones de «uno o más caracteres sin espacios» son de los NOMBRES de los elementos, no de su contenido."},
  {"id":"xml-3","origen":"campus","tema":"T7 · XML: introducción","fuente":"Control Teoría · XML","pregunta":"Sobre KML se puede decir:","opciones":["Es un estándar del W3C","Solamente permite representar un punto en un mapa","No es un estándar","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":4,"explicacion":"KML es un estándar del Open Geospatial Consortium (OGC), no del W3C. Además permite representar puntos, líneas, polígonos, rutas… no solo un punto. Por eso a, b y c son falsas."},
  {"id":"xml-9","origen":"campus","tema":"T7 · XML: introducción","fuente":"Control Teoría · XML","pregunta":"Sobre el lenguaje derivado de XML denominado XMI se puede decir:","opciones":["Es utilizado en el intercambio de metadatos de diseños de software en UML","Es utilizado en el intercambio de datos de comercio electrónico","Es utilizado en el intercambio de información de firma electrónica","Es utilizado en el intercambio de información bancaria","Es utilizado por interfaces y tecnología .NET"],"correcta":0,"explicacion":"XMI (XML Metadata Interchange) se usa para intercambiar metadatos de diseños de software en UML entre herramientas de modelado. Firma electrónica es XML Signature, .NET es XAML y comercio electrónico es ebXML."},
  {"id":"xml-12","origen":"campus","tema":"T7 · XML: introducción","fuente":"Control Teoría · XML","pregunta":"Sobre SVG se puede decir:","opciones":["Es un vocabulario XML","Es un estándar del W3C","Permite crear gráficos vectoriales","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":3,"explicacion":"SVG es un vocabulario (lenguaje derivado) de XML, es estándar del W3C (SVG 1.0 fue recomendación en 2001) y sirve para describir gráficos vectoriales bidimensionales. Las tres son ciertas."},
  {"id":"xml-15","origen":"campus","tema":"T7 · XML: introducción","fuente":"Control Teoría · XML","pregunta":"Sobre el lenguaje derivado de XML denominado XAML se puede decir:","opciones":["Es utilizado por interfaces y tecnología .NET","Es utilizado para datos de comercio electrónico","Es utilizado para información de firma electrónica","Es utilizado para información bancaria","Es utilizado para intercambio de metadatos de diseños de software en UML"],"correcta":0,"explicacion":"XAML se usa para definir interfaces de usuario en la tecnología .NET. UML es XMI, firma electrónica es XML Signature y comercio electrónico es ebXML."},
  {"id":"xml-16","origen":"campus","tema":"T7 · XML: introducción","fuente":"Control Teoría · XML","pregunta":"Sobre el uso de secciones CDATA en XML se puede decir:","opciones":["Permite especificar datos, utilizando cualquier carácter, especial o no, sin que se interprete como marcado XML","Solamente se puede utilizar para el código fuente de los lenguajes de programación","Si se utiliza para cualquier texto, genera documentos bien formados, pero no válidos","No se puede utilizar con DTDs","Se permiten anidamientos de secciones CDATA"],"correcta":0,"explicacion":"Una sección <![CDATA[ … ]]> permite escribir cualquier carácter (<, &, \"…) sin que se interprete como marcado. Se usa a menudo para código fuente, pero no solo para eso; el documento sigue siendo bien formado y las secciones CDATA no se pueden anidar."},
  {"id":"xml-17","origen":"campus","tema":"T7 · XML: introducción","fuente":"Control Teoría · XML","pregunta":"Sobre XML se puede decir...","opciones":["Es un meta-lenguaje","Es una forma de exportar e importar datos entre aplicaciones","Es un estándar del W3C","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":3,"explicacion":"XML es un metalenguaje (sirve para definir otros lenguajes), se usa para intercambiar datos entre aplicaciones y es un estándar del W3C. Las tres afirmaciones son ciertas."},
  {"id":"xml-18","origen":"campus","tema":"T7 · XML: introducción","fuente":"Control Teoría · XML","pregunta":"Sobre KMZ se puede decir que:","opciones":["Es un estándar de W3C","Es un KML empaquetado usando ZIP","No es un estándar","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":1,"explicacion":"KMZ es un archivo KML comprimido en ZIP (el resultado es binario). El estándar KML lo define el OGC, no el W3C."},
  {"id":"xml-21","origen":"campus","tema":"T7 · XML: introducción","fuente":"Control Teoría · XML","pregunta":"Sobre los nombres de los elementos en XML se puede decir:","opciones":["Son uno o más caracteres sin espacios en blanco","Pueden incluir caracteres Unicode","Son sensibles a mayúsculas y minúsculas","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":3,"explicacion":"Los nombres de elementos tienen uno o más caracteres sin espacios, empiezan por letra o «_», admiten después caracteres Unicode (p. ej. «Estudianteβ») y distinguen mayúsculas de minúsculas. Las tres son ciertas."},
  {"id":"xml-23","origen":"campus","tema":"T7 · XML: introducción","fuente":"Control Teoría · XML","pregunta":"KML es:","opciones":["Es un vocabulario XML","Es un estándar de datos geográficos","Es un estándar de OpenGeoSpatial","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":3,"explicacion":"KML es un vocabulario XML para datos geográficos (Google Earth, Google Maps…) y es un estándar del Open Geospatial Consortium (OGC). Las tres son ciertas."},
  {"id":"xml-26","origen":"campus","tema":"T7 · XML: introducción","fuente":"Control Teoría · XML","pregunta":"Sobre SVG se puede decir que:","opciones":["Permite incrustarse en el código HTML","Permite incrustarse en el código CSS","Permite incrustarse en el código JavaScript","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":0,"explicacion":"Un gráfico SVG puede incrustarse directamente en un documento HTML con el elemento <svg> o ser un archivo .svg independiente. No se incrusta en CSS ni en JavaScript como código."},
  {"id":"xml-27","origen":"campus","tema":"T7 · XML: introducción","fuente":"Control Teoría · XML","pregunta":"Sobre el lenguaje derivado de XML denominado XML Signature se puede decir:","opciones":["Es utilizado para información de firma electrónica","Es utilizado para datos de comercio electrónico","Es utilizado por interfaces y tecnología .NET","Es utilizado para información bancaria","Es utilizado para intercambio de metadatos de diseños de software en UML"],"correcta":0,"explicacion":"XML Signature es el lenguaje derivado de XML para la firma electrónica y la criptografía de documentos. .NET es XAML, UML es XMI y comercio electrónico es ebXML."},
  // T8 · XML: DTD
  {"id":"xml-4","origen":"campus","tema":"T8 · XML: DTD","fuente":"Control Teoría · XML","pregunta":"Sobre el uso de espacios de nombres en XML se puede decir:","opciones":["Evita el problema de la homonimia en las etiquetas","Solamente se puede utilizar para esquemas XML","Si se utiliza para cualquier texto genera documentos bien formados, pero no válidos","No se pueden utilizar con cualquier tipo de documento XML","Se usan para definir los tipos de los esquemas XML"],"correcta":0,"explicacion":"Los espacios de nombres asocian cada etiqueta a una URI para evitar la homonimia, es decir, etiquetas iguales con significados distintos (p. ej. <capital> de un país y <capital> de una inversión). Se pueden usar en cualquier documento XML, no solo en esquemas."},
  {"id":"xml-25","origen":"campus","tema":"T8 · XML: DTD","fuente":"Control Teoría · XML","pregunta":"Sobre los DTD se puede decir:","opciones":["Realizan una validación de XML muy detallada al usar intensivamente PCDATA y CDATA","Son mejores que los XML Schemas para validar","Históricamente son posteriores a los XML Schemas","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":4,"explicacion":"Las tres son falsas: los DTD tienen una validación pobre (casi todo es texto, PCDATA/CDATA, sin tipos ni rangos), son menos potentes que XML Schema y son anteriores a ellos (fueron la primera forma de validar XML)."},
  // T9 · XML Schema
  {"id":"xml-5","origen":"campus","tema":"T9 · XML Schema","fuente":"Control Teoría · XML","pregunta":"Sobre el uso del tipo duración (xs:duration) en XML se puede decir:","opciones":["<duracionRuta>P1Y7M29DT10H</duracionRuta> indica una duración de 1 año, 7 meses, 29 días y 10 horas","<duracionRuta>P1A7M29DT10H</duracionRuta> indica una duración de 1 año, 7 meses, 29 días y 10 horas","<duracionRuta>1A7M29DT10H</duracionRuta> indica una duración de 1 año, 7 meses, 29 días y 10 horas","<duracionRuta>1A7M29D10H</duracionRuta> indica una duración de 1 año, 7 meses, 29 días y 10 horas","<duracionRuta>1Y7M29D10H</duracionRuta> indica una duración de 1 año, 7 meses, 29 días y 10 horas"],"correcta":0,"explicacion":"El formato de xs:duration es PnYnMnDTnHnMnS: P obligatoria al inicio, Y para años (no A), M meses, D días y T antes de la parte de tiempo (H horas). Por eso P1Y7M29DT10H es la única correcta."},
  {"id":"xml-6","origen":"campus","tema":"T9 · XML Schema","fuente":"Control Teoría · XML","pregunta":"En XML Schema se utiliza un tipo fecha (xs:date). Si un elemento inicio viene definido por: <xs:element name = \"inicio\" type = \"xs:date\" /> Elegir la forma correcta del contenido del elemento","opciones":["<inicio>2021-10-21</inicio>","<inicio>\"veintiuno de octubre de 2021\"</inicio>","<inicio>\"21-10-2021\"</inicio>","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":0,"explicacion":"xs:date usa el formato ISO 8601 AAAA-MM-DD sin comillas, por ejemplo 2021-10-21. Ni las fechas en texto ni el formato DD-MM-AAAA son válidos."},
  {"id":"xml-8","origen":"campus","tema":"T9 · XML Schema","fuente":"Control Teoría · XML","pregunta":"Sobre el uso de tipos abstractos en XML se puede decir:","opciones":["Se puede limitar la derivación de tipos abstractos con final = “restriction”","No se pueden usar tipos abstractos","Solamente se pueden usar con tipos simples","No permiten la herencia","Los tipos derivados no pueden usarse en los mismos sitios que el tipo base"],"correcta":0,"explicacion":"Un tipo abstracto (abstract=\"true\") no se puede usar directamente, solo a través de sus tipos derivados. Permite herencia como en POO y se puede limitar la derivación con final=\"restriction\"."},
  {"id":"xml-10","origen":"campus","tema":"T9 · XML Schema","fuente":"Control Teoría · XML","pregunta":"Sobre el uso de tipos abstractos en XML se puede decir:","opciones":["Los tipos derivados pueden usarse en los mismos sitios que el tipo base","No se pueden usar tipos abstractos","Solamente se pueden usar con tipos simples","No permiten la herencia","No se puede limitar la derivación de tipos abstractos con final = “restriction”"],"correcta":0,"explicacion":"Igual que en POO, los tipos derivados por extensión pueden usarse donde se espera el tipo base, indicando en el XML el tipo concreto con xsi:type. Además se puede limitar la derivación con final=\"restriction\"."},
  {"id":"xml-11","origen":"campus","tema":"T9 · XML Schema","fuente":"Control Teoría · XML","pregunta":"Diferencias entre DTDs y XML Schemas:","opciones":["Los DTDs tienen más tipos de datos que los XML Schemas","Los DTDs son un vocabulario XML","Los XML Schema se pueden representar con un árbol n-ario","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":2,"explicacion":"Un XML Schema es en sí mismo un documento XML, así que se puede representar como un árbol n-ario (DOM). Los DTD no son XML y tienen muchos menos tipos de datos que los Schemas, por eso a y b son falsas."},
  {"id":"xml-22","origen":"campus","tema":"T9 · XML Schema","fuente":"Control Teoría · XML","pregunta":"Sobre el uso de la secuencia de elementos complejos no ordenados con <xs:all> en XML se puede decir:","opciones":["Los elementos pueden aparecer en cualquier orden","Los elementos pueden aparecer en cualquier orden solamente si se enumeran todas las combinaciones posibles","Hay una especificación equivalente en los DTDs","Es equivalente a <xs:choice> añadiendo una OR exclusiva","Es equivalente a <xs:sequence> eligiendo UNSORTED"],"correcta":0,"explicacion":"Con <xs:all> los elementos hijos pueden aparecer en cualquier orden. En los DTD no existe equivalente: había que enumerar todas las combinaciones (A,B,C)|(A,C,B)|… <xs:choice> es una alternativa (o-exclusiva) y no existe «UNSORTED»."},
  {"id":"xml-29","origen":"campus","tema":"T9 · XML Schema","fuente":"Control Teoría · XML","pregunta":"Si en XML Schema se quiere definir un elemento que contenga la duración de una actividad, se debe usar:","opciones":["xs:date","xs:dateTime","xs:duration","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":2,"explicacion":"xs:duration representa un intervalo de tiempo (p. ej. PT7H = 7 horas). xs:date es una fecha y xs:dateTime una fecha con hora, no una duración."},
  // T10 · XPath
  {"id":"xml-7","origen":"campus","tema":"T10 · XPath","fuente":"Control Teoría · XML","pregunta":"Sobre XPath se puede decir:","opciones":["Permite acceder al árbol DOM de un documento XML","Tiene sintaxis XML","No es un estándar del W3C","Solamente permite acceder a los atributos de un nodo","Solamente permite acceder al elemento raíz de un documento XML"],"correcta":0,"explicacion":"XPath sirve para identificar y acceder a nodos del árbol DOM de un documento XML (elementos, atributos, texto…). No tiene sintaxis XML, es un estándar del W3C y no se limita a atributos ni a la raíz."},
  {"id":"xml-20","origen":"campus","tema":"T10 · XPath","fuente":"Control Teoría · XML","pregunta":"Sobre XPath se puede decir:","opciones":["Es un lenguaje derivado de XML","No es un estándar del W3C","Identifica los nodos del árbol XML","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":2,"explicacion":"XPath identifica los nodos del árbol XML mediante rutas. No es un lenguaje derivado de XML (su sintaxis no es XML) y sí es un estándar del W3C."},
  {"id":"xml-24","origen":"campus","tema":"T10 · XPath","fuente":"Control Teoría · XML","pregunta":"En XPath que significa //X[last()] [@Y=\"Z\"]","opciones":["primeros hijos X con atributo Y = \"Z\"","últimos hijos X con atributo Y = \"Z\"","descendientes X con atributo Y = \"Z\"","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":1,"explicacion":"X[last()] selecciona el último hijo X entre sus hermanos, y el predicado [@Y=\"Z\"] filtra los que tienen el atributo Y igual a \"Z\". Con // se buscan en todo el documento: últimos hijos X con atributo Y=\"Z\"."},
  // T11 · XSLT
  {"id":"xml-1","origen":"campus","tema":"T11 · XSLT","fuente":"Control Teoría · XML","pregunta":"Sobre XSLT se puede decir:","opciones":["Permite transformar XML en XML","Permite transformar CSS en XSLT","Permite transformar HTML en XML","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":0,"explicacion":"XSLT transforma documentos XML en otros documentos: XML, HTML, texto… Por tanto «transformar XML en XML» es correcto. No transforma CSS ni toma HTML como entrada."},
  {"id":"xml-14","origen":"campus","tema":"T11 · XSLT","fuente":"Control Teoría · XML","pregunta":"XSLT se puede utilizar con la últimas versiones de los navegadores (agentes de usuario):","opciones":["Chrome","Firefox","Microsoft Edge","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":4,"explicacion":"Según los apuntes, por problemas de seguridad los navegadores actuales han dejado de soportar las transformaciones XSLT de archivos XML; solo lo hacían navegadores antiguos como Internet Explorer. Por eso ninguna de las tres es correcta."},
  {"id":"xml-28","origen":"campus","tema":"T11 · XSLT","fuente":"Control Teoría · XML","pregunta":"Sobre XSLT se puede decir:","opciones":["Es un lenguaje de programación","Es un vocabulario XML","Es un lenguaje de transformación de documentos XML","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":3,"explicacion":"XSLT es un lenguaje de programación (tiene bucles, condiciones, variables), es un vocabulario XML (sus hojas son documentos XML) y es un lenguaje de transformación de documentos XML. Las tres son ciertas."},
  {"id":"xml-30","origen":"campus","tema":"T11 · XSLT","fuente":"Control Teoría · XML","pregunta":"Sobre XSLT se puede decir:","opciones":["Tiene sintaxis XML","Lo soportan todos los navegadores (agentes de usuario)","No es un estándar del W3C","Solamente genera XML","No permite procesar documentos XML"],"correcta":0,"explicacion":"Las hojas XSLT son documentos XML (tienen sintaxis XML). Es estándar del W3C, puede generar XML, HTML o texto, y no la soportan los navegadores actuales."},
  // T12 · Procesamiento de XML
  {"id":"xml-13","origen":"campus","tema":"T12 · Procesamiento de XML","fuente":"Control Teoría · XML","pregunta":"Sobre procesamiento y generación de XML se puede decir:","opciones":["Se puede hacer con Java","Se puede hacer con C#","Se pueden hacer con Python","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":3,"explicacion":"Existen parsers y APIs para procesar y generar XML en casi todos los lenguajes: Java (JAXP, SAX, DOM), C# (XmlReader, XmlDocument, LINQ), Python (ElementTree, lxml), JavaScript… Las tres son ciertas."},
  {"id":"xml-19","origen":"campus","tema":"T12 · Procesamiento de XML","fuente":"Control Teoría · XML","pregunta":"El procesamiento de XML se hace:","opciones":["Recorriendo los atributos y después los elementos","Recorriendo el árbol n-ario desde la raíz","Recorriendo los atributos únicos marcados con ID","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":1,"explicacion":"Un documento XML se representa como un árbol n-ario (DOM) y se procesa recorriéndolo desde el elemento raíz hacia sus hijos."},
  // S1-2 · Usabilidad
  {"id":"usab-2","origen":"campus","tema":"S1-2 · Usabilidad","fuente":"Control Seminarios · Usabilidad","pregunta":"¿Cómo podemos favorecer la usabilidad de un sitio Web?","opciones":["Con un buscador","Usar tablas para maquetar","Usar el elemento de HTML iFrame","Todas las respuestas anteriores son correctas"],"correcta":0,"explicacion":"Un buscador visible en todas las páginas mejora la usabilidad: es el equivalente a «preguntar a un encargado». Usar tablas para maquetar o iframes empeora la usabilidad y la accesibilidad."},
  {"id":"usab-3","origen":"campus","tema":"S1-2 · Usabilidad","fuente":"Control Seminarios · Usabilidad","pregunta":"En la página principal de un sitio web se debe colocar:","opciones":["Saludos de bienvenida a los usuarios","Textualmente lo buenos que somos los que hicimos el sitio Web","Videos que deben visualizar obligatoriamente cada vez que entre un usuario al sitio web","Todas las respuestas anteriores son incorrectas"],"correcta":3,"explicacion":"La página principal debe decir de un vistazo qué es el sitio y qué se puede hacer en él. Saludos de bienvenida, autobombo («lo buenos que somos») y vídeos obligatorios son discurso innecesario que Krug manda eliminar."},
  {"id":"usab-4","origen":"campus","tema":"S1-2 · Usabilidad","fuente":"Control Seminarios · Usabilidad","pregunta":"¿Cómo se utiliza la metáfora de un semáforo en un sitio Web?","opciones":["Solo con colores","Con colores y etiquetas","No existen metáforas de semáforo","Ninguna de las respuestas anteriores son correctas"],"correcta":1,"explicacion":"La metáfora del semáforo no debe basarse solo en colores, porque un 8% de los hombres son daltónicos. Hay que reforzar los colores con etiquetas de texto (Adelante, Ayuda, Salir…)."},
  {"id":"usab-5","origen":"campus","tema":"S1-2 · Usabilidad","fuente":"Control Seminarios · Usabilidad","pregunta":"¿Qué es la navegación constante o global?","opciones":["Navegar por el sitio web a una velocidad constante, parando a reflexionar sobre los clics elegidos","Navegar siempre con el mismo navegador","Conjunto de elementos que aparecen en todas las páginas del sitio","Todas las respuestas anteriores son correctas"],"correcta":2,"explicacion":"La navegación constante o global es el conjunto de elementos de navegación que aparecen en todas las páginas, siempre en el mismo sitio y con el mismo aspecto: identificación del sitio, enlace a la página principal, secciones, búsqueda y utilidades."},
  {"id":"usab-6","origen":"campus","tema":"S1-2 · Usabilidad","fuente":"Control Seminarios · Usabilidad","pregunta":"Sobre los Rollovers (carruseles de menú) en sitios Web:","opciones":["Permiten ahorrar espacio","Son muy usables","Son la última moda en interfaz web","Todas las respuestas anteriores son incorrectas"],"correcta":3,"explicacion":"Los rollovers (carruseles) nacieron para ahorrar espacio, pero hoy se consideran obsoletos y poco usables: solo muestran una cosa a la vez, no permiten comparar y son «inquietos». Por eso ninguna de las afirmaciones es correcta tal cual."},
  {"id":"usab-7","origen":"campus","tema":"S1-2 · Usabilidad","fuente":"Control Seminarios · Usabilidad","pregunta":"¿Siempre se puede encontrar una metáfora para el diseño de un sitio Web?","opciones":["Cierto","Falso","No hay metáforas en la Web","Ninguna de las respuestas anteriores es correcta"],"correcta":1,"explicacion":"No siempre hay una metáfora adecuada para un sitio web. Cuando no la hay, según el seminario, hay que incrementar las pruebas de usabilidad."},
  {"id":"usab-8","origen":"campus","tema":"S1-2 · Usabilidad","fuente":"Control Seminarios · Usabilidad","pregunta":"Sobre Usabilidad:","opciones":["Toda la funcionalidad del sitio Web debe ser correcta","El modelo mental del usuario debe percibir el sentido del sitio Web","La curva de aprendizaje del usuario debe ser lo más rápida posible","Todas las respuestas anteriores son correctas"],"correcta":3,"explicacion":"La usabilidad exige que la funcionalidad sea correcta, que el sitio encaje con el modelo mental del usuario y que se aprenda rápido (fácil de aprender + fácil de usar). Las tres son ciertas."},
  {"id":"usab-9","origen":"campus","tema":"S1-2 · Usabilidad","fuente":"Control Seminarios · Usabilidad","pregunta":"¿Cómo debemos guiar al usuario cuando navega por nuestro sitio Web?","opciones":["Cambiando la CSS en cada cambio de página para que se modifiquen los colores de fondo","Incorporando gran cantidad de ventanas emergentes","Indicando donde nos encontramos","Todas las respuestas anteriores son correctas"],"correcta":2,"explicacion":"Hay que indicar siempre dónde está el usuario: nombre de la página, «usted está aquí» resaltado en la navegación y migas de pan. Cambiar los colores en cada página o abrir ventanas emergentes lo desorienta."},
  {"id":"usab-10","origen":"campus","tema":"S1-2 · Usabilidad","fuente":"Control Seminarios · Usabilidad","pregunta":"Sobre Experiencia de Usuario, se puede decir:","opciones":["Es una parte de la Usabilidad","Es una parte de la Accesibilidad","Es una parte de la Adaptabilidad","Todas las respuestas anteriores son incorrectas"],"correcta":3,"explicacion":"La experiencia de usuario (UX) es el concepto más amplio: el conjunto integral de factores de la interacción con un sistema. La usabilidad, la accesibilidad y la adaptabilidad son factores de los que depende la UX, no al revés."},
  // S3 · Adaptabilidad
  {"id":"adapt-1","origen":"campus","tema":"S3 · Adaptabilidad","fuente":"Control Seminarios · Adaptabilidad","pregunta":"Sobre las ventajas de la adaptabilidad web se puede decir:","opciones":["Mejoran la experiencia del usuario","Reducen los costes de creación y mantenimiento","Evita tener que desarrollar aplicaciones específicas para cada sistema operativo","Todas las respuestas anteriores son correctas","Ninguna de las respuestas anteriores es correcta"],"correcta":3,"explicacion":"La adaptabilidad mejora la experiencia del usuario en cualquier dispositivo, reduce costes (un único sitio para todos los dispositivos, menos mantenimiento) y evita desarrollar una aplicación por sistema operativo. Las tres son ciertas."},
  {"id":"adapt-2","origen":"campus","tema":"S3 · Adaptabilidad","fuente":"Control Seminarios · Adaptabilidad","pregunta":"Para que el diseño sea adaptable el tamaño de las fuentes debe ser definido por medio de:","opciones":["px","cm","em","Todas las respuestas anteriores son correctas","Ninguna de las respuestas anteriores es correcta"],"correcta":2,"explicacion":"em es una unidad relativa al tamaño de fuente, así que el texto escala bien en cualquier pantalla. px y cm son unidades absolutas que no se adaptan."},
  {"id":"adapt-3","origen":"campus","tema":"S3 · Adaptabilidad","fuente":"Control Seminarios · Adaptabilidad","pregunta":"La metáfora de los fluidos se utiliza para:","opciones":["Para maquetar tablas","Para estirar imágenes","Para técnicas de diseño adaptable","Todas las respuestas anteriores son correctas","Ninguna de las respuestas anteriores es correcta"],"correcta":2,"explicacion":"La metáfora de los fluidos se refiere al diseño fluido: los elementos se adaptan al espacio disponible como un líquido a su recipiente, usando unidades relativas. Es una técnica de diseño adaptable."},
  {"id":"adapt-4","origen":"campus","tema":"S3 · Adaptabilidad","fuente":"Control Seminarios · Adaptabilidad","pregunta":"Sobre el diseño web adaptable se puede decir:","opciones":["Es un caso particular de la usabilidad","Ha ido evolucionando históricamente hasta la actualidad","Los sitios web se ajustan automáticamente a cualquier resolución","Todas las respuestas anteriores son correctas","Ninguna de las respuestas anteriores es correcta"],"correcta":3,"explicacion":"El diseño adaptable es una aplicación práctica de la usabilidad, ha evolucionado desde la web de escritorio de ancho fijo hasta la revolución móvil, y hace que el sitio se ajuste automáticamente a cualquier resolución. Las tres son ciertas."},
  {"id":"adapt-5","origen":"campus","tema":"S3 · Adaptabilidad","fuente":"Control Seminarios · Adaptabilidad","pregunta":"Sobre las diferencias de usabilidad en dispositivos móviles se puede decir:","opciones":["Los principios de usabilidad son los mismos que en usabilidad web","Los usuarios tienen una iteración más rápida","Los usuarios leen menos que en otros dispositivos","Todas las respuestas anteriores son correctas","Ninguna de las respuestas anteriores es correcta"],"correcta":3,"explicacion":"En móviles se aplican los mismos principios de usabilidad, pero los usuarios se mueven más rápido, leen todavía menos y hay menos espacio. Las tres afirmaciones son ciertas."},
  {"id":"adapt-6","origen":"campus","tema":"S3 · Adaptabilidad","fuente":"Control Seminarios · Adaptabilidad","pregunta":"Las técnicas de diseño adaptable se inician con:","opciones":["HTML 1.1","HTML 4.0","HTML 5","Todas las respuestas anteriores son correctas","Ninguna de las respuestas anteriores es correcta"],"correcta":2,"explicacion":"Según el control del campus, las técnicas actuales de diseño adaptable se inician con HTML5 (viewport, <picture>, media queries de CSS3…), tras la revolución móvil de 2007."},
  {"id":"adapt-7","origen":"campus","tema":"S3 · Adaptabilidad","fuente":"Control Seminarios · Adaptabilidad","pregunta":"Para asegurar la usabilidad en dispositivos móviles, es necesario realizar pruebas:","opciones":["De usabilidad y adaptabilidad","Sobre distinto hardware","Sobre distintos sistemas operativos","Sobre distintos navegadores o agentes de usuario","Todas las respuestas anteriores son correctas"],"correcta":4,"explicacion":"Para asegurar la usabilidad en móviles hay que probar la usabilidad y la adaptabilidad en distintos dispositivos (hardware), sistemas operativos y navegadores. Todas son necesarias."},
  {"id":"adapt-8","origen":"campus","tema":"S3 · Adaptabilidad","fuente":"Control Seminarios · Adaptabilidad","pregunta":"Los conceptos actuales de diseño web adaptable se han definido por hitos de la historia de la computación en el año:","opciones":["1990","1996","2000","2007","Ningún año de los anteriores"],"correcta":3,"explicacion":"En 2007 aparece el primer iPhone, el hito que inicia la revolución móvil y obliga a que las webs se adapten a cualquier pantalla. (2008: Android; 2010: iPad)."},
  {"id":"adapt-9","origen":"campus","tema":"S3 · Adaptabilidad","fuente":"Control Seminarios · Adaptabilidad","pregunta":"Sobre los navegadores o agentes de usuarios para los dispositivos móviles:","opciones":["Son los mismos que en los dispositivos de escritorio","Son los mismos en todos los sistemas operativos","Son versiones adaptadas de los navegadores de escritorio","Todas las respuestas anteriores son correctas","Ninguna de las respuestas anteriores es correcta"],"correcta":2,"explicacion":"Los navegadores móviles suelen ser versiones adaptadas de los de escritorio, y cambian según el sistema operativo. Por eso hay que comprobar cómo se comportan el HTML, el CSS y el JavaScript en cada uno."},
  {"id":"adapt-10","origen":"campus","tema":"S3 · Adaptabilidad","fuente":"Control Seminarios · Adaptabilidad","pregunta":"Para que el diseño sea adaptable el tamaño de las imágenes debe ser definido por medio de:","opciones":["px","cm","%","Todas las respuestas anteriores son correctas","Ninguna de las respuestas anteriores es correcta"],"correcta":2,"explicacion":"Con porcentajes (p. ej. max-width: 100%) la imagen se ajusta al contenedor y nunca lo desborda. px y cm son medidas fijas que rompen el diseño en pantallas pequeñas."},
  // S4 · Accesibilidad
  {"id":"usab-1","origen":"campus","tema":"S4 · Accesibilidad","fuente":"Control Seminarios · Usabilidad","pregunta":"¿Cuáles son las barreras para el acceso a la Web de personas con ceguera?","opciones":["Tablas que solamente se emplean para maquetar páginas","Imágenes sin texto alternativo","Usar Frames o marcos","Todas las respuestas anteriores son correctas"],"correcta":3,"explicacion":"Para una persona ciega con lector de pantalla son barreras: las tablas usadas para maquetar (se leen como datos sin sentido), las imágenes sin texto alternativo y los marcos (iframes), que obligan a usar el ratón. Las tres lo son."},

  // S4 · Accesibilidad (Control Seminarios · Accesibilidad)
  {"id": "acces-1", "origen": "campus", "tema": "S4 · Accesibilidad", "fuente": "Control Seminarios · Accesibilidad", "pregunta": "Indicar las barreras relacionadas con la visión reducida en acceso a la Web:", "opciones": ["Sitios Web con imágenes con mucho contraste", "Sitios Web con pérdida de contexto cuando se amplían", "Sitios Web con tamaños de letra relativos", "Todas las respuestas anteriores son correctas", "Ninguna de las respuestas anteriores es correcta"], "correcta": 1, "explicacion": "Según el Seminario 4, las barreras para la visión reducida son: poco contraste (no mucho), páginas que pierden el contexto al ampliarse y tamaños de letra absolutos (no relativos, que sí se pueden ampliar). La a y la c dicen lo contrario, así que solo la b es correcta."},
  {"id": "acces-2", "origen": "campus", "tema": "S4 · Accesibilidad", "fuente": "Control Seminarios · Accesibilidad", "pregunta": "Indicar la última versión en desarrollo de la normativa WAI denominada “Web Content Accessibility Guidelines”:", "opciones": ["3.0", "2.1", "2.2", "Todas las respuestas anteriores son correctas", "Ninguna de las respuestas anteriores es correcta"], "correcta": 0, "explicacion": "La clave es «en desarrollo»: WCAG 3 está en desarrollo (borrador de trabajo del W3C). WCAG 2.2 (diciembre de 2024) es la última versión ya aprobada como recomendación y 2.1 es de 2018; ambas están terminadas. Si preguntan por la última recomendación, sería la 2.2."},
  {"id": "acces-3", "origen": "campus", "tema": "S4 · Accesibilidad", "fuente": "Control Seminarios · Accesibilidad", "pregunta": "Para que el diseño sea accesible el tamaño de las fuentes debe ser definido por medio de:", "opciones": ["ex", "rem", "em", "Todas las respuestas anteriores son correctas", "Ninguna de las respuestas anteriores es correcta"], "correcta": 3, "explicacion": "ex (altura de la «x»), rem (fuente del elemento raíz) y em (fuente del elemento) son unidades relativas, así que el usuario puede ampliar el texto. La barrera de accesibilidad son los tamaños absolutos (px, pt, cm). En el control de Adaptabilidad la respuesta era «em» porque las otras opciones eran px y cm."},
  {"id": "acces-4", "origen": "campus", "tema": "S4 · Accesibilidad", "fuente": "Control Seminarios · Accesibilidad", "pregunta": "¿Es posible que una persona sorda y ciega pueda navegar por la Web?", "opciones": ["Hay actualmente dispositivos para facilitarlo", "La normativa de accesibilidad si lo contempla", "Si es posible", "Todas las respuestas anteriores son correctas", "Ninguna de las respuestas anteriores es correcta"], "correcta": 3, "explicacion": "Las tres son ciertas: existen dispositivos como las líneas Braille actualizables (la voz sintetizada no le sirve, pero el Braille sí), la normativa de accesibilidad cubre discapacidades visuales y auditivas, y es posible, como muestra la entrevista a una persona sordociega que aparece en las referencias del Seminario 4."},
  {"id": "acces-5", "origen": "campus", "tema": "S4 · Accesibilidad", "fuente": "Control Seminarios · Accesibilidad", "pregunta": "Sobre la Usabilidad Universal se puede decir:", "opciones": ["Es un caso particular de la adaptabilidad", "Es otra definición de la accesibilidad", "Los sitios web se ajustan automáticamente a cualquier resolución", "Todas las respuestas anteriores son correctas", "Ninguna de las respuestas anteriores es correcta"], "correcta": 1, "explicacion": "El Seminario 4 presenta la usabilidad universal como la base de la accesibilidad: que nadie se vea limitado en el uso de algo por sus diferencias, es decir, que la Web sea usable por todas las personas. La a está al revés (la adaptabilidad es un caso particular de la usabilidad) y la c es la definición del diseño web adaptable."},
  {"id": "acces-6", "origen": "campus", "tema": "S4 · Accesibilidad", "fuente": "Control Seminarios · Accesibilidad", "pregunta": "Indicar las barreras relacionadas con el acceso a la Web de las personas con ceguera:", "opciones": ["Imágenes con texto alternativo", "Marcos con la etiqueta “iframe”", "Tablas usadas para contener información", "Todas las respuestas anteriores son correctas", "Ninguna de las respuestas anteriores es correcta"], "correcta": 1, "explicacion": "Los marcos (iframe) son una barrera: para cambiar de marco muchas veces solo sirve el ratón. La a está al revés (la barrera son las imágenes SIN texto alternativo) y la c describe el uso correcto de las tablas (datos); la barrera son las tablas usadas solo para maquetar."},
  {"id": "acces-7", "origen": "campus", "tema": "S4 · Accesibilidad", "fuente": "Control Seminarios · Accesibilidad", "pregunta": "Sobre AENOR se puede decir:", "opciones": ["Define una norma de accesibilidad coincidente con la del W3C", "Define normas UNE", "Es una organización española", "Todas las respuestas anteriores son correctas", "Ninguna de las respuestas anteriores es correcta"], "correcta": 3, "explicacion": "Las tres son ciertas: AENOR es la Asociación Española de Normalización y Certificación, define las normas UNE («Una Norma Española»: 139.801, 139.802, 139803…) y la UNE 139803:2004 fue una trasposición de las WCAG 1.0 del W3C, con versiones posteriores basadas en las WCAG 2.0 y 2.1."},
  {"id": "acces-8", "origen": "campus", "tema": "S4 · Accesibilidad", "fuente": "Control Seminarios · Accesibilidad", "pregunta": "Para que el diseño sea accesible el tamaño de las imágenes debe ser definido por medio de:", "opciones": ["vw", "vh", "%", "Todas las respuestas anteriores son correctas", "Ninguna de las respuestas anteriores es correcta"], "correcta": 3, "explicacion": "vw (1% del ancho del viewport), vh (1% del alto) y % (relativo al contenedor) son unidades relativas, así que la imagen se adapta al espacio disponible. En el control de Adaptabilidad la respuesta era «%» porque las otras opciones eran px y cm, que son absolutas."},
  {"id": "acces-9", "origen": "campus", "tema": "S4 · Accesibilidad", "fuente": "Control Seminarios · Accesibilidad", "pregunta": "Sobre la protanopia se puede decir:", "opciones": ["Se refiere a la visión en gama de grises", "Se refiere a la ceguera al color verde", "Se refiere a la ceguera al color azul", "Todas las respuestas anteriores son correctas", "Ninguna de las respuestas anteriores es correcta"], "correcta": 4, "explicacion": "La protanopia es la falta de sensibilidad al color ROJO, opción que no aparece. El verde es la deuteranopia y el azul la tritanopia; ver en grises no es la protanopia. Truco: pro-, deuter-, tri- = primero, segundo y tercero de RGB (rojo, verde, azul)."},
  {"id": "acces-10", "origen": "campus", "tema": "S4 · Accesibilidad", "fuente": "Control Seminarios · Accesibilidad", "pregunta": "Sobre SWML se puede decir:", "opciones": ["Es un lenguaje estándar basado en signos de las manos", "Son las siglas de “SignWriting Markup Language”", "No se puede utilizar en sitios Web", "Todas las respuestas anteriores son correctas", "Ninguna de las respuestas anteriores es correcta"], "correcta": 1, "explicacion": "SWML significa SignWriting Markup Language. Según el Seminario 4 es un lenguaje estándar basado en XML (no «en signos de las manos»; además, el lenguaje de signos no está normalizado y cambia en cada país) y la mayoría de las aplicaciones web de escritura de signos se basan en él, así que la c también es falsa."},

  /* ===== EXÁMENES DE OTROS AÑOS =====
     Añade aquí las preguntas con origen: "examen" */
  /* Cuestionarios del 1er parcial */
  {"origen":"examen","tema":"T3 · Lenguajes de presentación","fuente":"1er parcial","pregunta":"La cascada en CSS:","opciones":["Es uno de los principios fundamentales de las hojas de estilo y permite que varias hojas de estilo afecten a un mismo documento.","Produce una lista desordenada con varios valores de estilo a aplicar a cada propiedad en cada elemento del documento estructurado (como HTML y XML)","Permite que los elementos descendientes de un elemento del documento estructurado (como HTML y XML) hereden el valor de las propiedades del elemento padre.","Determina el valor de estilo a aplicar a cada una de las propiedades en cada elemento del documento estructurado (como HTML y XML) según su orden de aparición","Determina el valor de estilo a aplicar a cada una de las propiedades en cada elemento del documento estructurado (como HTML y XML) según la especificidad del selector."],"correcta":0,"explicacion":"La cascada es uno de los principios básicos de CSS: permite que varias hojas de estilo (del autor, del usuario y del navegador) se apliquen a la vez sobre un mismo documento y resuelve qué valor gana. La herencia de propiedades de padres a hijos es otro mecanismo distinto."},
  {"origen":"examen","tema":"T2 · HTML5","fuente":"1er parcial","pregunta":"Elige el elemento HTML5 correcta para definir el título o encabezado de más rango","opciones":["<header>","<title>","<h1>","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":2,"explicacion":"<h1> es el encabezado de mayor rango. <title> es el título de la pestaña (va en <head>) y <header> es un contenedor de cabecera, no un encabezado."},
  {"origen":"examen","tema":"T4 · CSS","fuente":"1er parcial","pregunta":"En cuanto a la especificidad en CSS","opciones":["El selector \"a[accesskey]\" tiene una especificidad de 011","El selector \"body>p\" tiene una especificidad de 012","El selector universal \"*\" tiene una especificidad de 100","El selector \".contenedor\" tiene una especificidad de 100","El selector \"#contenedor\" tiene una especificidad de 010"],"correcta":0,"explicacion":"La especificidad se cuenta como (id, clases/atributos/pseudoclases, elementos). a[accesskey] = 0 ids, 1 atributo, 1 elemento → 011. body>p sería 002, * es 000, .contenedor es 010 y #contenedor es 100."},
  {"origen":"examen","tema":"T2 · HTML5","fuente":"1er parcial","pregunta":"¿Que elementos se utilizan para la definición de listas no ordenadas, ordenadas y de definición en HTML5?","opciones":["<ul>…</ul>; <ol>…</ol>; <dl>…</dl>; <li>…</li>; <dd>…</dd>;","<ul>…</ul>; <ol>…</ol>; <dl>…</dl>","<li>…</li>; <dd>…</dd>; <dt>..</dt>","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":1,"explicacion":"Las listas se definen con <ul> (no ordenada), <ol> (ordenada) y <dl> (de definición). <li>, <dt> y <dd> son sus elementos internos, no los que definen la lista."},
  {"origen":"examen","tema":"T4 · CSS","fuente":"1er parcial","pregunta":"En CSS, a:hover y a:active son…","opciones":["Atributos","Pseudoclases","Pseudoelementos","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":1,"explicacion":":hover y :active son pseudoclases: seleccionan elementos según su estado. Los pseudoelementos llevan :: (::before, ::first-line)."},
  {"origen":"examen","tema":"T5 · CSS: posicionamiento y maquetación","fuente":"1er parcial","pregunta":"En CSS los elementos forman cajas que pueden ser manipuladas a través de la interacción con los siguientes elementos:","opciones":["Contenido, relleno, borde y margen","Relleno, borde y margen","Borde y margen","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":1,"explicacion":"En el modelo de caja el contenido está rodeado por el relleno (padding), el borde (border) y el margen (margin); esas tres son las propiedades con las que se manipula la caja."},
  {"origen":"examen","tema":"T3 · Lenguajes de presentación","fuente":"1er parcial","pregunta":"Sobre CSS se puede decir que:","opciones":["Permite describir la presentación de documentos estructurados (como HTML y XML) en diferentes medios.","Existen múltiples especificaciones de módulos que son manuales de usuario que determinan como se deben establecer estilos.","En el nivel 4 se definen módulos como FlexBox, Grid Layout, etc. con propiedades específicas para establecer el posicionamiento de los elementos de un documento estructurado (como HTML y XML) en diferentes medios.","Promueve la utilización de implementaciones propietarias de los agentes de usuario.","Crea el árbol DOM de los estilos para documentos estructurados (como HTML y XML) en diferentes medios."],"correcta":0,"explicacion":"CSS describe la presentación de documentos estructurados (HTML, XML) en distintos medios (pantalla, impresión…). Los módulos son especificaciones, no manuales; CSS busca estándares, no soluciones propietarias, y no crea el DOM."},
  {"origen":"examen","tema":"T2 · HTML5","fuente":"1er parcial","pregunta":"Para establecer la información referida al autor de un documento HTML5 válido se debe añadir al <head>:","opciones":["<meta name=\"author\" content=\"pepito grillo\" />","<meta name=author content=pepito grillo />","<p> Autor=\"pepito grillo\" </p>","<meta author=\"pepito grillo\" />","<address>Autor: pepito grillo </address>"],"correcta":0,"explicacion":"El autor se indica con <meta name=\"author\" content=\"…\">. Si el valor tiene espacios hay que entrecomillarlo, y no existe un atributo author en <meta>."},
  {"origen":"examen","tema":"T3 · Lenguajes de presentación","fuente":"1er parcial","pregunta":"Las propiedades de estilo para un elemento h1 se pueden establecer:","opciones":["En el documento html mediante: <h1 style = \"color: red;\">Este titulo va en rojo</h1>","En el documento html mediante: <head> <style> h1{color: red;} </style> </head>","Una hoja de estilo estilo.css enlazada a través del elemento <link> en el <head> del documento HTML, que contiene el siguiente código: h1{color:red;}","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":3,"explicacion":"Los estilos se pueden aplicar en línea (atributo style), con una hoja interna (<style> en el <head>) o con una hoja externa enlazada con <link>. Las tres formas son válidas."},
  {"origen":"examen","tema":"T2 · HTML5","fuente":"1er parcial","pregunta":"¿Cuál es el tipo de documento (doctype) correcto en HTML5?","opciones":["<!DOCTYPE HTML5>","<!DOCTYPE html>","<!DOCTYPE HTML PUBLIC \"-//W3C//DTD HTML 5.0//EN\" \"http://www.w3.org/TR/html5/strict.dtd\">","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":1,"explicacion":"En HTML5 el doctype es simplemente <!DOCTYPE html>, sin DTD ni versión."},
  {"origen":"examen","tema":"T4 · CSS","fuente":"1er parcial","pregunta":"En CSS, ¿qué prefijo se emplea para indicar una propiedad específica del navegador Firefox?","opciones":["-ff-","-moz-","-webkit-","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":1,"explicacion":"-moz- es el prefijo de Firefox (Mozilla). -webkit- es el de Chrome/Safari y -ms- el del antiguo Internet Explorer/Edge."},
  {"origen":"examen","tema":"T2 · HTML5","fuente":"1er parcial","pregunta":"Del árbol DOM (Document Object Model) construido a partir de un documento HTML5 válido se puede decir:","opciones":["Los elementos se representan como objetos que pueden ser manipulados con una API.","Los nodos representan a los elementos con tienen etiqueta de inicio <etiqueta> y etiqueta de cierre o final","El elemento raíz es <head>","Es un árbol binario","El elemento raíz es <body>"],"correcta":0,"explicacion":"El DOM representa el documento como un árbol de objetos (nodos) que se manipulan con una API, por ejemplo desde JavaScript. La raíz es <html>, y no es un árbol binario: cada nodo puede tener muchos hijos."},
  {"origen":"examen","tema":"T4 · CSS","fuente":"1er parcial","pregunta":"En cuanto a los selectores en CSS","opciones":["El selector \"a[accesskey]\" selecciona todos los hiperenlaces que tengan el atributo accesskey","El selector \"body>p\" selecciona todos los párrafos que estén dentro de sections, articles, header, footer y aside definidos en el body","El selector \"h2+h1\" selecciona todos los elementos h2 que aparezcan después del elemento h1","El selector \"h2+h1\" selecciona todos los elementos h1 que aparezcan antes del elemento h2","El selector \"#\" selecciona todos los elementos que tengan establecido el atributo id en su definición"],"correcta":0,"explicacion":"a[accesskey] es un selector de atributo: selecciona los <a> que tengan ese atributo. body>p solo selecciona los p hijos directos del body; h2+h1 selecciona el h1 justo después de un h2; # sin nombre no es un selector válido."},
  {"origen":"examen","tema":"T2 · HTML5","fuente":"1er parcial","pregunta":"El elemento <link> de HTML5 sirve para:","opciones":["Vincular al documento HTML recursos externos","Vincular al documento los estilos que deben aplicarse a los elementos HTML especificados en archivos CSS con la etiqueta <style>","Vincular al documento el comportamiento que debe especificarse en archivos JavaScript con la etiqueta <script>","Vincular al documento los estilos especificados en archivos CSS y el comportamiento especificado en archivos JavaScript.","Vincular al documento los hiperenlaces de navegación"],"correcta":0,"explicacion":"<link> vincula recursos externos al documento (hojas de estilo, iconos, etc.). Los scripts se cargan con <script>, no con <link>, y los hiperenlaces se hacen con <a>."},
  {"origen":"examen","tema":"T2 · HTML5","fuente":"1er parcial","pregunta":"Elige el elemento HTML5 correcto para definir el título o encabezado de más rango dentro de una sección o en un article","opciones":["<header>","Depende del contexto donde se ubique la section","<h2>","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":1,"explicacion":"Según el apunte, dentro de una section o un article el encabezado de mayor rango depende del contexto en el que esté. En la otra versión de esta pregunta la respuesta dada es <h1>."},
  {"origen":"examen","tema":"T2 · HTML5","fuente":"1er parcial","pregunta":"Qué elementos son imprescindibles para que un documento sea HTML5 válido y sin advertencias","opciones":["Doctype, html, head, title, body, h1","Doctype, html, head, title, body, link","Doctype, html, head, title, body","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":2,"explicacion":"Un HTML5 mínimo válido necesita el doctype, html, head, title y body. Ni h1 ni link son obligatorios. (En otra versión de la pregunta se añade también el meta charset para evitar advertencias.)"},
  {"origen":"examen","tema":"T4 · CSS","fuente":"1er parcial","pregunta":"De qué color se mostrará el texto \"uniovi\" si tenemos en el documento html: <p>La Universidad de Oviedo se conoce como <a href=\"www.uniovi.es\" title=\"página web de la universidad de oviedo\"> uniovi</a>. </p> y en la hoja de estilo las siguientes reglas: p {color:red;} p a {color:green;} a {color:blue;}","opciones":["Verde","Rojo","Azul","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":0,"explicacion":"Gana p a (especificidad 002) frente a a (001) y frente a p (que solo se heredaría). Por eso uniovi se ve verde."},
  {"origen":"examen","tema":"T4 · CSS","fuente":"1er parcial","pregunta":"Si se quiere cambiar el tamaño del texto de un elemento con CSS se utiliza:","opciones":["font-size","size","text-size","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":0,"explicacion":"El tamaño del texto se cambia con font-size. size y text-size no son propiedades CSS."},
  {"origen":"examen","tema":"T2 · HTML5","fuente":"1er parcial","pregunta":"¿Qué elementos se utilizan en la definición de los componentes de una tabla simple en HTML5?","opciones":["<td>…</td>","<th>…</th>","<tr>…</tr>","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":3,"explicacion":"Una tabla simple usa <tr> para las filas, <th> para las celdas de cabecera y <td> para las celdas de datos."},
  {"origen":"examen","tema":"T2 · HTML5","fuente":"1er parcial","pregunta":"Para incluir la imagen \"casatata.jpg\" en un documento HTML:","opciones":["<img src=\"casatata.jpg\" title=\"La casa de tata\" alt=\"imagen de la casa de tata\" />","<img href=\"casatata.jpg\" title=\"La casa de tata\" alt=\"imagen de la casa de tata\" />","<img src=\"casatata.jpg\" title=\"La casa de tata\" alt=\"imagen de la casa de tata\" > </img>","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":0,"explicacion":"<img> usa src (no href) y es un elemento vacío, así que no lleva etiqueta de cierre </img>. alt es el texto alternativo y title el texto informativo."},
  {"origen":"examen","tema":"T4 · CSS","fuente":"1er parcial","pregunta":"Cuál es la regla en CSS para establecer la familia de tipografía Times New Roman de la familia serif y garantizar que con el validador del W3C no se obtengan errores ni advertencias:","opciones":["font-family: Times new Roman, serif;","font-family: \"Times new Roman\";","font-family: \"Times new Roman\", serif;","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":2,"explicacion":"Los nombres de fuente con espacios van entre comillas, y conviene terminar con una familia genérica (serif) como alternativa. Sin ella, el validador da una advertencia."},
  {"origen":"examen","tema":"T5 · CSS: posicionamiento y maquetación","fuente":"1er parcial","pregunta":"El modelo de caja CSS generado para un elemento <section> de HTML5:","opciones":["Se puede modificar mediante las propiedades margin, padding y border","Se puede modificar el color del margen con la propiedad \"margin: red 2em;\"","Se puede modificar el color del margen con la propiedad \"margin-color: red;\"","El borde (border) de la caja se encuentra entre el relleno (padding) y el contenido (content)","El relleno (padding) permite separar al elemento del resto de elementos de HTML5"],"correcta":0,"explicacion":"La caja se ajusta con margin, padding y border. El margen es siempre transparente (no tiene color), y el orden desde dentro es contenido → padding → border → margin."},
  {"origen":"examen","tema":"T2 · HTML5","fuente":"1er parcial","pregunta":"En los enlaces del menú de navegación para establecer un atajo de teclado para el documento \"Actividades.html\" se utiliza:","opciones":["<a title=\"Actividad\" accesskey=\"a\" href=\"actividades.html\">Actividades </a>","<a title=\"Actividad\" accesskey=\"ab\" href=\"actividades.html\">Actividades </a>","<a title=\"Actividad\" tabindex=\"1\" accesskey=\"ab\" href=\"actividades.html\">Actividades </a>","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":0,"explicacion":"accesskey define un atajo de teclado y su valor debe ser un único carácter. Por eso accesskey=\"ab\" no es correcto."},
  {"origen":"examen","tema":"T2 · HTML5","fuente":"1er parcial","pregunta":"Para introducir el video.mp4 en un documento HTML5…","opciones":["<video source=\"video.mp4\" type=\"video/mp4\" autoplay> </video>","<video src=\"video.mp4\" type=\"video/mp4\" controls=\"autoplay\" />","<video> <source=\"video.mp4\" type=\"video/mp4\" autoplay> </video>","Las respuestas a, b y c son incorrectas","Las respuestas a, b y c son correctas"],"correcta":3,"explicacion":"Lo correcto sería <video src=\"video.mp4\" controls autoplay></video> o usar <source src=\"…\" type=\"…\"> dentro de <video>. a usa un atributo source que no existe, b pone controls=\"autoplay\" y se cierra con />, y c escribe <source=…> mal."},
  {"origen":"examen","tema":"T2 · HTML5","fuente":"1er parcial","pregunta":"Sobre los metadatos en HTML se puede decir…","opciones":["Se sitúan detrás del bloque HEAD","Se definen con el elemento \"meta\" y un valor","No tienen atributos","Las respuestas a, b y c son incorrectas","Las respuestas a, b y c son correctas"],"correcta":3,"explicacion":"Los metadatos van dentro de <head> (no detrás) y se definen con <meta> y atributos como name/content o charset. Por eso ninguna de las tres frases es correcta."},
  {"origen":"examen","tema":"T7 · XML: introducción","fuente":"1er parcial","pregunta":"Sobre el uso de secciones CDATA en XML se puede decir:","opciones":["Permite especificar datos, utilizando cualquier carácter, especial o no, sin que se interprete como marcado XML","Solamente se puede utilizar para el código fuente de los lenguajes de programación","Si se utiliza para cualquier texto, genera documentos bien formados, pero no válidos","No se puede utilizar con DTDs","Se permiten anidamientos de secciones CDATA"],"correcta":0,"explicacion":"Una sección CDATA (<![CDATA[ … ]]>) contiene texto que el parser no interpreta como marcado, aunque tenga < o &. No se pueden anidar."},
  {"origen":"examen","tema":"T10 · XPath","fuente":"1er parcial","pregunta":"En XPath que significa //X[last()] [@Y=\"Z\"]","opciones":["primeros hijos X con atributo Y = \"Z\"","últimos hijos X con atributo Y = \"Z\"","descendientes X con atributo Y = \"Z\"","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":1,"explicacion":"//X busca X en cualquier nivel; [last()] se queda con los que son el último X entre sus hermanos, y [@Y=\"Z\"] filtra los que tienen el atributo Y=\"Z\"."},
  {"origen":"examen","tema":"T7 · XML: introducción","fuente":"1er parcial","pregunta":"Sobre el lenguaje derivado de XML denominado XMI se puede decir:","opciones":["Es utilizado en el intercambio de metadatos de diseños de software en UML","Es utilizado en el intercambio de datos de comercio electrónico","Es utilizado en el intercambio de información de firma electrónica","Es utilizado en el intercambio de información bancaria","Es utilizado por interfaces y tecnología .NET"],"correcta":0,"explicacion":"XMI (XML Metadata Interchange) sirve para intercambiar modelos UML entre herramientas de diseño de software."},
  {"origen":"examen","tema":"T9 · XML Schema","fuente":"1er parcial","pregunta":"Sobre el uso de la secuencia de elementos complejos no ordenados con xs:all en XML se puede decir:","opciones":["Los elementos pueden aparecer en cualquier orden","Los elementos pueden aparecer en cualquier orden solamente si se enumeran todas las combinaciones posibles","Hay una especificación equivalente en los DTDs","Es equivalente a xs:choice añadiendo una OR exclusiva","Es equivalente a xs:sequence eligiendo UNSORTED"],"correcta":0,"explicacion":"xs:all indica que los elementos hijos pueden aparecer en cualquier orden, cada uno como mucho una vez. Los DTD no tienen un equivalente directo: habría que enumerar todas las combinaciones."},
  {"origen":"examen","tema":"T12 · Procesamiento de XML","fuente":"1er parcial","pregunta":"El procesamiento de XML se hace:","opciones":["Recorriendo los atributos y después los elementos","Recorriendo el árbol n-ario desde la raíz","Recorriendo los atributos únicos marcados con ID","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":1,"explicacion":"Un documento XML es un árbol n-ario y se procesa recorriéndolo desde el elemento raíz."},
  {"origen":"examen","tema":"T9 · XML Schema","fuente":"1er parcial","pregunta":"Sobre el uso de tipos abstractos en XML se puede decir:","opciones":["Se puede limitar la derivación de tipos abstractos con final = \"restriction\"","No se pueden usar tipos abstractos","Solamente se pueden usar con tipos simples","No permiten la herencia","Los tipos derivados no pueden usarse en los mismos sitios que el tipo base"],"correcta":0,"explicacion":"Con final=\"restriction\" (o extension) se puede impedir que un tipo se derive por restricción. Los tipos abstractos sí admiten herencia, y sus derivados pueden usarse donde se espera el tipo base."},
  {"origen":"examen","tema":"T11 · XSLT","fuente":"1er parcial","pregunta":"Sobre XSLT se puede decir:","opciones":["Permite transformar XML en XML","Permite transformar CSS en XSLT","Permite transformar HTML en XML","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":0,"explicacion":"XSLT transforma documentos XML en otros documentos: XML, HTML o texto. No transforma CSS, y la entrada debe ser XML."},
  {"origen":"examen","tema":"T11 · XSLT","fuente":"1er parcial","pregunta":"XSLT se puede utilizar con la últimas versiones de los navegadores (agentes de usuario):","opciones":["Chrome","Firefox","Microsoft Edge","Las respuestas a, b y c son incorrectas","Las respuestas a, b y c son correctas"],"correcta":3,"explicacion":"Según los apuntes, los navegadores actuales están dejando de aplicar XSLT, así que no se puede contar con ellos."},
  {"origen":"examen","tema":"T7 · XML: introducción","fuente":"1er parcial","pregunta":"Sobre XML se puede decir...","opciones":["Es un meta-lenguaje","Es una forma de exportar e importar datos entre aplicaciones","Es un estándar del W3C","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":3,"explicacion":"XML es un metalenguaje (sirve para definir otros lenguajes), es una recomendación del W3C y se usa mucho para intercambiar datos entre aplicaciones."},
  {"origen":"examen","tema":"T7 · XML: introducción","fuente":"1er parcial","pregunta":"KML es:","opciones":["Es un vocabulario XML","Es un estándar de datos geográficos","Es un estándar de OpenGeoSpatial","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":3,"explicacion":"KML (Keyhole Markup Language) es un vocabulario XML para datos geográficos, estandarizado por el Open Geospatial Consortium (OGC)."},
  {"origen":"examen","tema":"T11 · XSLT","fuente":"1er parcial","pregunta":"Sobre XSLT se puede decir:","opciones":["Es un lenguaje de programación","Es un vocabulario XML","Es un lenguaje de transformación de documentos XML","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":3,"explicacion":"XSLT es un vocabulario XML que sirve como lenguaje (declarativo) de transformación de documentos XML; el cuestionario lo considera también un lenguaje de programación."},
  {"origen":"examen","tema":"T7 · XML: introducción","fuente":"1er parcial","pregunta":"Sobre SVG se puede decir:","opciones":["Es un vocabulario XML","Es un estándar del W3C","Permite crear gráficos vectoriales","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":3,"explicacion":"SVG (Scalable Vector Graphics) es un vocabulario XML para gráficos vectoriales y es un estándar del W3C."},
  {"origen":"examen","tema":"T9 · XML Schema","fuente":"1er parcial","pregunta":"Sobre el uso del tipo duración (xs:duration) en XML se puede decir:","opciones":["<duracionRuta>P1Y7M29DT10H</duracionRuta> indica una duración de 1 año, 7 meses, 29 días y 10 horas","<duracionRuta>P1A7M29DT10H</duracionRuta> indica una duración de 1 año, 7 meses, 29 días y 10 horas","<duracionRuta>1A7M29DT10H</duracionRuta> indica una duración de 1 año, 7 meses, 29 días y 10 horas","<duracionRuta>1A7M29D10H</duracionRuta> indica una duración de 1 año, 7 meses, 29 días y 10 horas","<duracionRuta>1Y7M29D10H</duracionRuta> indica una duración de 1 año, 7 meses, 29 días y 10 horas"],"correcta":0,"explicacion":"xs:duration usa el formato ISO 8601: empieza por P, usa Y (años), M (meses), D (días) y, tras la T, H, M y S para la parte horaria. Así, P1Y7M29DT10H = 1 año, 7 meses, 29 días y 10 horas."},
  {"origen":"examen","tema":"T7 · XML: introducción","fuente":"1er parcial","pregunta":"Sobre el lenguaje derivado de XML denominado XAML se puede decir:","opciones":["Es utilizado por interfaces y tecnología .NET","Es utilizado para datos de comercio electrónico","Es utilizado para información de firma electrónica","Es utilizado para información bancaria","Es utilizado para intercambio de metadatos de diseños de software en UML"],"correcta":0,"explicacion":"XAML (Extensible Application Markup Language) es el lenguaje XML de Microsoft para definir interfaces en .NET (WPF, UWP…)."},
  {"origen":"examen","tema":"T8 · XML: DTD","fuente":"1er parcial","pregunta":"Sobre los DTD se puede decir:","opciones":["Realizan una validación de XML muy detallada al usar intensivamente PCDATA y CDATA","Son mejores que los XML Schemas para validar","Históricamente son posteriores a los XML Schemas","Las respuestas a, b y c son incorrectas","Las respuestas a, b y c son correctas"],"correcta":3,"explicacion":"Los DTD son anteriores a XML Schema y menos potentes: no tienen tipos de datos (solo PCDATA y CDATA), así que validan con poco detalle. Por eso ninguna de las tres frases es correcta."},
  {"origen":"examen","tema":"T7 · XML: introducción","fuente":"1er parcial","pregunta":"Sobre el lenguaje derivado de XML denominado XML Signature se puede decir:","opciones":["Es utilizado para información de firma electrónica","Es utilizado para datos de comercio electrónico","Es utilizado por interfaces y tecnología .NET","Es utilizado para información bancaria","Es utilizado para intercambio de metadatos de diseños de software en UML"],"correcta":0,"explicacion":"XML Signature es la recomendación del W3C para firmas digitales en XML."},
  {"origen":"examen","tema":"T7 · XML: introducción","fuente":"1er parcial","pregunta":"Sobre el contenido de los elementos en XML se puede decir:","opciones":["Son uno o más caracteres sin espacios en blanco","Pueden incluir caracteres Unicode","No pueden contener números","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":1,"explicacion":"El contenido de un elemento puede tener cualquier texto Unicode, incluidos espacios y números."},
  {"origen":"examen","tema":"T10 · XPath","fuente":"1er parcial","pregunta":"Sobre XPath se puede decir:","opciones":["Es un lenguaje derivado de XML","No es un estándar del W3C","Identifica los nodos del árbol XML","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":2,"explicacion":"XPath identifica (selecciona) nodos del árbol XML. No usa sintaxis XML y sí es un estándar del W3C."},
  {"origen":"examen","tema":"T7 · XML: introducción","fuente":"1er parcial","pregunta":"Sobre KMZ se puede decir que:","opciones":["Es un estándar de W3C","Es un KML empaquetado usando ZIP","No es un estándar","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":1,"explicacion":"KMZ es un archivo KML comprimido en ZIP, que puede incluir también imágenes y otros recursos."},
  {"origen":"examen","tema":"T9 · XML Schema","fuente":"1er parcial","pregunta":"En XML Schema se utiliza un tipo fecha (xs:date). Si un elemento inicio viene definido por: <xs:element name = \"inicio\" type = \"xs:date\" /> Elegir la forma correcta del contenido del elemento","opciones":["<inicio>2021-10-21</inicio>","<inicio>\"veintiuno de octubre de 2021\"</inicio>","<inicio>\"21-10-2021\"</inicio>","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":0,"explicacion":"xs:date usa el formato ISO AAAA-MM-DD sin comillas: <inicio>2021-10-21</inicio>."},
  {"origen":"examen","tema":"T7 · XML: introducción","fuente":"1er parcial","pregunta":"Sobre los nombres de los elementos en XML se puede decir:","opciones":["Son uno o más caracteres sin espacios en blanco","Pueden incluir caracteres Unicode","Son sensibles a mayúsculas y minúsculas","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":3,"explicacion":"Los nombres de elementos XML no pueden tener espacios, admiten caracteres Unicode y distinguen mayúsculas de minúsculas (<Nombre> ≠ <nombre>)."},
  {"origen":"examen","tema":"T9 · XML Schema","fuente":"1er parcial","pregunta":"Sobre el uso de tipos abstractos en XML se puede decir:","opciones":["Los tipos derivados pueden usarse en los mismos sitios que el tipo base","No se pueden usar tipos abstractos","Solamente se pueden usar con tipos simples","No permiten la herencia","No se puede limitar la derivación de tipos abstractos con final = \"restriction\""],"correcta":0,"explicacion":"Los tipos derivados se pueden usar donde se espera el tipo base (sustitución, por ejemplo con xsi:type). La derivación sí se puede limitar con final, y los tipos abstractos admiten herencia."},
  {"origen":"examen","tema":"T10 · XPath","fuente":"1er parcial","pregunta":"Sobre XPath se puede decir:","opciones":["Permite acceder al árbol DOM de un documento XML","Tiene sintaxis XML","No es un estándar del W3C","Solamente permite acceder a los atributos de un nodo","Solamente permite acceder al elemento raíz de un documento XML"],"correcta":0,"explicacion":"XPath permite acceder a cualquier parte del árbol (DOM) de un documento XML: elementos, atributos, texto… No usa sintaxis XML y es un estándar del W3C."},
  {"origen":"examen","tema":"T9 · XML Schema","fuente":"1er parcial","pregunta":"Diferencias entre DTDs y XML Schemas:","opciones":["Los DTDs tienen más tipos de datos que los XML Schemas","Los DTDs son un vocabulario XML","Los XML Schema se pueden representar con un árbol n-ario","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":2,"explicacion":"Un XML Schema es a su vez un documento XML, así que se puede representar como un árbol n-ario. Los DTD no usan sintaxis XML y casi no tienen tipos de datos."},
  {"origen":"examen","tema":"T7 · XML: introducción","fuente":"1er parcial","pregunta":"Sobre el uso de espacios de nombres en XML se puede decir:","opciones":["Evita el problema de la homonimia en las etiquetas","Solamente se puede utilizar para esquemas XML","Si se utiliza para cualquier texto genera documentos bien formados, pero no válidos","No se pueden utilizar con cualquier tipo de documento XML","Se usan para definir los tipos de los esquemas XML"],"correcta":0,"explicacion":"Los espacios de nombres evitan la homonimia: que dos vocabularios usen el mismo nombre de etiqueta con significados distintos (por ejemplo, <title> de HTML y <title> de un libro)."},
  {"origen":"examen","tema":"T9 · XML Schema","fuente":"1er parcial","pregunta":"Si en XML Schema se quiere definir un elemento que contenga la duración de una actividad, se debe usar:","opciones":["xs:date","xs:dateTime","xs:duration","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":2,"explicacion":"Para una duración (un periodo de tiempo) se usa xs:duration. xs:date es una fecha y xs:dateTime una fecha con hora."},
  {"origen":"examen","tema":"T7 · XML: introducción","fuente":"1er parcial","pregunta":"Sobre SVG se puede decir que:","opciones":["Permite incrustarse en el código HTML","Permite incrustarse en el código CSS","Permite incrustarse en el código JavaScript","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":0,"explicacion":"Un SVG se puede incrustar directamente en el código HTML con el elemento <svg>."},
  {"origen":"examen","tema":"T7 · XML: introducción","fuente":"1er parcial","pregunta":"Sobre KML se puede decir:","opciones":["Es un estándar del W3C","Solamente permite representar un punto en un mapa","No es un estándar","Las respuestas a, b y c son incorrectas","Las respuestas a, b y c son correctas"],"correcta":3,"explicacion":"KML no es del W3C sino del OGC (Open Geospatial Consortium), sí es un estándar y permite representar puntos, líneas, polígonos, rutas… Por eso las tres frases son incorrectas."},
  {"origen":"examen","tema":"T11 · XSLT","fuente":"1er parcial","pregunta":"Sobre XSLT se puede decir:","opciones":["Tiene sintaxis XML","Lo soportan todos los navegadores (agentes de usuario)","No es un estándar del W3C","Solamente genera XML","No permite procesar documentos XML"],"correcta":0,"explicacion":"XSLT usa sintaxis XML y es una recomendación del W3C. Puede generar XML, HTML o texto, y no todos los navegadores lo soportan."},
  {"origen":"examen","tema":"T12 · Procesamiento de XML","fuente":"1er parcial","pregunta":"Sobre procesamiento y generación de XML se puede decir:","opciones":["Se puede hacer con Java","Se puede hacer con C#","Se pueden hacer con Python","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":3,"explicacion":"Hay APIs para procesar y generar XML en casi todos los lenguajes: Java (JAXP), C# (System.Xml, LINQ to XML), Python (ElementTree)…"},
  {"origen":"examen","tema":"S1-2 · Usabilidad","fuente":"1er parcial","pregunta":"¿Siempre se puede encontrar una metáfora para el diseño de un sitio Web?","opciones":["Cierto","Falso","No hay metáforas en la Web","Ninguna de las respuestas anteriores es correcta"],"correcta":1,"explicacion":"No siempre existe una metáfora del mundo real que encaje con un sitio web. Cuando la hay ayuda, pero no hay que forzarla."},
  {"origen":"examen","tema":"S1-2 · Usabilidad","fuente":"1er parcial","pregunta":"¿Cómo podemos favorecer la usabilidad de un sitio Web?","opciones":["Con un buscador","Usar tablas para maquetar","Usar el elemento de HTML iFrame","Todas las respuestas anteriores son correctas"],"correcta":0,"explicacion":"Un buscador visible ayuda al usuario a encontrar lo que busca. Las tablas para maquetar y los iframes empeoran la usabilidad y la accesibilidad."},
  {"origen":"examen","tema":"S1-2 · Usabilidad","fuente":"1er parcial","pregunta":"¿Cómo se utiliza la metáfora de un semáforo en un sitio Web?","opciones":["Solo con colores","Con colores y etiquetas","No existen metáforas de semáforo","Ninguna de las respuestas anteriores son correctas"],"correcta":1,"explicacion":"La metáfora del semáforo se usa con colores y además etiquetas (texto o iconos), porque el color solo no basta, por ejemplo para personas daltónicas."},
  {"origen":"examen","tema":"S1-2 · Usabilidad","fuente":"1er parcial","pregunta":"En la página principal de un sitio web se debe colocar:","opciones":["Saludos de bienvenida a los usuarios","Textualmente lo buenos que somos los que hicimos el sitio Web","Videos que deben visualizar obligatoriamente cada vez que entre un usuario al sitio web","Todas las respuestas anteriores son incorrectas"],"correcta":3,"explicacion":"La página principal debe decir qué es el sitio y qué se puede hacer en él. Bienvenidas, autobombo o vídeos obligatorios estorban."},
  {"origen":"examen","tema":"S4 · Accesibilidad","fuente":"1er parcial","pregunta":"¿Cuáles son las barreras para el acceso a la Web de personas con ceguera?","opciones":["Tablas que solamente se emplean para maquetar páginas","Imágenes sin texto alternativo","Usar Frames o marcos","Todas las respuestas anteriores son correctas"],"correcta":3,"explicacion":"Para un lector de pantalla son barreras las tablas usadas para maquetar, las imágenes sin texto alternativo y los frames o marcos."},
  {"origen":"examen","tema":"S1-2 · Usabilidad","fuente":"1er parcial","pregunta":"¿Cómo debemos guiar al usuario cuando navega por nuestro sitio Web?","opciones":["Cambiando la CSS en cada cambio de página para que se modifiquen los colores de fondo","Incorporando gran cantidad de ventanas emergentes","Indicando donde nos encontramos","Todas las respuestas anteriores son correctas"],"correcta":2,"explicacion":"Hay que indicar al usuario dónde se encuentra (página actual resaltada en el menú, migas de pan…). Cambiar colores o abrir ventanas emergentes despista."},
  {"origen":"examen","tema":"S1-2 · Usabilidad","fuente":"1er parcial","pregunta":"Sobre Experiencia de Usuario, se puede decir:","opciones":["Es una parte de la Usabilidad","Es una parte de la Accesibilidad","Es una parte de la Adaptabilidad","Todas las respuestas anteriores son incorrectas"],"correcta":3,"explicacion":"La experiencia de usuario es un concepto más amplio que engloba la usabilidad, la accesibilidad, la adaptabilidad, la estética, etc. No es una parte de ninguna de ellas."},
  {"origen":"examen","tema":"S1-2 · Usabilidad","fuente":"1er parcial","pregunta":"Sobre Usabilidad:","opciones":["Toda la funcionalidad del sitio Web debe ser correcta","El modelo mental del usuario debe percibir el sentido del sitio Web","La curva de aprendizaje del usuario debe ser lo más rápida posible","Todas las respuestas anteriores son correctas"],"correcta":3,"explicacion":"Un sitio usable funciona correctamente, encaja con el modelo mental del usuario y se aprende rápido."},
  {"origen":"examen","tema":"S1-2 · Usabilidad","fuente":"1er parcial","pregunta":"Sobre los Rollovers (carruseles de menú) en sitios Web:","opciones":["Permiten ahorrar espacio","Son muy usables","Son la última moda en interfaz web","Todas las respuestas anteriores son incorrectas"],"correcta":3,"explicacion":"Los rollovers o carruseles de menú esconden opciones, son poco usables y no ahorran realmente espacio útil. Por eso ninguna de las afirmaciones es correcta."},
  {"origen":"examen","tema":"S1-2 · Usabilidad","fuente":"1er parcial","pregunta":"¿Qué es la navegación constante o global?","opciones":["Navegar por el sitio web a una velocidad constante, parando a reflexionar sobre los clics elegidos","Navegar siempre con el mismo navegador","Conjunto de elementos que aparecen en todas las páginas del sitio","Todas las respuestas anteriores son correctas"],"correcta":2,"explicacion":"La navegación constante o global es el conjunto de elementos que se repiten en todas las páginas: identificación del sitio, secciones, búsqueda y utilidades."},
  {"origen":"examen","tema":"S3 · Adaptabilidad","fuente":"1er parcial","pregunta":"Para que el diseño sea adaptable el tamaño de las imágenes debe ser definido por medio de:","opciones":["px","cm","%","Todas las respuestas anteriores son correctas","Ninguna de las respuestas anteriores es correcta"],"correcta":2,"explicacion":"En un diseño adaptable las imágenes se dimensionan con medidas relativas (%), por ejemplo max-width: 100%, para que se ajusten al contenedor."},
  {"origen":"examen","tema":"S3 · Adaptabilidad","fuente":"1er parcial","pregunta":"La metáfora de los fluidos se utiliza para:","opciones":["Para maquetar tablas","Para estirar imágenes","Para técnicas de diseño adaptable","Todas las respuestas anteriores son correctas","Ninguna de las respuestas anteriores es correcta"],"correcta":2,"explicacion":"La metáfora de los fluidos (diseño fluido o líquido) se refiere a las técnicas de diseño adaptable: el contenido se ajusta como un líquido al recipiente."},
  {"origen":"examen","tema":"S3 · Adaptabilidad","fuente":"1er parcial","pregunta":"Para asegurar la usabilidad en dispositivos móviles, es necesario realizar pruebas:","opciones":["De usabilidad y adaptabilidad","Sobre distinto hardware","Sobre distintos sistemas operativos","Sobre distintos navegadores o agentes de usuario","Todas las respuestas anteriores son correctas"],"correcta":4,"explicacion":"Para asegurar la usabilidad en móviles hay que probar la usabilidad y la adaptabilidad en distinto hardware, sistemas operativos y navegadores."},
  {"origen":"examen","tema":"S3 · Adaptabilidad","fuente":"1er parcial","pregunta":"Para que el diseño sea adaptable el tamaño de las fuentes debe ser definido por medio de:","opciones":["px","cm","em","Todas las respuestas anteriores son correctas","Ninguna de las respuestas anteriores es correcta"],"correcta":2,"explicacion":"Para que las fuentes se adapten se usan unidades relativas como em (o rem), no unidades absolutas como px o cm."},
  {"origen":"examen","tema":"S3 · Adaptabilidad","fuente":"1er parcial","pregunta":"Sobre los navegadores o agentes de usuarios para los dispositivos móviles:","opciones":["Son los mismos que en los dispositivos de escritorio","Son los mismos en todos los sistemas operativos","Son versiones adaptadas de los navegadores de escritorio","Todas las respuestas anteriores son correctas","Ninguna de las respuestas anteriores es correcta"],"correcta":2,"explicacion":"Los navegadores móviles son versiones adaptadas de los de escritorio y cambian según el sistema operativo."},
  {"origen":"examen","tema":"S3 · Adaptabilidad","fuente":"1er parcial","pregunta":"Sobre las diferencias de usabilidad en dispositivos móviles se puede decir:","opciones":["Los principios de usabilidad son los mismos que en usabilidad web","Los usuarios tienen una iteración más rápida","Los usuarios leen menos que en otros dispositivos","Todas las respuestas anteriores son correctas","Ninguna de las respuestas anteriores es correcta"],"correcta":3,"explicacion":"En móviles se aplican los mismos principios de usabilidad, pero los usuarios interactúan más rápido y leen todavía menos."},
  {"origen":"examen","tema":"S3 · Adaptabilidad","fuente":"1er parcial","pregunta":"Sobre el diseño web adaptable se puede decir:","opciones":["Es un caso particular de la usabilidad","Ha ido evolucionando históricamente hasta la actualidad","Los sitios web se ajustan automáticamente a cualquier resolución","Todas las respuestas anteriores son correctas","Ninguna de las respuestas anteriores es correcta"],"correcta":3,"explicacion":"El diseño adaptable está relacionado con la usabilidad, ha evolucionado con el tiempo y hace que el sitio se ajuste automáticamente a cualquier resolución."},
  {"origen":"examen","tema":"S3 · Adaptabilidad","fuente":"1er parcial","pregunta":"Las técnicas de diseño adaptable se inician con:","opciones":["HTML 1.1","HTML 4.0","HTML 5","Todas las respuestas anteriores son correctas","Ninguna de las respuestas anteriores es correcta"],"correcta":2,"explicacion":"Las técnicas de diseño adaptable modernas (media queries, viewport, etc.) llegan con HTML5 y CSS3."},
  {"origen":"examen","tema":"S3 · Adaptabilidad","fuente":"1er parcial","pregunta":"Sobre las ventajas de la adaptabilidad web se puede decir:","opciones":["Mejoran la experiencia del usuario","Reducen los costes de creación y mantenimiento","Evita tener que desarrollar aplicaciones específicas para cada sistema operativo","Todas las respuestas anteriores son correctas","Ninguna de las respuestas anteriores es correcta"],"correcta":3,"explicacion":"La adaptabilidad mejora la experiencia de usuario, reduce costes porque hay un único sitio, y evita hacer aplicaciones específicas para cada sistema."},
  {"origen":"examen","tema":"S3 · Adaptabilidad","fuente":"1er parcial","pregunta":"Los conceptos actuales de diseño web adaptable se han definido por hitos de la historia de la computación en el año:","opciones":["1990","1996","2000","2007","Ningún año de los anteriores"],"correcta":3,"explicacion":"El hito es 2007, con el primer iPhone, que dio comienzo a la «revolución móvil»."},
  {"origen":"examen","tema":"T9 · XML Schema","fuente":"1er parcial","pregunta":"En XML Schema se utiliza un tipo fecha (xs:date). Si un elemento inicio viene definido por: <xs:element name = \"inicio\" type = \"xs:date\" /> Elegir la forma correcta del contenido del elemento","opciones":["<inicio>2018-11-01</inicio>","<inicio>\"uno de noviembre de 2018\"</inicio>","<inicio>\"01-11-2018\"</inicio>","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":0,"explicacion":"xs:date usa el formato ISO AAAA-MM-DD sin comillas: <inicio>2018-11-01</inicio>."},
  {"origen":"examen","tema":"T11 · XSLT","fuente":"1er parcial","pregunta":"xsl:variable en el vocabulario XSLT se puede decir","opciones":["No son parte de un vocabulario XML","Se pueden usar para definir las consultas en XSLT","Son una parte de los XML Schemas","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":1,"explicacion":"xsl:variable forma parte del vocabulario XSLT (que es XML, no XML Schema) y guarda valores o resultados de expresiones XPath para reutilizarlos en la hoja."},
  {"origen":"examen","tema":"T12 · Procesamiento de XML","fuente":"1er parcial","pregunta":"Los servicios Web permite:","opciones":["Intercambio de información entre ordenadores","Intercambio de información en XML","Intercambio de información en JSON","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":3,"explicacion":"Los servicios web permiten intercambiar información entre ordenadores, usando formatos como XML (SOAP) o JSON (REST)."},
  {"origen":"examen","tema":"T2 · HTML5","fuente":"1er parcial","pregunta":"Que elementos son imprescindibles para que un documento sea HTML5 válido y sin advertencias:","opciones":["Doctype, html, head, title, body, h1 y el elemento meta estableciendo la codificación de caracteres","Doctype, html, head, title, body, link y el elemento meta estableciendo la codificación de caracteres","Doctype, html, head, title, body y el elemento meta estableciendo la codificación de caracteres","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":2,"explicacion":"Para ser válido y sin advertencias, un HTML5 necesita doctype, html, head, title, body y el <meta charset> con la codificación. Ni h1 ni link son obligatorios."},
  {"origen":"examen","tema":"T2 · HTML5","fuente":"1er parcial","pregunta":"Elige el elemento HTML5 correcto para definir el título o encabezado de más rango dentro de una sección o en un article","opciones":["<header>","<h1>","<h2>","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":1,"explicacion":"En esta versión de la pregunta la respuesta dada es <h1>, porque cada section o article puede empezar con su propio h1. En la otra versión la respuesta es «depende del contexto»."},
  {"origen":"examen","tema":"T2 · HTML5","fuente":"1er parcial","pregunta":"¿Qué elementos se utilizan en la definición de una tabla en HTML5?","opciones":["<td>...</td>","<th>...</th>","<tr>...</tr>","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":2,"explicacion":"Esta versión da como respuesta <tr> (la fila, que es lo que estructura la tabla). En la pregunta sobre los «componentes» de la tabla la respuesta es que se usan los tres."},
  {"origen":"examen","tema":"T5 · CSS: posicionamiento y maquetación","fuente":"1er parcial","pregunta":"Si el valor de la propiedad margin para un elemento en una hoja de estilo es \"margin: 5px 10px 2px\" ¿que valor se aplicará a cada margen?","opciones":["margen izquierdo 10px, margen superior 5px, margen derecho 10px, margen inferior 2px","margen izquierdo 5px, margen superior 10px, margen derecho 5px, margen inferior 2px","margen izquierdo 10px, margen superior 2px, margen derecho 10px, margen inferior 5px","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":0,"explicacion":"Con tres valores, margin: arriba lados abajo. Es decir, superior 5px, izquierdo y derecho 10px, inferior 2px."},
  {"origen":"examen","tema":"T5 · CSS: posicionamiento y maquetación","fuente":"1er parcial","pregunta":"¿Cuál de los valores indicados para la propiedad position hace que la caja correspondiente a un elemento HTML no salga del flujo normal?","opciones":["clear","relative","absolute","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":1,"explicacion":"position: relative desplaza la caja pero conserva su hueco en el flujo normal. absolute (y fixed) la sacan del flujo, y clear no es un valor de position."},
  {"origen":"examen","tema":"T5 · CSS: posicionamiento y maquetación","fuente":"1er parcial","pregunta":"¿Cuál es la propiedad CSS que describe los tipos de caja que se pueden generar?","opciones":["display","position","float","Las respuestas a, b y c son correctas","Las respuestas a, b y c son incorrectas"],"correcta":0,"explicacion":"display define el tipo de caja que genera un elemento (block, inline, flex, grid, none…)."},

  /* ===== CREADAS POR CLAUDE a partir de los apuntes ===== */
  // T1 · Lenguajes de marcado
  {"origen":"ia","tema":"T1 · Lenguajes de marcado","pregunta":"¿Qué organismo normalizó SGML y con qué norma?","opciones":["La ISO, con la norma ISO 8879:1986","El IETF, con el RFC 1866 de 1995","El WHATWG, como estándar vivo en 2004","El W3C, con la recomendación SGML 1.0"],"correcta":0,"explicacion":"SGML (Standard Generalized Markup Language) fue normalizado por la ISO como ISO 8879:1986."},
  {"origen":"ia","tema":"T1 · Lenguajes de marcado","pregunta":"¿Cuál era el principal problema de SGML para su adopción en la Web?","opciones":["No era un estándar internacional reconocido","Solo describía la presentación, no la estructura","No permitía definir nuevos formatos de documento","Era demasiado complicado de manejar"],"correcta":3,"explicacion":"SGML se centra únicamente en la estructura del documento, pero resultaba demasiado complejo para la Web."},
  {"origen":"ia","tema":"T1 · Lenguajes de marcado","pregunta":"En 1991 Tim Berners-Lee publica la definición de «HTML Tags». ¿Qué características tenía?","opciones":["Era un vocabulario XML con 120 elementos","Era un subconjunto de SGML con 22 elementos","Era una reformulación de SGML en XML 1.0","Incluía tablas, applets y fórmulas matemáticas"],"correcta":1,"explicacion":"La primera definición de HTML era un subconjunto de SGML con 22 elementos."},
  {"origen":"ia","tema":"T1 · Lenguajes de marcado","pregunta":"¿Cómo se llamaba el primer navegador web que se menciona en los apuntes?","opciones":["Netscape Navigator","Mosaic","Lynx","ViolaWWW"],"correcta":3,"explicacion":"ViolaWWW fue el primer navegador citado: textual y sobre UNIX."},
  {"origen":"ia","tema":"T1 · Lenguajes de marcado","pregunta":"El estándar de HTML 2.0 (1993-1995) se publicó como:","opciones":["Borrador del WHATWG","ISO 8879","Recomendación del W3C","RFC 1866 del IETF"],"correcta":3,"explicacion":"HTML 2.0 lo establecieron Tim Berners-Lee y Dan Connolly en el grupo de trabajo de HTML del IETF (RFC 1866)."},
  {"origen":"ia","tema":"T1 · Lenguajes de marcado","pregunta":"¿Qué versión de HTML (enero de 1997) incluyó soporte para tablas, applets, subíndices y superíndices, impulsada por empresas como IBM, Microsoft y Netscape?","opciones":["HTML 3.2","HTML 4.01","HTML 3.0","HTML 2.0"],"correcta":0,"explicacion":"HTML 3.2 (enero de 1997). HTML 3.0 fue solo un borrador de 1995 que resultó poco manejable."},
  {"origen":"ia","tema":"T1 · Lenguajes de marcado","pregunta":"Sobre XHTML se puede decir:","opciones":["Es un lenguaje creado por el WHATWG en 2004 para sustituir a HTML","Es un único lenguaje con una semántica distinta a la de HTML 4","Es una familia de tipos de documentos que reformula HTML 4 en XML","Es la versión de HTML5 que sustituyó definitivamente a HTML 4.01"],"correcta":2,"explicacion":"XHTML es una familia de tipos de documentos con la misma semántica que HTML 4, reformulada en XML 1.0 para mejorar la interoperabilidad."},
  {"origen":"ia","tema":"T1 · Lenguajes de marcado","pregunta":"¿Por qué se creó el WHATWG en 2004?","opciones":["Porque el W3C había paralizado HTML para priorizar XHTML","Para desarrollar XHTML 2 en colaboración con el W3C","Para crear CSS Level 3 y sus módulos independientes","Para normalizar SGML como norma ISO internacional"],"correcta":0,"explicacion":"El W3C había paralizado HTML para priorizar XHTML; Apple, Mozilla y Opera crearon el WHATWG para seguir con HTML."},
  {"origen":"ia","tema":"T1 · Lenguajes de marcado","pregunta":"¿Qué empresas formaron el WHATWG?","opciones":["Sun Microsystems, Novell y SoftQuad","IBM, Microsoft y Netscape Communications","Google, Microsoft y Apple Computer Inc.","Apple, Mozilla Foundation y Opera Software"],"correcta":3,"explicacion":"El WHATWG lo crearon en 2004 Apple, la Mozilla Foundation y Opera Software, como respuesta a que el W3C había paralizado HTML para priorizar XHTML."},
  {"origen":"ia","tema":"T1 · Lenguajes de marcado","pregunta":"¿Qué se acordó en el Memorandum of Understanding entre W3C y WHATWG (28/05/2019)?","opciones":["Que HTML volvería a basarse en SGML para mejorar la compatibilidad","Que el W3C mantendría XHTML y el WHATWG se encargaría solo de HTML5","Que habría una única versión de HTML y del DOM, publicada por el WHATWG","Que se cerraría el grupo de HTML y el DOM pasaría a depender de ECMA"],"correcta":2,"explicacion":"Desde 2019 hay una única especificación de HTML (html.spec.whatwg.org) y una única del DOM."},
  {"origen":"ia","tema":"T1 · Lenguajes de marcado","pregunta":"¿En qué año el W3C adopta la especificación HTML5 del WHATWG?","opciones":["2014","2000","2004","2007"],"correcta":3,"explicacion":"En abril de 2007 el WHATWG lo propone y en mayo de 2007 el W3C relanza su grupo de HTML adoptando HTML5. La recomendación HTML5 llegó el 28/10/2014."},
  {"origen":"ia","tema":"T1 · Lenguajes de marcado","pregunta":"Sobre XML se puede decir:","opciones":["Es una versión ampliada y más compleja de HTML","Es una versión simplificada de SGML y un metalenguaje","Es un lenguaje de presentación similar a CSS","Es una norma ISO de 1986 anterior a SGML"],"correcta":1,"explicacion":"XML (desarrollado por el W3C) es una versión simplificada de SGML y un metalenguaje para intercambiar información con vocabularios auto-descritos."},
  {"origen":"ia","tema":"T1 · Lenguajes de marcado","pregunta":"¿Cuál de estos NO es un objetivo de XML según los apuntes?","opciones":["Ser un formato abierto e independiente de la plataforma","Ser un estándar de intercambio de información en la Web","Permitir que los documentos sean auto-descritos","Definir la apariencia visual de los documentos"],"correcta":3,"explicacion":"XML describe datos y su estructura; la apariencia es cosa de lenguajes de presentación como CSS o de transformaciones como XSLT."},
  {"origen":"ia","tema":"T1 · Lenguajes de marcado","pregunta":"¿Qué ocurrió en 2010 con XHTML?","opciones":["Se cerró el grupo de trabajo de XHTML2","El WHATWG adoptó XHTML como estándar vivo","XHTML 5 se convirtió en recomendación del W3C","Se publicó la primera versión de XHTML 1.0"],"correcta":0,"explicacion":"El 17 de diciembre de 2010 se cerró el XHTML2 Working Group."},
  // T2 · HTML5
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Quién mantiene actualmente el estándar HTML y cómo se denomina?","opciones":["La ISO, como revisión de la norma ISO 8879","El W3C, como recomendación numerada HTML 5.3","El WHATWG, como estándar vivo (Living Standard)","El IETF, como una actualización del RFC 1866"],"correcta":2,"explicacion":"Se popularizó como HTML5, pero hoy HTML es un Living Standard mantenido por el WHATWG."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Por qué es imprescindible <!DOCTYPE html>?","opciones":["Porque indica el idioma principal del documento","Porque activa el modo estándar del navegador","Porque define la codificación de caracteres","Porque enlaza con el DTD externo de HTML5"],"correcta":1,"explicacion":"Activa el modo estándar y permite interpretar el documento como HTML moderno. A diferencia de XHTML 1.1, no usa un DTD externo."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Qué dos cosas se deben indicar siempre dentro de <head>?","opciones":["Las hojas de estilo con <link> y los scripts","El encabezado principal <h1> y el elemento <nav>","El atributo lang y la URL base con el elemento <base>","La codificación (meta charset) y el elemento <title>"],"correcta":3,"explicacion":"Siempre: <meta charset=\"utf-8\" /> y un <title> que identifique el documento incluso fuera de contexto."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Cómo se indica el idioma de un documento HTML?","opciones":["<body lang=\"spanish\">","<!DOCTYPE html es>","<html lang=\"es\">","<meta language=\"es\">"],"correcta":2,"explicacion":"Con el atributo lang del elemento raíz, usando códigos de dos letras (ISO 639-1)."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"Según los apuntes, ¿cómo deben escribirse los nombres de los elementos en HTML?","opciones":["Da igual, se recomienda mezclarlas","Siempre en minúsculas","En mayúsculas solo los de bloque","Siempre en mayúsculas, como en HTML4"],"correcta":1,"explicacion":"HTML admite ambas, pero la recomendación es usar minúsculas siempre."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Qué es el árbol DOM?","opciones":["La representación en memoria del documento que crea el navegador","Un archivo .dom que se genera junto a cada documento HTML","El DTD interno que usa HTML5 para validar los documentos","La hoja de estilos por defecto que aplica cada navegador"],"correcta":0,"explicacion":"Al analizar (parsear) el HTML, el navegador construye el árbol DOM, una representación en memoria del documento formada por nodos (de tipo de documento, de elementos, de texto, de comentarios…) que se puede manipular con scripts."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Por qué aparecen muchos nodos #text en un árbol DOM?","opciones":["Porque cada atributo de un elemento genera uno","Porque el DOCTYPE genera un nodo de texto por línea","Por los espacios en blanco y saltos de línea del código","Porque cada comentario del documento genera varios"],"correcta":2,"explicacion":"El parser convierte en nodos #text los espacios en blanco y retornos de carro que hay entre etiquetas, por eso aparecen tantos en el árbol DOM."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Qué atributo es obligatorio en el elemento <link>?","opciones":["media","type","title","rel"],"correcta":3,"explicacion":"<link rel=\"stylesheet\" href=\"default.css\" />: el destino va en href y rel es obligatorio."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Para qué sirve el elemento <base>?","opciones":["Para fijar la fuente tipográfica base de todo el documento","Para definir la URL base con la que se resuelven las URL relativas","Para indicar el elemento raíz a partir del cual se construye el DOM","Para cargar la hoja de estilos principal antes que las demás"],"correcta":1,"explicacion":"Con <base href=\"http://www.uniovi.es\" /> el enlace demo.html se buscará en http://www.uniovi.es/demo.html."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Qué inconveniente tiene definir estilos con el elemento <style> dentro del documento?","opciones":["Solo admite el medio print, así que no sirve para la pantalla","No funciona en HTML5 y solo es válido en los documentos XHTML","Mezcla contenido y presentación, lo que dificulta el mantenimiento","Obliga a usar JavaScript para aplicar los estilos al documento"],"correcta":2,"explicacion":"<style> mete la presentación dentro del propio documento: no se puede reutilizar en otras páginas y mezcla contenido y presentación, lo que dificulta el mantenimiento. Lo recomendable es una hoja externa con <link>."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Cuándo se debe usar <article> en lugar de <section>?","opciones":["Cuando el contenido tiene sentido por sí solo y podría reutilizarse fuera","Cuando el bloque contiene los enlaces de navegación principal del sitio","Cuando el contenido es complementario y suele ir en una barra lateral","Siempre que el bloque tenga un encabezado h1-h6 que lo identifique"],"correcta":0,"explicacion":"section agrupa contenido relacionado temáticamente; article es una composición autocontenida reutilizable."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"Sobre el elemento <aside> se puede decir:","opciones":["Sustituye al elemento <nav> cuando la navegación es secundaria o lateral","Solo puede aparecer una vez por documento y siempre a la derecha del contenido","Significa siempre «barra lateral» y debe colocarse fuera del elemento <main>","Representa contenido complementario al principal y puede ir dentro de un article"],"correcta":3,"explicacion":"<aside> es contenido complementario o tangencial al principal (p. ej. «Datos rápidos» de un artículo). No significa «barra lateral»: puede ir dentro de article o section, o integrado en el flujo de la página."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Qué recomiendan los apuntes respecto al elemento <h1>?","opciones":["Usar un <h1> en cada sección para marcar su comienzo","Usar un único <h1> por documento para el tema principal","Evitarlo y usar <hgroup> para agrupar los títulos","Ponerlo siempre dentro de <header> y nunca en <main>"],"correcta":1,"explicacion":"HTML permite varios <h1>, pero se recomienda uno solo y respetar la jerarquía de encabezados."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"Sobre el elemento <main> se puede decir:","opciones":["Debe haber como máximo uno visible y sin lo que se repite en todo el sitio","Es un elemento de la cabecera <head> que agrupa los metadatos","Debe contener la navegación principal, el logotipo y el buscador","Puede haber tantos como secciones, uno por cada bloque temático"],"correcta":0,"explicacion":"<main> marca el contenido principal y específico del documento. Debe haber como máximo uno visible y no debe incluir lo que se repite en todo el sitio, como la navegación principal, el logotipo o el copyright."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Qué dice la especificación sobre el uso de <div>?","opciones":["Es el elemento de bloque recomendado por defecto para agrupar","Solo puede usarse dentro de <span> para agrupar fragmentos","Está obsoleto en HTML5 y ha sido sustituido por <section>","Debe usarse como último recurso, si no hay otro elemento adecuado"],"correcta":3,"explicacion":"La especificación dice que <div> es el «cajón de sastre» para bloques: se usa solo como último recurso, cuando ningún elemento semántico (section, article, nav…) es adecuado, porque así se mejora la accesibilidad y el mantenimiento."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Qué elemento conserva los saltos de línea, espacios y tabuladores tal como están en el código?","opciones":["<pre>","<br>","<blockquote>","<p>"],"correcta":0,"explicacion":"<pre> representa texto preformateado: mantiene saltos de línea, espacios y tabuladores tal como aparecen en el código. Se usa para código fuente, salidas de consola, poemas… En <p> el navegador ignora los espacios extra."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Qué tipo de lista se usa para asociar términos con sus descripciones (glosarios, FAQs)?","opciones":["<ul> con <li>","<ol> con <li>","<menu> con <li>","<dl> con <dt> y <dd>"],"correcta":3,"explicacion":"Las listas de descripción <dl> asocian términos (<dt>) con sus descripciones (<dd>); son típicas de glosarios, diccionarios y FAQs. <ul> es una lista sin orden, <ol> con orden y <menu> una lista de acciones u opciones."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Cuántos <figcaption> puede contener una <figure>?","opciones":["Uno por cada imagen que contenga","Ninguno, va fuera de la figura","Como máximo uno","Exactamente dos (inicio y final)"],"correcta":2,"explicacion":"Una <figure> puede tener como máximo un <figcaption>, que le da título o descripción y puede ir al principio o al final de la figura."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Qué valores de rel son habituales al usar target=\"_blank\" en un enlace?","opciones":["noopener y noreferrer","author y license","next y prev","stylesheet e icon"],"correcta":0,"explicacion":"noopener impide que el documento enlazado acceda a la ventana que lo abrió y noreferrer no envía información de referencia."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Qué diferencia hay entre <strong> y <b>?","opciones":["Ninguna: ambos son sinónimos y los navegadores los muestran en negrita","<b> indica importancia semántica; <strong> solo llama la atención visualmente","<strong> indica importancia semántica; <b> solo llama la atención visualmente","<strong> está obsoleto en HTML5 y hay que usar <b> en su lugar"],"correcta":2,"explicacion":"<strong> tiene significado semántico: importancia, urgencia o relevancia. <b> solo llama la atención visualmente, sin importancia semántica. Ambos se suelen ver en negrita y ninguno está obsoleto."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Qué representa el elemento <cite>?","opciones":["El autor de una obra","El título de una obra","Una cita extensa en bloque","Una cita breve en línea"],"correcta":1,"explicacion":"<cite> es el título de una obra (no su autor). La cita breve es <q> y la extensa <blockquote>."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Qué atributos son obligatorios en <img>?","opciones":["alt y title","width y height","src y alt","src y title"],"correcta":2,"explicacion":"width y height se recomiendan para que el navegador reserve el espacio, pero no para redimensionar."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Para qué se usa el elemento <picture>?","opciones":["Para añadir un pie de foto o título descriptivo a una imagen","Para incrustar documentos PDF o recursos externos en la página","Para dibujar gráficos vectoriales directamente en el documento","Para ofrecer varias versiones de una imagen según el dispositivo"],"correcta":3,"explicacion":"<picture> contiene varios <source> y un <img>; el navegador elige automáticamente la versión más adecuada según la pantalla o el formato soportado (AVIF, WebP…). Facilita el diseño adaptable."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Qué elemento añade subtítulos a un <video> y en qué formato?","opciones":["<caption>, en formato SRT (.srt)","<track>, en formato WebVTT (.vtt)","<source>, en formato MP4 con pista","<figcaption>, en texto plano (.txt)"],"correcta":1,"explicacion":"<track> asocia información temporal (subtítulos, descripciones) a un <video> o <audio> usando archivos WebVTT (.vtt), por ejemplo kind=\"subtitles\" srclang=\"es\". Mejora la accesibilidad."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"En una tabla compleja con varios niveles de encabezado, ¿cómo se hace accesible?","opciones":["Identificando los <th> con id y enlazando cada <td> con headers","Añadiendo el atributo scope a cada celda de datos <td>","Usando solo celdas <td> con el texto de los encabezados en negrita","Poniendo un <caption> en cada fila para describir su contenido"],"correcta":0,"explicacion":"En tablas sencillas basta con scope; en las complejas se usan id y headers."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Cuál de estos atributos NO es un mecanismo de validación de formularios en el lado cliente?","opciones":["placeholder","required","maxlength","pattern"],"correcta":0,"explicacion":"placeholder solo muestra un texto de ayuda; required, pattern, maxlength, min/max y type=\"email\" validan."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Qué elementos permiten crear un desplegable sin JavaScript?","opciones":["<details> y <summary>","<menu> y <li>","<dialog> y <button>","<select> y <optgroup>"],"correcta":0,"explicacion":"<details> crea un bloque desplegable y <summary> define su encabezado visible; funciona solo con HTML, sin JavaScript. <dialog> es una ventana de diálogo, no un desplegable."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Qué ocurre con el valor del atributo id dentro de un documento?","opciones":["Solo puede usarse en elementos <div>","Debe ser único en todo el documento","Solo puede contener números","Puede repetirse en varios elementos"],"correcta":1,"explicacion":"El atributo global id asigna un identificador único: su valor no puede repetirse en el documento. Para agrupar varios elementos se usa class, que sí puede repetirse."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Cuál es el uso correcto de las tablas en HTML?","opciones":["Crear menús horizontales alineados","Centrar contenido en la pantalla","Representar datos tabulares","Maquetar la página en columnas"],"correcta":2,"explicacion":"Las tablas deben representar datos tabulares (filas y columnas de datos), nunca maquetar la página. Maquetar con tablas es una barrera de accesibilidad: los lectores de pantalla las leen como datos."},
  {"origen":"ia","tema":"T2 · HTML5","pregunta":"¿Qué representa el elemento <hr>?","opciones":["El final del documento o la sección","Una línea decorativa sin significado","Un salto de línea dentro de un párrafo","Una ruptura temática entre bloques"],"correcta":3,"explicacion":"<hr> representa una ruptura temática entre bloques de contenido (un cambio de tema o de escena). Suele verse como una línea, pero tiene significado semántico y no debe usarse solo como decoración."},
  // T3 · Lenguajes de presentación
  {"origen":"ia","tema":"T3 · Lenguajes de presentación","pregunta":"En un sitio web, ¿qué describe cada tecnología?","opciones":["HTML el contenido y CSS la presentación","HTML la presentación y CSS el contenido","Ambos describen solo el contenido","CSS el contenido y la presentación a la vez"],"correcta":0,"explicacion":"HTML define la información (títulos, párrafos, tablas…) y CSS cómo se muestra (colores, fuentes, disposición…)."},
  {"origen":"ia","tema":"T3 · Lenguajes de presentación","pregunta":"¿Cuál de estas NO es una ventaja de separar contenido y presentación?","opciones":["Facilita la adaptación a dispositivos","Facilita el mantenimiento del sitio","Aumenta la duplicación de código","Mejora la accesibilidad del sitio"],"correcta":2,"explicacion":"Separar contenido y presentación reduce la duplicación de código, además de permitir reutilizar contenido."},
  {"origen":"ia","tema":"T3 · Lenguajes de presentación","pregunta":"En CSS se habla de…","opciones":["Ediciones anuales que se publican cada diciembre","Niveles, y cada uno es un superconjunto del anterior","Versiones, y cada una sustituye a la anterior","Releases independientes e incompatibles entre sí"],"correcta":1,"explicacion":"Cada nivel se construye sobre el anterior refinando definiciones y añadiendo características."},
  {"origen":"ia","tema":"T3 · Lenguajes de presentación","pregunta":"¿Qué permitía controlar CSS Level 1 (recomendación de diciembre de 1996)?","opciones":["Posicionamiento y tipos de medios","Flexbox, Grid y media queries","Animaciones, transiciones y efectos","Colores, tipografía y márgenes"],"correcta":3,"explicacion":"CSS Level 1 (diciembre de 1996) fue el primer estándar CSS y permitía controlar colores, tipografía y márgenes. El posicionamiento y los tipos de medios llegaron con CSS2; Flexbox, Grid y las animaciones son módulos de CSS3."},
  {"origen":"ia","tema":"T3 · Lenguajes de presentación","pregunta":"¿Qué novedades trajo CSS Level 2 (1998)?","opciones":["Una arquitectura modular con módulos independientes","Solo cambios de colores, tipografía y márgenes","Los niveles 4 de módulos como Selectors y Color","Posicionamiento, nuevos tipos de medios y más diseño"],"correcta":3,"explicacion":"CSS Level 2 (1998) añadió el posicionamiento, nuevos tipos de medios y más posibilidades de diseño. La arquitectura modular es de CSS3."},
  {"origen":"ia","tema":"T3 · Lenguajes de presentación","pregunta":"¿Cuál es el estado de CSS 2.1 y CSS 2.2?","opciones":["Ambos son recomendaciones del W3C desde el año 2011","CSS 2.1 es recomendación (2011) y CSS 2.2 es borrador","Ninguno de los dos llegó a publicarse oficialmente","CSS 2.1 es borrador (2016) y CSS 2.2 es recomendación"],"correcta":1,"explicacion":"CSS 2.1 (revisión 1 de CSS2) es recomendación (REC) desde 2011; CSS 2.2 (revisión 2) se quedó en borrador de trabajo (Working Draft) en 2016."},
  {"origen":"ia","tema":"T3 · Lenguajes de presentación","pregunta":"En CSS Level 3, un módulo que NO existía en CSS 2.1 empieza en el nivel…","opciones":["4","0","3","1"],"correcta":3,"explicacion":"Los módulos nuevos empiezan en el nivel 1; los que actualizan algo de CSS 2.1 empiezan en el nivel 3."},
  {"origen":"ia","tema":"T3 · Lenguajes de presentación","pregunta":"Sobre CSS Level 4 se puede decir:","opciones":["Es la recomendación del W3C publicada en el año 2016","Es el nuevo núcleo que ha sustituido a CSS 2.1","No existe como tal: son módulos que alcanzan el nivel 4","Es la versión monolítica actual que agrupa todo CSS"],"correcta":2,"explicacion":"No hay un «CSS4» monolítico. CSS3 se divide en módulos que evolucionan por separado y algunos llegan al nivel 4, como Selectors Level 4 o CSS Color Level 4."},
  {"origen":"ia","tema":"T3 · Lenguajes de presentación","pregunta":"¿Qué especificación usa CSS3 como núcleo (core)?","opciones":["CSS2.1","CSS2.2","HTML5","CSS1"],"correcta":0,"explicacion":"CSS3 se construye módulo a módulo sobre CSS 2.1 y no debe contradecirlo."},
  {"origen":"ia","tema":"T3 · Lenguajes de presentación","pregunta":"El principio de diseño de CSS «independiente de dispositivo, plataforma o agente» significa que:","opciones":["Un mismo documento puede verse en ordenadores, tabletas y móviles","Los estilos se incrustan en el contenido para que viajen con él","Cada dispositivo necesita su propia versión del documento HTML","La hoja de estilos se adapta a un único navegador concreto"],"correcta":0,"explicacion":"Independencia de dispositivo, plataforma o agente significa que un mismo documento puede visualizarse en ordenadores, tabletas y móviles sin tener que reescribir su HTML."},
  // T4 · CSS
  {"origen":"ia","tema":"T4 · CSS","pregunta":"¿Cuál es la principal ventaja de las hojas de estilo externas frente a las internas y los estilos en línea?","opciones":["Tienen siempre más especificidad que los estilos internos y en línea","Reutilizan estilos, facilitan el mantenimiento y separan presentación","Se aplican más rápido porque afectan solo a un elemento concreto","No necesitan ningún elemento para enlazarse con el documento HTML"],"correcta":1,"explicacion":"Además, el navegador guarda la hoja externa en caché tras la primera descarga."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"¿Qué inconveniente tienen los estilos en línea (atributo style)?","opciones":["Solo funcionan en documentos XML y no en HTML","Afectan a todo el documento y no se pueden limitar","Son poco reutilizables y de difícil mantenimiento","No los soporta ningún navegador moderno actual"],"correcta":2,"explicacion":"Los estilos en línea (atributo style) afectan solo a ese elemento: son rápidos de aplicar, pero no se reutilizan y dificultan el mantenimiento porque el estilo queda repartido por el HTML."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"¿Cómo se asocia una hoja de estilo CSS a un documento XML?","opciones":["<?xml-stylesheet type=\"text/css\" href=\"estilo.css\"?>","<!DOCTYPE xml STYLESHEET \"estilo.css\">","<style src=\"estilo.css\" type=\"text/css\"></style>","<link rel=\"stylesheet\" type=\"text/css\" href=\"estilo.css\">"],"correcta":0,"explicacion":"En XML la hoja de estilos se asocia con una instrucción de procesamiento en el prólogo: <?xml-stylesheet type=\"text/css\" href=\"estilo.css\"?>. <link> es un elemento de HTML."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"En la regla h2 { color: green; }, ¿qué es «color: green;»?","opciones":["La declaración","El selector","El valor","La propiedad"],"correcta":0,"explicacion":"h2 es el selector; color: green; es la declaración, formada por la propiedad (color) y el valor (green)."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"Según la «regla del reloj», padding: 2em 3em; aplica…","opciones":["2em a izquierda y derecha, 3em arriba y abajo","2em en todos los lados y 3em de margen extra","2em arriba y 3em abajo, sin relleno lateral","2em arriba y abajo, 3em a derecha e izquierda"],"correcta":3,"explicacion":"Con 4 valores: arriba, derecha, abajo, izquierda (sentido de las agujas). Con 2: vertical y horizontal."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"Al agrupar selectores (h1, h2, h3 { … }), ¿qué ocurre si uno de ellos no es válido?","opciones":["Se ignora solo ese selector","El navegador corrige el selector","Se aplica a todos los elementos","No se aplica la regla"],"correcta":3,"explicacion":"Todos los selectores de la lista deben ser válidos para que la regla se aplique."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"¿Con qué carácter empieza un selector de clase y uno de identificador?","opciones":["Clase con * e identificador con @","Clase con : e identificador con ::","Clase con . e identificador con #","Clase con # e identificador con ."],"correcta":2,"explicacion":"El selector de clase empieza por punto (.destacado) y puede aplicarse a varios elementos; el de identificador empieza por almohadilla (#principal) y se refiere a un único elemento."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"¿Qué selecciona a[href^=\"https\"]?","opciones":["Enlaces cuyo href es exactamente https","Enlaces cuyo href empieza por https","Enlaces cuyo href contiene https","Enlaces cuyo href termina por https"],"correcta":1,"explicacion":"^= empieza por, $= termina por, *= contiene."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"¿Qué diferencia hay entre «section p» y «section > p»?","opciones":["El primero selecciona todos los p descendientes; el segundo, solo los hijos directos","El segundo selecciona el p que va justo después de section, como hermano adyacente","Ninguna: los dos selectores son equivalentes y seleccionan exactamente los mismos p","El primero selecciona solo los hijos directos; el segundo, todos los p descendientes"],"correcta":0,"explicacion":"El espacio («section p») es el combinador descendiente: selecciona todos los p dentro de section a cualquier profundidad. «section > p» solo selecciona los p que son hijos directos."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"¿Qué selecciona h2 + p?","opciones":["Los elementos p que están dentro de un h2","El p que va justo después de un h2, como hermano adyacente","Todos los p que son hermanos posteriores de un h2","El h2 que aparece inmediatamente después de un p"],"correcta":1,"explicacion":"+ es hermano adyacente; ~ es hermano general (todos los hermanos posteriores)."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"¿Qué pseudoclase selecciona un elemento mientras el puntero está sobre él?","opciones":[":active",":visited",":hover",":focus"],"correcta":2,"explicacion":":hover se activa cuando el puntero está sobre el elemento. :focus es cuando el elemento tiene el foco, :active mientras se está pulsando y :visited para enlaces ya visitados."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"¿Qué diferencia hay entre :is() y :where()?","opciones":["Ninguna: son sinónimos y suman la especificidad de todos los selectores",":where() toma la especificidad del más específico de la lista; :is() vale 0",":is() solo admite un selector y :where() admite una lista de selectores",":is() toma la especificidad del más específico de la lista; :where() vale 0"],"correcta":3,"explicacion":":is() agrupa selectores y toma la especificidad del más específico de la lista (p. ej. :is(li, .aviso, #contenedor) vale 100). :where() agrupa igual pero aporta especificidad 000."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"¿Qué selecciona article:has(img)?","opciones":["Las imágenes que están dentro de un article","El primer img de cada elemento article","Los article que contienen una imagen","Los article que no contienen imágenes"],"correcta":2,"explicacion":":has() selecciona elementos que contienen a otros: article:has(img) selecciona los article que tienen alguna imagen dentro, no las imágenes."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"¿Cuáles son los tres criterios de ordenación de la cascada, por orden?","opciones":["Origen e importancia, especificidad y orden de aparición","Especificidad, herencia y orden de aparición en la hoja","Orden de aparición, origen de la hoja y herencia del padre","Herencia, especificidad y valores iniciales de la propiedad"],"correcta":0,"explicacion":"La cascada ordena las declaraciones en conflicto por: 1) origen e importancia, 2) especificidad del selector y 3) orden de aparición. La herencia solo actúa cuando no hay ninguna declaración para esa propiedad."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"¿Cuál es la especificidad del selector «ul ol li.aviso»?","opciones":["031","013","004","103"],"correcta":1,"explicacion":"a=0 (ningún id), b=1 (una clase), c=3 (tres selectores de tipo) → 013."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"¿Cuál es la especificidad de #principal?","opciones":["000","010","100","001"],"correcta":2,"explicacion":"La especificidad se calcula como abc: a = número de id, b = clases, atributos y pseudoclases, c = tipos y pseudoelementos. #principal tiene un id, así que vale 100."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"¿Qué especificidad tiene el selector universal *?","opciones":["100","001","010","000"],"correcta":3,"explicacion":"El selector universal se ignora en el cálculo."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"Si dos declaraciones tienen el mismo origen, importancia y especificidad, ¿cuál se aplica?","opciones":["La que aparece en último lugar","La de la hoja del navegador","La que aparece en primer lugar","Ninguna: se produce un error"],"correcta":0,"explicacion":"Si el origen, la importancia y la especificidad son iguales, gana la declaración que aparece en último lugar (orden de aparición)."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"¿Qué dicen los apuntes sobre !important?","opciones":["Solo funciona en las hojas de estilo definidas por el usuario","Altera el orden de la cascada y debe evitarse en lo posible","No afecta a la cascada, solo a la herencia de propiedades","Debe usarse siempre para asegurar que se aplica el estilo"],"correcta":1,"explicacion":"!important altera el orden normal de la cascada e invierte la precedencia por origen. Los apuntes recomiendan evitarlo y resolver los conflictos aplicando bien la cascada y la especificidad."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"¿Qué valor hereda un elemento cuando una propiedad es heredable?","opciones":["El valor declarado de la propiedad en su elemento padre","El valor que fija la hoja de estilos del navegador","El valor inicial que define la especificación de CSS","El valor computado de la propiedad en su elemento padre"],"correcta":3,"explicacion":"Una propiedad heredable toma el valor computado (ya calculado) que tiene esa propiedad en el elemento padre, no el valor declarado. Por ejemplo, un em ya se ha convertido a px."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"¿Cuáles son las cuatro áreas del modelo de caja, de dentro hacia fuera?","opciones":["Contenido, borde, relleno (padding), margen","Margen, borde, relleno (padding), contenido","Contenido, relleno (padding), borde, margen","Relleno (padding), contenido, borde, margen"],"correcta":2,"explicacion":"De dentro hacia fuera: contenido (width/height), relleno o padding (espacio entre contenido y borde), borde y margen (espacio exterior que separa de otras cajas)."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"Con html { font-size: 16px } y body { font-size: 20px }, ¿qué tamaño tiene un h1 con font-size: 2rem dentro de body?","opciones":["40px","32px","36px","20px"],"correcta":1,"explicacion":"rem se calcula sobre el elemento raíz (html): 2 × 16 = 32px. Con 2em sería 2 × 20 = 40px."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"¿Cuál de estas unidades es relativa?","opciones":["cm","pt","px","vw"],"correcta":3,"explicacion":"vw es el 1% del ancho del viewport. Las unidades relativas facilitan la adaptabilidad."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"¿Cómo se declara y usa una variable CSS (custom property)?","opciones":["let color = navy; y color: color(color);","@var color = navy; y color: @color;",":root { --color: navy; } y color: var(--color);","$color: navy; y después color: $color;"],"correcta":2,"explicacion":"Las custom properties se declaran con dos guiones, normalmente en :root (--color-principal: navy;), y se usan con var(--color-principal). $ es de Sass y @ de Less, no de CSS estándar."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"Según las buenas prácticas, si un navegador no soporta un valor de una declaración, debe…","opciones":["Usar el valor soportado más parecido","Ignorar toda la declaración","Mostrar un aviso de error al usuario","Aplicar solo la parte que entiende"],"correcta":1,"explicacion":"Según las buenas prácticas de CSS, si un valor no es válido o no está soportado, el navegador debe ignorar toda la declaración, sin ser selectivo."},
  {"origen":"ia","tema":"T4 · CSS","pregunta":"¿Qué son propiedades como -moz-border-radius?","opciones":["Variables CSS definidas por el navegador","Pseudoelementos específicos de Mozilla","Propiedades estándar del módulo CSS3","Extensiones propietarias de un proveedor"],"correcta":3,"explicacion":"Los prefijos como -moz-, -webkit- o -ms- marcan extensiones propietarias de un proveedor (vendor-specific), pensadas para un único navegador y no estandarizadas."},
  // T5 · CSS: posicionamiento y maquetación
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"¿Qué caracteriza a un elemento de bloque como <p> o <section>?","opciones":["Ocupa todo el ancho disponible y empieza en una nueva línea","Ocupa solo el espacio necesario y sigue en la misma línea","No genera ninguna caja hasta que se le da un tamaño","Siempre está fuera del flujo normal del documento"],"correcta":0,"explicacion":"Los elementos de línea (<a>, <img>) ocupan solo lo necesario y continúan en la misma línea."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"¿Qué hace display: inline-block?","opciones":["Convierte el elemento en un contenedor flex en línea","Oculta el elemento pero mantiene el espacio que ocupa","Genera una caja de bloque que fluye como una en línea","Genera varias cajas de línea, una por cada palabra"],"correcta":2,"explicacion":"inline-block genera una caja de bloque (admite width, height y márgenes verticales) que fluye en la línea como un elemento en línea, junto a otros."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"¿Qué hace display: none?","opciones":["Lo convierte en un elemento en línea","El elemento no genera ninguna caja","Lo saca del flujo como position: absolute","Lo hace transparente pero ocupa su espacio"],"correcta":1,"explicacion":"display: none hace que el elemento no genere ninguna caja: no se ve y no ocupa espacio. Para ocultar algo manteniendo su hueco se usaría visibility: hidden."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"¿Cuál es el valor por defecto de la propiedad position?","opciones":["static","absolute","fixed","relative"],"correcta":0,"explicacion":"static sigue el flujo normal e ignora top, right, bottom y left."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"Sobre position: relative se puede decir:","opciones":["Conserva su hueco en el flujo y se desplaza visualmente","Se queda fijo respecto a la pantalla al hacer scroll","Ignora las propiedades top, right, bottom y left","Sale del flujo normal y no reserva ningún espacio"],"correcta":0,"explicacion":"position: relative mantiene el espacio original del elemento en el flujo y lo desplaza visualmente con top, right, bottom y left. Además sirve como bloque contenedor de los hijos con position: absolute."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"Un elemento con position: absolute dentro de un padre con position: relative se posiciona respecto a…","opciones":["La ventana del navegador (viewport)","Su posición normal dentro del flujo","El elemento <body> en todos los casos","Ese elemento padre posicionado"],"correcta":3,"explicacion":"Si está dentro de otro elemento posicionado, ése es su bloque contenedor; si no, suele ser el elemento raíz."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"¿Qué valor de position mantiene el elemento en el flujo normal y, al hacer scroll y alcanzar una posición, lo deja visible como si fuera fijo?","opciones":["absolute","fixed","sticky","static"],"correcta":2,"explicacion":"sticky se comporta como relative (sigue en el flujo) hasta que, al hacer scroll, alcanza la posición indicada (p. ej. top: 0); entonces se queda fijo dentro de su contenedor. Es muy habitual en barras de navegación."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"¿Cuál es el bloque contenedor de un elemento con position: fixed?","opciones":["El primer ancestro con relative","Su elemento padre directo","El elemento raíz <html>","La pantalla (viewport)"],"correcta":3,"explicacion":"Con position: fixed el bloque contenedor es la pantalla (viewport): el elemento queda fijo aunque se haga scroll. Se usa en menús superiores y botones de ayuda."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"¿Para qué NO se recomienda la propiedad position según los apuntes?","opciones":["Hacer menús fijos que no se mueven con el scroll","Estructurar la página completa o crear columnas","Colocar etiquetas o iconos encima de imágenes","Crear cabeceras adhesivas que siguen al hacer scroll"],"correcta":1,"explicacion":"Para la estructura de la página y las columnas se recomienda Flexbox y Grid."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"¿Qué dicen los apuntes sobre float para construir layouts?","opciones":["Es la técnica recomendada actualmente para columnas","Es obligatoria para centrar elementos verticalmente","Es histórica: hoy se recomiendan Flexbox y Grid","Solo funciona si se combina siempre con clear: both"],"correcta":2,"explicacion":"float se usó durante años para maquetar, pero los apuntes lo consideran histórico y no recomendado: para construir layouts se usan Flexbox y Grid."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"Flexbox es un sistema de diseño…","opciones":["Unidimensional (una fila o una columna)","Bidimensional (filas y columnas a la vez)","Pensado solo para elementos con position absolute","Pensado solo para maquetar tablas de datos"],"correcta":0,"explicacion":"Flexbox organiza elementos en una única dimensión: una fila o una columna. Para trabajar filas y columnas a la vez (dos dimensiones) se usa Grid."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"En Flexbox, ¿qué propiedad alinea los elementos sobre el eje principal?","opciones":["flex-wrap","align-items","justify-content","gap"],"correcta":2,"explicacion":"justify-content trabaja en el eje principal y align-items en el transversal."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"¿Cuál es el valor por defecto de flex-direction?","opciones":["row","wrap","row-reverse","column"],"correcta":0,"explicacion":"flex-direction es row por defecto, así que los elementos flex se colocan en fila. Con column se apilan en vertical."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"¿Qué diferencia hay entre gap y margin?","opciones":["gap pertenece al elemento; margin, al contenedor flex o grid","margin pertenece al elemento; gap, al contenedor flex o grid","margin solo funciona en Grid y gap solo en elementos de bloque","Son equivalentes y se pueden intercambiar en cualquier caso"],"correcta":1,"explicacion":"margin es una propiedad de cada elemento; gap pertenece al contenedor flex o grid y define la separación entre sus elementos. Es una abreviatura de row-gap y column-gap."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"¿Qué significa grid-template-columns: 1fr 2fr 1fr?","opciones":["Tres columnas que se reparten el espacio (25%, 50% y 25%)","Tres filas cuya altura es proporcional a 1, 2 y 1","Tres columnas fijas de 1, 2 y 1 píxeles de ancho","Una única columna que se repite tres veces seguidas"],"correcta":0,"explicacion":"fr es una fracción del espacio disponible: 1fr + 2fr + 1fr = 4 partes, así que las columnas se reparten aproximadamente 25%, 50% y 25%."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"¿Qué hace header { grid-column: 1 / -1; }?","opciones":["Lo oculta porque -1 indica una columna que no existe","Lo coloca en la primera columna y lo saca de la última fila","Lo coloca en la última fila del grid, debajo del contenido","Hace que ocupe todo el ancho, de la primera a la última línea"],"correcta":3,"explicacion":"grid-column es la abreviatura de grid-column-start / grid-column-end. Con 1 / -1 el elemento va de la primera a la última línea de columna, es decir, ocupa todo el ancho."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"En grid-template-areas, ¿qué indica repetir un nombre en una fila (\"cabecera cabecera\")?","opciones":["Que hay dos elementos header","Que hay un error de sintaxis","Que esa área ocupa varias celdas","Que la fila completa se repite"],"correcta":2,"explicacion":"En grid-template-areas cada cadena es una fila y cada palabra una celda. Repetir el mismo nombre indica que esa área ocupa varias celdas, por ejemplo una cabecera que ocupa dos columnas."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"¿Qué diferencia hay entre auto-fill y auto-fit en repeat()?","opciones":["auto-fill solo funciona con filas y auto-fit solo con columnas en el grid","auto-fill reserva espacio para columnas vacías; auto-fit las quita y reparte el hueco","Ninguna: son sinónimos y producen exactamente el mismo número de columnas","auto-fit reserva espacio para columnas vacías; auto-fill las quita y reparte el hueco"],"correcta":1,"explicacion":"Ambos crean tantas columnas como quepan. auto-fill mantiene las columnas vacías y reserva su espacio; auto-fit las elimina y reparte el espacio libre entre las que tienen contenido."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"¿Para qué sirve minmax(200px, 1fr)?","opciones":["Fija la columna en 200px exactos aunque sobre espacio","Establece el número máximo de columnas que caben","Define un tamaño mínimo y máximo para una fila o columna","Define la separación mínima y máxima entre columnas"],"correcta":2,"explicacion":"minmax(min, max) define un rango de tamaños para una fila o columna: con minmax(200px, 1fr) la columna nunca baja de 200px y puede crecer hasta una fracción del espacio. Es clave en diseños adaptables."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"Según la «regla de oro» de los apuntes, ¿cómo se combinan Grid y Flexbox?","opciones":["Grid para la estructura general y Flexbox para los componentes","Nunca deben combinarse en la misma página para evitar conflictos","Grid solo para tablas de datos y Flexbox para todo lo demás","Flexbox para la estructura general y Grid para los componentes"],"correcta":0,"explicacion":"La regla de oro es: HTML semántico para el contenido, Grid para la estructura general de la página (dos dimensiones), Flexbox para organizar componentes en una dimensión y media queries para adaptar. Se combinan."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"¿Qué enfoque representa este código? main { grid-template-columns: 1fr; } @media (min-width: 768px) { main { grid-template-columns: repeat(3, 1fr); } }","opciones":["Posicionamiento absoluto","Desktop first","Diseño fijo","Mobile first"],"correcta":3,"explicacion":"Primero se define el diseño para móvil y con min-width se adapta a pantallas mayores."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"¿Qué es un breakpoint en media queries?","opciones":["Un error de CSS que detiene el renderizado","La última línea de columna de un grid","Un punto en el que se rompe el flujo normal","El ancho a partir del cual cambian los estilos"],"correcta":3,"explicacion":"Un breakpoint es el ancho de pantalla a partir del cual cambian los estilos, por ejemplo @media (max-width: 768px). En los apuntes: 768px para móviles y 1024px para tabletas."},
  {"origen":"ia","tema":"T5 · CSS: posicionamiento y maquetación","pregunta":"¿Qué propiedades agrupa la propiedad abreviada grid-template?","opciones":["grid-row-start, grid-row-end, grid-column-start y grid-column-end","gap, row-gap y column-gap para la separación entre celdas","justify-items, align-items y place-items del contenedor grid","grid-template-rows, grid-template-columns y grid-template-areas"],"correcta":3,"explicacion":"grid-template es la abreviatura que define en una sola instrucción las filas (grid-template-rows), las columnas (grid-template-columns) y las áreas (grid-template-areas)."},
  // T6 · Diseño con estándares
  {"origen":"ia","tema":"T6 · Diseño con estándares","pregunta":"¿Quién creó la Web, cuándo y dónde?","opciones":["Marc Andreessen, en 1993, en el NCSA","Vint Cerf, en 1969, en ARPANET","Tim Berners-Lee, en 1989, en el CERN","Tim Berners-Lee, en 1994, en el MIT"],"correcta":2,"explicacion":"Internet empieza en los años 60, pero la Web la inventa Tim Berners-Lee en 1989 en el CERN."},
  {"origen":"ia","tema":"T6 · Diseño con estándares","pregunta":"¿Cuáles son los cuatro componentes esenciales de la Web que creó Berners-Lee?","opciones":["TCP, IP, DNS y el protocolo HTTP","HTML, HTTP, un servidor web y un navegador","HTML, CSS, JavaScript y un servidor web","XML, XSLT, XPath y un navegador"],"correcta":1,"explicacion":"Tim Berners-Lee creó en el CERN las versiones iniciales de HTML, HTTP, un servidor web y un navegador: los cuatro componentes esenciales de la Web."},
  {"origen":"ia","tema":"T6 · Diseño con estándares","pregunta":"¿Qué es un cliente web?","opciones":["Cualquier dispositivo con navegador que pide y muestra documentos web","La persona o empresa que encarga el desarrollo del sitio","Solo un ordenador de sobremesa con un navegador instalado","El servidor que aloja y envía las páginas del sitio web"],"correcta":0,"explicacion":"Hoy pueden ser móviles, televisiones, electrodomésticos, automóviles…"},
  {"origen":"ia","tema":"T6 · Diseño con estándares","pregunta":"¿Qué diferencia hay entre desarrollo web y diseño web?","opciones":["El diseño se hace en el servidor y el desarrollo en el cliente","El diseño implementa la funcionalidad; el desarrollo, la apariencia","El desarrollo implementa la funcionalidad; el diseño, la apariencia","Ninguna: son dos nombres distintos para el mismo trabajo"],"correcta":2,"explicacion":"El desarrollo web implementa la funcionalidad que se ejecuta en el navegador; el diseño web decide la apariencia (colores, disposición, tipografía) con énfasis en la estética y la experiencia de usuario."},
  {"origen":"ia","tema":"T6 · Diseño con estándares","pregunta":"Según los apuntes, ¿qué tecnologías pertenecen al frontend?","opciones":["Solo JavaScript y sus frameworks","HTML, CSS, XML y JavaScript","Servidores web y HTTP/HTTPS","PHP, bases de datos y servidores"],"correcta":1,"explicacion":"Backend: tecnologías del servidor (PHP). Full-Stack engloba ambos."},
  {"origen":"ia","tema":"T6 · Diseño con estándares","pregunta":"¿Cuál de estos NO es uno de los 8 estándares de diseño web de los apuntes?","opciones":["Simplicidad","Consistencia","Credibilidad","Exclusividad"],"correcta":3,"explicacion":"Son: simplicidad, jerarquía visual, navegabilidad, consistencia, capacidad de respuesta, accesibilidad, convencionalidad y credibilidad."},
  {"origen":"ia","tema":"T6 · Diseño con estándares","pregunta":"¿Cuándo y quién fundó el W3C?","opciones":["1989, el CERN","1998, la ISO","2004, Apple, Mozilla y Opera","1994, Tim Berners-Lee"],"correcta":3,"explicacion":"Tim Berners-Lee fundó el W3C (World Wide Web Consortium) en 1994, con la misión de llevar la web a su máximo potencial mediante estándares abiertos. 1989 es cuando inventa la Web en el CERN."},
  {"origen":"ia","tema":"T6 · Diseño con estándares","pregunta":"¿Cuál de estos es uno de los 5 objetivos del W3C?","opciones":["Gestionar los dominios de Internet","Vender licencias de los estándares","Proporcionar herramientas de validación","Desarrollar sus propios navegadores"],"correcta":2,"explicacion":"Los 5 objetivos: estándares web, accesibilidad, herramientas de validación, educación y divulgación, e internacionalización."},
  {"origen":"ia","tema":"T6 · Diseño con estándares","pregunta":"¿Qué organismo mantiene el estándar ECMAScript y cuál WebGL?","opciones":["W3C y WHATWG","WHATWG y ECMA","ECMA y Khronos","IETF e ISO"],"correcta":2,"explicacion":"ECMAScript (el estándar de JavaScript) lo mantiene ECMA International; WebGL y los gráficos 3D, el consorcio Khronos. HTML lo mantiene el WHATWG y la mayoría de estándares web, el W3C."},
  {"origen":"ia","tema":"T6 · Diseño con estándares","pregunta":"¿Qué significa el principio de compatibilidad «no rompas la web»?","opciones":["Que no se pueden crear tecnologías nuevas","Que solo se admiten conexiones HTTPS","Que hay que validar todas las páginas web","Que lo nuevo debe ser compatible con lo anterior"],"correcta":3,"explicacion":"«No rompas la web» significa que cualquier tecnología nueva debe ser compatible con las anteriores, para que las páginas existentes sigan funcionando."},
  {"origen":"ia","tema":"T6 · Diseño con estándares","pregunta":"¿Qué significa que los estándares web sean abiertos?","opciones":["Que son libres de usar y mejorar, sin patentes ni licencias","Que solo los pueden usar los miembros del consorcio W3C","Que su código es público, pero hay que pagar por usarlo","Que cualquier empresa puede modificarlos sin consenso"],"correcta":0,"explicacion":"Desde el inicio se acordó que la web debía ser libre: cualquiera puede crear un sitio sin pagar licencias ni patentes y cualquiera puede participar en el proceso de creación de estándares."},
  {"origen":"ia","tema":"T6 · Diseño con estándares","pregunta":"¿Cuáles son las tres capas o componentes de un sitio web?","opciones":["HTML para datos, XML para estilos y XSLT para lógica","Cliente, servidor y base de datos con sus conexiones","Estructura (HTML), presentación (CSS) y comportamiento (JS)","Diseño, desarrollo y despliegue del sitio en producción"],"correcta":2,"explicacion":"Un sitio web se divide en estructura (HTML/XML, el contenido), presentación (CSS, la apariencia) y comportamiento (ECMAScript en el cliente, PHP en el servidor)."},
  {"origen":"ia","tema":"T6 · Diseño con estándares","pregunta":"Según los apuntes, un sistema usable es…","opciones":["Con muchos colores y animaciones","Fácil de aprender y fácil de utilizar","Rápido de cargar y bonito de ver","Validado por el W3C y sin errores"],"correcta":1,"explicacion":"Un sistema usable es fácil de aprender y fácil de utilizar. La usabilidad va mucho más allá de colores y tipos de letra: diálogos, enlace cognitivo con el usuario, documentación y metáforas."},
  {"origen":"ia","tema":"T6 · Diseño con estándares","pregunta":"¿Qué es la WAI?","opciones":["La iniciativa de accesibilidad web del W3C","Un organismo de la ISO para normas web","Un validador de hojas de estilo CSS del W3C","Un lenguaje de marcado para accesibilidad"],"correcta":0,"explicacion":"La WAI (Web Accessibility Initiative) es la iniciativa del W3C para la accesibilidad web: desarrolla pautas como las WCAG, herramientas de evaluación, difusión y educación."},
  {"origen":"ia","tema":"T6 · Diseño con estándares","pregunta":"¿Qué permite garantizar el uso correcto de los estándares web?","opciones":["Solo una mejor estética y una carga más rápida de las páginas","Que no haga falta validar ni probar el sitio en dispositivos","Que la web funcione perfectamente en un navegador concreto","Compatibilidad, usabilidad, accesibilidad, seguridad y buen SEO"],"correcta":3,"explicacion":"Usar bien los estándares garantiza la compatibilidad entre dispositivos y a lo largo del tiempo, la usabilidad, la adaptabilidad, la accesibilidad, la seguridad y un buen posicionamiento en buscadores."},
  // T7 · XML: introducción
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"¿Qué significa que XML sea un metalenguaje?","opciones":["Que es un lenguaje para definir otros lenguajes","Que solo describe la presentación visual","Que tiene un conjunto fijo de etiquetas","Que es un lenguaje de programación"],"correcta":0,"explicacion":"XML es extensible: sus etiquetas no están predefinidas y sirve para crear vocabularios específicos."},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"¿Qué especifica un documento XML?","opciones":["El contenido, la estructura y la presentación","Solo la presentación visual de los datos","El contenido y la estructura, no la presentación","Solo los tipos de datos de cada elemento"],"correcta":2,"explicacion":"XML describe el contenido y su estructura (un árbol), pero no cómo se presenta. Para presentarlo se usa CSS o se transforma con XSLT."},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"Comparando DTDs y XML Schemas según los apuntes:","opciones":["Los Schemas son más breves que los DTDs y no tienen tipos","Los DTDs tienen tipos de datos y rangos, pero son más extensos","Los DTDs usan sintaxis XML y los Schemas una sintaxis propia","Los Schemas usan XML y tienen tipos, pero son más extensos"],"correcta":3,"explicacion":"Los DTDs son breves pero no tienen tipos ni rangos y abusan de las cadenas de texto."},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"¿Qué indica standalone=\"yes\" en la declaración XML?","opciones":["Que el documento puede no tener elemento raíz","Que el documento no depende de declaraciones externas","Que el documento debe validarse obligatoriamente","Que la codificación del documento es UTF-8"],"correcta":1,"explicacion":"standalone=\"yes\" indica al procesador que el documento es independiente y no depende de declaraciones externas (como un DTD externo). Con \"no\" sí depende de ellas."},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"En la declaración <?xml … ?>, ¿qué atributo es obligatorio?","opciones":["encoding","lang","version","standalone"],"correcta":2,"explicacion":"version es obligatorio; encoding (por defecto UTF-8) y standalone son opcionales."},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"En <!DOCTYPE pizzas SYSTEM \"pizzas.dtd\">, ¿qué indica SYSTEM?","opciones":["Que la DTD es privada y está en nuestro equipo","Que la DTD está incrustada dentro del documento","Que el documento usa un XML Schema en lugar de DTD","Que la DTD es pública y está disponible en la red"],"correcta":0,"explicacion":"SYSTEM indica que el DTD es privado y se carga desde la URI indicada (normalmente un archivo de nuestro equipo). PUBLIC se usa para DTDs públicos con identificador, como el de XHTML."},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"¿Cuál de estos nombres de elemento XML es válido?","opciones":["_Estudiante","-Estudiante","Estudiante 1234","1234"],"correcta":0,"explicacion":"Deben empezar por letra o «_», sin espacios; después admiten caracteres Unicode (por ejemplo «Estudianteβ»)."},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"Sobre los atributos en XML se puede decir:","opciones":["Sus valores van siempre sin comillas","No puede haber dos atributos con el mismo nombre","El orden de los atributos es significativo","Solo se admiten valores entre comillas dobles"],"correcta":1,"explicacion":"Los valores van entre comillas dobles o simples y el orden no importa."},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"¿Qué entidad predefinida representa el carácter <?","opciones":["&amp;","&lt;","&gt;","&quot;"],"correcta":1,"explicacion":"Las entidades predefinidas de XML son &lt; (<), &gt; (>), &amp; (&), &apos; (') y &quot; (\"). Se usan para escribir esos caracteres sin que se confundan con el marcado."},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"¿Qué hace el atributo predefinido xml:space=\"preserve\"?","opciones":["Indica el idioma del elemento","Define la URL base del documento","Pide mantener los espacios en blanco","Elimina los espacios sobrantes"],"correcta":2,"explicacion":"xml:space=\"preserve\" pide mantener los espacios en blanco tal cual; con \"default\" la aplicación los trata como quiera. xml:lang indica el idioma y xml:base la URL base."},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"¿Qué dos condiciones imprescindibles debe cumplir un documento XML bien formado?","opciones":["Usar la codificación ISO-8859-1 y tener comentarios","Que todos los elementos tengan al menos un atributo","Tener un DTD asociado y un XML Schema válido","Un único elemento raíz y etiquetas bien anidadas"],"correcta":3,"explicacion":"Un documento bien formado cumple la sintaxis XML: un único elemento raíz que envuelve todo y etiquetas correctamente cerradas y anidadas, sin solapamientos. No necesita DTD ni Schema (eso es ser válido)."},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"¿Qué es un documento XML válido?","opciones":["Uno guardado con la codificación de caracteres UTF-8","Cualquier documento que el navegador consigue abrir","Uno bien formado que no contiene comentarios","Uno bien formado que además cumple su DTD o Schema"],"correcta":3,"explicacion":"Todo documento válido está bien formado, pero no al revés."},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"¿Cuál de estas NO es una alternativa para validar documentos XML?","opciones":["CSS","Relax NG","DTD","XML Schema"],"correcta":0,"explicacion":"También existe Schematron."},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"¿Dónde pueden ir los comentarios en un documento XML?","opciones":["En el prólogo o el cuerpo, pero nunca dentro de etiquetas","En cualquier sitio, incluso dentro de las etiquetas","Solo dentro del elemento raíz, nunca en el prólogo","Solo al final del documento, tras el elemento raíz"],"correcta":0,"explicacion":"Los comentarios <!-- … --> pueden ir en el prólogo o en el cuerpo, pero nunca dentro de declaraciones, de etiquetas ni de otros comentarios."},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"¿Qué es SVG?","opciones":["Un lenguaje de estilos para dar formato a documentos XML","Un lenguaje derivado de XML para gráficos vectoriales 2D","Un formato de datos geográficos del OGC basado en XML","Un formato de imagen de mapa de bits (raster) del W3C"],"correcta":1,"explicacion":"SVG (Scalable Vector Graphics) es un lenguaje derivado de XML y estándar del W3C para describir gráficos vectoriales en dos dimensiones: formas, imágenes y texto."},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"¿Por qué las imágenes SVG no pierden calidad al cambiar de tamaño?","opciones":["Porque se comprimen en ZIP","Porque se crean con Inkscape","Porque son vectoriales","Porque usan muchos píxeles"],"correcta":2,"explicacion":"Los gráficos vectoriales se describen con formas matemáticas (líneas, curvas…), no con píxeles. Por eso se pueden escalar e imprimir a cualquier resolución sin perder calidad."},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"¿Qué organismo define el estándar KML?","opciones":["La ISO, como norma geográfica","Google, en exclusiva","El W3C (World Wide Web)","El Open Geospatial Consortium"],"correcta":3,"explicacion":"KML se usa en Google Earth y Google Maps, pero es un estándar del OGC."},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"¿Para qué se usa WaterML?","opciones":["Para subtítulos de películas y series","Para intercambiar datos hidrológicos","Para describir gráficos vectoriales","Para firmar documentos electrónicos"],"correcta":1,"explicacion":"WaterML es un estándar del OGC basado en XML para intercambiar datos hidrológicos, sobre todo series temporales (fecha y valor): precipitaciones, caudales, temperatura del agua…"},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"¿Qué lenguaje derivado de XML se usa para subtítulos de películas y series (promovido por Netflix)?","opciones":["TTML","WML","VoiceXML","SMIL"],"correcta":0,"explicacion":"TTML (Timed Text Markup Language) es el vocabulario XML para subtítulos de películas y series, promovido por Netflix. SMIL es para presentaciones multimedia y VoiceXML para voz."},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"¿Qué lenguaje derivado de XML sirve para visualizar ecuaciones matemáticas?","opciones":["XBRL","ebXML","P3P","MathML"],"correcta":3,"explicacion":"MathML (y también OpenMath) sirve para representar y visualizar ecuaciones matemáticas. XBRL es para contabilidad y auditoría, y ebXML para negocio electrónico."},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"¿Cuál de estos es un inconveniente de XML según los apuntes?","opciones":["Puede ocupar mucho espacio y tiempo de proceso","No es un formato abierto ni estándar","No es legible por las personas","No permite crear vocabularios específicos"],"correcta":0,"explicacion":"También es malo para datos binarios, poco eficiente para bases de datos y está siendo sustituido en muchas aplicaciones por JSON."},
  {"origen":"ia","tema":"T7 · XML: introducción","pregunta":"¿Qué diferencia hay entre modelar la información con elementos o con atributos?","opciones":["Ninguna, el árbol DOM es idéntico","Los elementos no se pueden validar","Se generan árboles DOM diferentes","Los atributos no aparecen en el DOM"],"correcta":2,"explicacion":"Guardar un dato como atributo o como elemento hijo genera árboles DOM diferentes, lo que afecta a cómo se procesa y se accede a él después."},
  // T8 · XML: DTD
  {"origen":"ia","tema":"T8 · XML: DTD","pregunta":"Sobre los DTD se puede decir:","opciones":["Fueron la primera forma de validar XML y la menos potente","Son la forma más potente de validar XML que existe","Usan sintaxis XML, igual que los esquemas XML Schema","Aparecieron después de los XML Schemas para simplificarlos"],"correcta":0,"explicacion":"Los DTD fueron históricamente la primera forma de validar XML y son la más simple y menos potente: no usan sintaxis XML y no tienen tipos de datos. Después llegó XML Schema."},
  {"origen":"ia","tema":"T8 · XML: DTD","pregunta":"¿De cuántas formas se puede vincular un DTD a un documento XML según los apuntes?","opciones":["Solo con el atributo xsi:schemaLocation del elemento raíz","Incrustado, en un archivo aparte (SYSTEM) o público (PUBLIC)","Solo incrustado en el documento, dentro de <!DOCTYPE>","Con un elemento <link> en el prólogo del documento"],"correcta":1,"explicacion":"Hay tres formas: incrustarlo en el propio documento con <!DOCTYPE raiz [ … ]>, ponerlo en un archivo aparte con SYSTEM, o usar un identificador público con PUBLIC (como el DTD de XHTML)."},
  {"origen":"ia","tema":"T8 · XML: DTD","pregunta":"¿Qué ventaja tiene colocar el DTD en un archivo aparte?","opciones":["Que ya no hace falta la declaración !DOCTYPE","Que así admite tipos de datos como xs:integer","Que se puede reutilizar para validar varios XML","Que el documento no necesita estar bien formado"],"correcta":2,"explicacion":"Un DTD externo (archivo .dtd) se puede reutilizar para validar muchos documentos XML que comparten estructura, en vez de repetirlo en cada uno."},
  {"origen":"ia","tema":"T8 · XML: DTD","pregunta":"¿Qué cuatro tipos de declaraciones puede contener un DTD?","opciones":["DOCTYPE, CDATA, PCDATA e ID","ELEMENT, ATTLIST, ENTITY y NOTATION","SEQUENCE, CHOICE, ALL y ANY","ELEMENT, TYPE, GROUP y ATTRIBUTE"],"correcta":1,"explicacion":"Un DTD puede declarar elementos (ELEMENT), listas de atributos (ATTLIST), entidades (ENTITY, parecidas a macros) y notaciones (NOTATION, para formatos no XML como imágenes)."},
  {"origen":"ia","tema":"T8 · XML: DTD","pregunta":"En <!ELEMENT libro (título, autor+, año?, precio)>, ¿cuántos autores puede tener un libro?","opciones":["Cero o uno","Uno o más","Exactamente uno","Cero o más"],"correcta":1,"explicacion":"? = 0 o 1, * = 0 o más, + = 1 o más."},
  {"origen":"ia","tema":"T8 · XML: DTD","pregunta":"¿Qué indica <!ELEMENT servicio (domicilio | restaurante)>?","opciones":["Que está vacío y no admite elementos hijos","Que ambos elementos son opcionales","Que contiene domicilio y después restaurante","Que contiene domicilio o restaurante (uno de los dos)"],"correcta":3,"explicacion":"| indica alternativa y , indica secuencia."},
  {"origen":"ia","tema":"T8 · XML: DTD","pregunta":"¿Qué indica #PCDATA en la declaración de un elemento?","opciones":["Que el contenido son datos binarios codificados","Que el contenido es solo texto, sin elementos hijos","Que puede tener cualquier contenido, como ANY","Que el elemento está vacío, como EMPTY"],"correcta":1,"explicacion":"#PCDATA significa que el elemento contiene solo texto (parsed character data), sin elementos anidados. Vacío es EMPTY y cualquier contenido es ANY."},
  {"origen":"ia","tema":"T8 · XML: DTD","pregunta":"¿Qué recomiendan los apuntes sobre el contenido ANY?","opciones":["Solo se puede usar en declaraciones de atributos","Usarlo siempre porque da más flexibilidad","Mejor no usarlo y estructurar bien los documentos","Es obligatorio en el elemento raíz del documento"],"correcta":2,"explicacion":"ANY permite cualquier contenido, así que apenas valida nada. Los apuntes recomiendan no usarlo y estructurar bien los documentos."},
  {"origen":"ia","tema":"T8 · XML: DTD","pregunta":"¿Qué tipo de contenido es <!ELEMENT parrafo (#PCDATA|enfasis)*>?","opciones":["Mixto: texto mezclado con subelementos","ANY: cualquier contenido sin restricción","Solo elementos, sin texto entre ellos","EMPTY: el elemento no tiene contenido"],"correcta":0,"explicacion":"(#PCDATA|enfasis)* es contenido mixto: texto mezclado con subelementos <enfasis>, en cualquier orden y cantidad."},
  {"origen":"ia","tema":"T8 · XML: DTD","pregunta":"En una declaración ATTLIST, ¿qué significa #IMPLIED?","opciones":["Es un identificador único en el documento","Tiene un valor constante que no cambia","Es obligatorio y no tiene valor por defecto","Es opcional y no toma valor por defecto"],"correcta":3,"explicacion":"#REQUIRED = obligatorio, #IMPLIED = opcional, #FIXED = constante."},
  {"origen":"ia","tema":"T8 · XML: DTD","pregunta":"¿Qué tipo de atributo exige un valor único en el documento que puede ser referenciado desde otro atributo?","opciones":["IDREF","ID","CDATA","NMTOKEN"],"correcta":1,"explicacion":"ID declara un nombre único; IDREF apunta a un ID existente (permite hipervínculos en un documento)."},
  {"origen":"ia","tema":"T8 · XML: DTD","pregunta":"Sobre el tipo de atributo NMTOKEN se puede decir:","opciones":["Debe empezar siempre por una letra o por un subrayado","Admite letras, números, puntos y guiones, sin espacios","Admite espacios en blanco en medio del valor","Es una lista de valores separados por comas"],"correcta":1,"explicacion":"NMTOKENS es una lista de NMTOKEN separados por espacios."},
  {"origen":"ia","tema":"T8 · XML: DTD","pregunta":"¿Qué declara <!ATTLIST mensaje prioridad (normal | urgente) normal>?","opciones":["Un atributo enumerado con valor por defecto «normal»","Dos elementos hijos de mensaje: normal y urgente","Una entidad llamada prioridad con dos valores","Un atributo CDATA obligatorio con valor «normal»"],"correcta":0,"explicacion":"Declara en el elemento mensaje un atributo prioridad de tipo enumerado: solo admite \"normal\" o \"urgente\", y si no se indica toma por defecto \"normal\"."},
  {"origen":"ia","tema":"T8 · XML: DTD","pregunta":"Una entidad general interna como <!ENTITY ovni \"Objeto Volador No Identificado\"> se usa en el documento como…","opciones":["&ovni;","#ovni","%ovni;","<ovni/>"],"correcta":0,"explicacion":"Las entidades generales se referencian con &nombre; y las de parámetro con %nombre; (dentro del DTD)."},
  {"origen":"ia","tema":"T8 · XML: DTD","pregunta":"¿Para qué sirven las notaciones (<!NOTATION>) en un DTD?","opciones":["Para definir tipos de datos numéricos en el DTD","Para escribir comentarios y anotaciones en el DTD","Para declarar espacios de nombres del documento","Para indicar el formato de entidades externas no XML"],"correcta":3,"explicacion":"Con NDATA se asocia una entidad a una notación, p. ej. gif → image/gif."},
  {"origen":"ia","tema":"T8 · XML: DTD","pregunta":"¿Qué problema resuelven los espacios de nombres en XML?","opciones":["La codificación de caracteres especiales del documento","La validación de los tipos de datos de cada elemento","La homonimia: etiquetas iguales con distinto significado","El rendimiento del parser al procesar archivos grandes"],"correcta":2,"explicacion":"Los espacios de nombres resuelven la homonimia: etiquetas con el mismo nombre pero distinto significado (<capital> de un país frente a <capital> de una inversión). Cada nombre se asocia a una URI."},
  {"origen":"ia","tema":"T8 · XML: DTD","pregunta":"¿Qué función tienen las URIs en los espacios de nombres?","opciones":["Definen el tipo de dato de cada elemento","Son enlaces que el parser descarga","Solo sirven para que el nombre sea único","Indican dónde se encuentra el DTD"],"correcta":2,"explicacion":"La URI de un espacio de nombres solo sirve para que el nombre sea único globalmente. No es un enlace que se descargue ni tiene que contener información."},
  {"origen":"ia","tema":"T8 · XML: DTD","pregunta":"¿Qué nombres NO puede tener un prefijo de espacio de nombres?","opciones":["xsl y xs","b y bolsa","ns y geo","xmlns y xml"],"correcta":3,"explicacion":"Los prefijos xmlns y xml están reservados por el propio XML, así que no se pueden usar como alias de un espacio de nombres."},
  {"origen":"ia","tema":"T8 · XML: DTD","pregunta":"¿Cómo se declara un espacio de nombres por defecto (sin alias)?","opciones":["xmlns:default=\"…\"","xml:ns=\"…\"","xmlns=\"…\"","namespace=\"…\""],"correcta":2,"explicacion":"Con xmlns=\"URI\" (sin prefijo) se declara un espacio de nombres por defecto, que se aplica a los elementos sin prefijo en su ámbito. Con xmlns:alias=\"URI\" se declara uno con prefijo."},
  {"origen":"ia","tema":"T8 · XML: DTD","pregunta":"En el proceso de validación con DTD, ¿qué se comprueba primero?","opciones":["Si tiene notaciones","Si está bien formado","Si usa UTF-8","Si es válido con su DTD"],"correcta":1,"explicacion":"Si no está bien formado: error de documento mal formado. Si lo está y tiene DTD, se comprueba si es válido."},
  // T9 · XML Schema
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Cuál de estos es un problema de los DTDs que resuelve XML Schema?","opciones":["No tienen tipos de datos y no usan sintaxis XML","No permiten validar la estructura del documento","No admiten la declaración de atributos","Son demasiado extensos y difíciles de leer"],"correcta":0,"explicacion":"Además, los DTDs no son extensibles y no los soportan muchas herramientas."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Qué extensión tienen los archivos de XML Schema?","opciones":[".xsd",".dtd",".xsl",".xsch"],"correcta":0,"explicacion":"Los esquemas XML se guardan en archivos .xsd (XML Schema Definition). .dtd es de DTD y .xsl de las hojas XSLT."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Cuál es el elemento raíz de un documento XML Schema?","opciones":["<xs:root>","<xs:element>","<xs:complexType>","<xs:schema>"],"correcta":3,"explicacion":"Normalmente con el espacio de nombres xs: = http://www.w3.org/2001/XMLSchema."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Qué atributo vincula un documento XML a un esquema SIN espacio de nombres?","opciones":["xs:targetNamespaceLocation","xsi:noNamespaceSchemaLocation","xsi:schemaLocation","xmlns:noNamespaceSchema"],"correcta":1,"explicacion":"Con espacio de nombres se usa xsi:schemaLocation=\"URI archivo.xsd\", y los espacios de nombres deben coincidir."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"Al convertir un DTD a XML Schema, el indicador * equivale a…","opciones":["minOccurs=0 maxOccurs=unbounded","minOccurs=1 maxOccurs=unbounded","minOccurs=0 maxOccurs=1","minOccurs=1 maxOccurs=1"],"correcta":0,"explicacion":"+ → min 1 / max unbounded; ? → min 0 / max 1; , → xs:sequence; | → xs:choice."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Qué es un elemento simple en XML Schema?","opciones":["Uno con elementos hijos pero sin atributos","Uno vacío que solo puede tener atributos","Uno que no tiene ningún tipo de dato asociado","Uno que solo contiene texto, sin hijos ni atributos"],"correcta":3,"explicacion":"Un elemento simple solo contiene texto (de cualquier tipo: string, integer, date…), sin elementos hijos ni atributos. Si tiene hijos o atributos es complejo."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"Por defecto, los atributos en XML Schema son…","opciones":["Obligatorios","Fijos","Opcionales","Únicos"],"correcta":2,"explicacion":"En XML Schema los atributos son opcionales por defecto; para hacerlos obligatorios se añade use=\"required\"."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Qué diferencia hay entre default y fixed en un atributo?","opciones":["default se puede cambiar; fixed, si se indica, debe coincidir","fixed se puede cambiar; default, si se indica, debe coincidir","Ninguna: los dos dan un valor por defecto que se puede cambiar","default solo vale para elementos y fixed solo para atributos"],"correcta":0,"explicacion":"default da un valor por defecto que se puede cambiar; fixed fija un valor: si no se indica se usa ese y, si se indica, debe coincidir con él."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Qué indica <duracionRuta>PT7H</duracionRuta> con tipo xs:duration?","opciones":["Es un valor incorrecto","7 meses","7 años","7 horas"],"correcta":3,"explicacion":"Formato PnYnMnDTnHnMnS: P es obligatoria y T marca el inicio de la parte de tiempo."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Qué tipo usarías para <inicioRuta>2018-10-20T12:30:00</inicioRuta>?","opciones":["xs:dateTime","xs:duration","xs:date","xs:time"],"correcta":0,"explicacion":"xs:dateTime combina fecha y hora en formato AAAA-MM-DDThh:mm:ss, con la T separando ambas partes. xs:date es solo la fecha y xs:duration un intervalo."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Cuál de estos es un tipo primitivo (no derivado) de XML Schema?","opciones":["boolean","positiveInteger","token","integer"],"correcta":0,"explicacion":"integer, positiveInteger o token son tipos derivados; string, boolean, float, double, date, duration… son primitivos."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Qué faceta restringe un valor a un conjunto cerrado de opciones (primavera, verano…)?","opciones":["pattern","whiteSpace","length","enumeration"],"correcta":3,"explicacion":"La faceta enumeration restringe el valor a una lista cerrada de opciones. pattern usa expresiones regulares, length fija la longitud y whiteSpace trata los espacios."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Qué faceta usa expresiones regulares para validar valores como un NIF?","opciones":["totalDigits","pattern","enumeration","maxLength"],"correcta":1,"explicacion":"Por ejemplo <xs:pattern value=\"\\d{7,8}[A-Z]\"/>."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Qué hace whiteSpace con value=\"collapse\"?","opciones":["Mantiene todos los espacios tal como están","Reduce cada secuencia de espacios a uno solo","Elimina todos los espacios del texto","Cambia tabuladores y saltos por espacios"],"correcta":1,"explicacion":"whiteSpace=\"collapse\" reemplaza cada secuencia de espacios en blanco por un único espacio. \"preserve\" los mantiene y \"replace\" cambia tabuladores y saltos por espacios."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Qué restricción exige que el número sea estrictamente mayor que el valor dado?","opciones":["minInclusive","minExclusive","maxExclusive","fractionDigits"],"correcta":1,"explicacion":"minExclusive exige un valor estrictamente mayor (>); minInclusive mayor o igual (≥). Las versiones max son el equivalente para el límite superior."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"Aplicada a un xs:list, ¿qué cuenta la faceta xs:length?","opciones":["El número de dígitos de cada ítem","El número de espacios separadores","El número de ítems de la lista","El número de caracteres del texto"],"correcta":2,"explicacion":"En un xs:list, xs:length no cuenta caracteres sino el número de ítems de la lista; por ejemplo, length 3 exige exactamente tres valores RGB."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Qué permite xs:union?","opciones":["Que un tipo complejo herede de dos tipos a la vez","Combinar elementos y atributos en un mismo grupo","Unir dos esquemas en un único archivo .xsd","Que un tipo acepte valores de varios tipos simples"],"correcta":3,"explicacion":"xs:union permite que un tipo acepte valores de varios tipos simples, como una nota que puede ser un número entre 0 y 10 o el texto «No presentado»."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Qué indicador de orden representa una alternativa (o-exclusiva) entre elementos?","opciones":["xs:choice","xs:all","xs:group","xs:sequence"],"correcta":0,"explicacion":"<xs:choice> representa una alternativa o-exclusiva: aparece solo uno de los elementos del grupo. <xs:sequence> exige un orden fijo y <xs:all> permite todos en cualquier orden."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Cómo se permite mezclar texto con elementos en un tipo complejo?","opciones":["Con mixed=\"true\" en xs:complexType","Con xs:any y processContents=\"lax\"","Con xs:simpleContent y xs:extension","No es posible: solo los DTD lo permiten"],"correcta":0,"explicacion":"Para mezclar texto y elementos hijos se añade mixed=\"true\" al xs:complexType; el texto puede ir en cualquier sitio entre los elementos. simpleContent es para texto con atributos, sin hijos."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Qué ventaja tienen los tipos con nombre frente a los anónimos?","opciones":["Ocupan menos espacio","No necesitan prefijo","Son más legibles","Son reutilizables"],"correcta":3,"explicacion":"Los anónimos son más legibles; los que tienen nombre se pueden reutilizar."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"Para usar un tipo derivado por extensión (p. ej. Círculo) donde se espera el tipo base (Figura), en el XML hay que indicar…","opciones":["xs:extension","xsi:nil=\"true\"","xsi:type=\"Círculo\"","abstract=\"true\""],"correcta":2,"explicacion":"Un tipo derivado puede usarse donde se espera el tipo base, pero en el documento XML hay que indicar el tipo concreto con xsi:type, por ejemplo <figura radio=\"3\" xsi:type=\"Círculo\"/>."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Qué diferencia hay entre xs:include y xs:import?","opciones":["include permite modificar los elementos incluidos","import, mismo espacio de nombres; include, distintos","include, mismo espacio de nombres; import, distintos","Ninguna: son sinónimos para incorporar esquemas"],"correcta":2,"explicacion":"xs:redefine es como include pero permite modificar lo incluido."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Qué diferencia hay entre xs:key y xs:unique?","opciones":["unique debe existir y ser único; key puede no existir","key debe existir y ser único; unique puede no existir","Ninguna: son sinónimos para marcar valores únicos","key solo se aplica a atributos y unique a elementos"],"correcta":1,"explicacion":"keyref hace referencia a una clave (como una clave externa)."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Qué permite nillable=\"true\" en un elemento?","opciones":["Que el tipo del elemento sea abstracto","Que acepte cualquier contenido, como ANY","Que el elemento sea opcional (minOccurs=0)","Que pueda ser nulo con xsi:nil=\"true\""],"correcta":3,"explicacion":"nillable=\"true\" permite que el elemento sea nulo (sin valor) marcándolo con xsi:nil=\"true\" en el XML. Nulo no es lo mismo que vacío: el elemento indica explícitamente que no hay valor."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Cuál es una limitación de XML Schema según los apuntes?","opciones":["No soporta entidades: para macros hay que usar DTDs","No usa sintaxis XML, por lo que es difícil de procesar","No soporta tipos de datos numéricos ni de fechas","No permite usar espacios de nombres en los esquemas"],"correcta":0,"explicacion":"También tiene un lenguaje de restricciones y una sensibilidad al contexto limitados."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"¿Qué elementos se usan para documentar los componentes de un esquema?","opciones":["xs:description dentro de cada tipo","xs:annotation con xs:documentation","Comentarios <!-- --> únicamente","xs:comment con el atributo lang"],"correcta":1,"explicacion":"Los esquemas se documentan con xs:annotation, que contiene xs:documentation (texto para personas) y xs:appinfo (información para otras aplicaciones)."},
  {"origen":"ia","tema":"T9 · XML Schema","pregunta":"Al generar automáticamente un XML Schema a partir de un XML, ¿qué suele haber que corregir?","opciones":["Convertirlo a DTD para que se pueda validar","Nada: el esquema generado es siempre definitivo","Ajustar los tipos: suelen salir demasiados xs:string","Quitar el prefijo xs de todos los elementos"],"correcta":2,"explicacion":"Las herramientas que generan un Schema a partir de un XML ahorran tiempo, pero suelen poner demasiados xs:string, pueden omitir elementos opcionales que no aparecían en el ejemplo y no siempre usan la codificación deseada. Hay que revisarlo."},
  // T10 · XPath
  {"origen":"ia","tema":"T10 · XPath","pregunta":"¿Qué es XPath?","opciones":["Una biblioteca de Python para analizar archivos XML","Un lenguaje de esquemas para validar documentos XML","Un vocabulario XML para transformar documentos en HTML","Una sintaxis no basada en XML para acceder a partes de un XML"],"correcta":3,"explicacion":"XPath (XML Path Language) es una sintaxis, no basada en XML, para acceder o referirse a partes de un documento XML. Es una recomendación del W3C y la usan XSLT, XML Schema (claves) y muchas bibliotecas."},
  {"origen":"ia","tema":"T10 · XPath","pregunta":"¿Qué puede devolver una expresión XPath?","opciones":["Solo un nodo, nunca un conjunto","Solo atributos de los nodos seleccionados","Nodos, o bien un string, un número o un boolean","Siempre un documento XML completo"],"correcta":2,"explicacion":"Una expresión XPath describe un camino y su resultado puede ser un conjunto de nodos o un valor: string, número (p. ej. count()) o boolean."},
  {"origen":"ia","tema":"T10 · XPath","pregunta":"¿Qué selecciona //Y?","opciones":["El nodo padre de cada elemento Y","Todos los elementos Y del documento","Los Y hijos directos del nodo actual","El atributo Y del nodo actual"],"correcta":1,"explicacion":"// busca a cualquier profundidad: //Y selecciona todos los elementos Y del documento desde la raíz. Solo Y selecciona los hijos directos del nodo actual."},
  {"origen":"ia","tema":"T10 · XPath","pregunta":"En XPath, ¿cómo se selecciona el atributo Y?","opciones":["$Y","Y()","@Y","#Y"],"correcta":2,"explicacion":"@ selecciona atributos: @Y es el atributo Y del nodo actual y libro[@id='x'] filtra los libros por su atributo id."},
  {"origen":"ia","tema":"T10 · XPath","pregunta":"¿Qué representan «..» y «.» en XPath?","opciones":["El nodo padre y el nodo actual","El primer y el último nodo","Los descendientes y los hijos","El nodo raíz y el nodo actual"],"correcta":0,"explicacion":"Como en un sistema de archivos, «..» es el nodo padre y «.» el nodo actual o de contexto."},
  {"origen":"ia","tema":"T10 · XPath","pregunta":"¿Qué selecciona X[1]?","opciones":["El último X entre sus hermanos","Los X con un atributo igual a 1","El segundo X (índice desde 0)","El primer X entre sus hermanos"],"correcta":3,"explicacion":"En XPath los índices empiezan en 1."},
  {"origen":"ia","tema":"T10 · XPath","pregunta":"¿Qué selecciona */X?","opciones":["Los X que son hijos de cualquier hijo del nodo actual","Todos los elementos X del documento, a cualquier nivel","Los elementos X que no tienen ningún elemento hijo","El elemento X que hace de raíz del documento"],"correcta":0,"explicacion":"* representa cualquier elemento hijo, así que */X selecciona los elementos X que son hijos de cualquier hijo del nodo actual (nietos llamados X)."},
  {"origen":"ia","tema":"T10 · XPath","pregunta":"¿Qué devuelve count(/biblioteca/libro)?","opciones":["La posición del último libro","El número total de libros","El primer libro de la biblioteca","La lista de títulos de los libros"],"correcta":1,"explicacion":"count() cuenta los nodos seleccionados: count(/biblioteca/libro) devuelve el número total de libros de la biblioteca."},
  {"origen":"ia","tema":"T10 · XPath","pregunta":"¿Qué expresión selecciona el segundo libro de la biblioteca?","opciones":["/biblioteca/libro[last() - 2]","/biblioteca/libro/2","/biblioteca/libro[position() = 2]","/biblioteca/libro[2nd]"],"correcta":2,"explicacion":"position() devuelve la posición del nodo, así que [position() = 2] selecciona el segundo (equivale a [2]). Las posiciones en XPath empiezan en 1."},
  {"origen":"ia","tema":"T10 · XPath","pregunta":"¿Qué selecciona //libro[contains(titulo, 'Gatsby')]/editorial?","opciones":["Los títulos que contienen «Gatsby» de cada editorial","Todas las editoriales, ordenadas por título del libro","La editorial de los libros cuyo título contiene «Gatsby»","Los libros cuya editorial contiene la palabra «Gatsby»"],"correcta":2,"explicacion":"La expresión filtra los libros cuyo título contiene «Gatsby» con contains() y después baja a su hijo editorial. El resultado es la editorial de esos libros."},
  {"origen":"ia","tema":"T10 · XPath","pregunta":"¿Qué función comprueba si el atributo id empieza por 'ISBN-978'?","opciones":["contains(@id, 'ISBN-978')","substring(@id, 'ISBN-978')","name(@id) = 'ISBN-978'","starts-with(@id, 'ISBN-978')"],"correcta":3,"explicacion":"starts-with(cadena, prefijo) comprueba si la cadena empieza por el prefijo. contains() comprobaría si lo contiene en cualquier posición."},
  {"origen":"ia","tema":"T10 · XPath","pregunta":"¿Qué hace la función normalize-space()?","opciones":["Convierte el texto a mayúsculas","Inserta espacios entre palabras","Cuenta los espacios del texto","Quita los espacios sobrantes"],"correcta":3,"explicacion":"normalize-space() elimina los espacios del principio y del final y reduce los espacios repetidos a uno solo, por ejemplo para comparar títulos sin espacios extra."},
  {"origen":"ia","tema":"T10 · XPath","pregunta":"¿Qué limitación tiene la biblioteca estándar de Python xml.etree.ElementTree con XPath?","opciones":["No funciona con archivos XML que tengan un DTD","No admite funciones como contains() ni operadores and/or","No permite seleccionar elementos por sus atributos","No permite seleccionar elementos por su nombre"],"correcta":1,"explicacion":"Para XPath completo se usa lxml, que hay que instalar."},
  {"origen":"ia","tema":"T10 · XPath","pregunta":"Al usar XML Schema con espacio de nombres, ¿cómo aparecen los elementos en las expresiones XPath de ElementTree?","opciones":["Con la URI entre llaves: {http://www.uniovi.es}pizza","Con @ delante del nombre del elemento: @pizza","Con el prefijo xs: delante del nombre: xs:pizza","Sin cambios: el espacio de nombres se ignora"],"correcta":0,"explicacion":"Cuando el XML usa un espacio de nombres (por ejemplo, por estar ligado a un Schema), ElementTree escribe los elementos con la URI entre llaves: {http://www.uniovi.es}pizza."},
  {"origen":"ia","tema":"T10 · XPath","pregunta":"¿Qué selecciona //libro/*?","opciones":["Todos los elementos hijos de cada libro","Los atributos de cada libro","Todos los libros del documento","El texto de cada elemento libro"],"correcta":0,"explicacion":"//libro/* selecciona todos los elementos hijos (titulo, autor, editorial, anio, isbn) de cada libro del documento."},
  // T11 · XSLT
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"¿Qué tres especificaciones forman XSL?","opciones":["DOM, SAX y XPath","XML, DTD y XML Schema","XSLT, CSS y HTML","XSLT, XSL-FO y XPath"],"correcta":3,"explicacion":"XSLT transforma, XSL-FO formatea (sobre todo para generar PDF) y XPath localiza partes del documento."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"¿Para qué se usa principalmente XSL-FO?","opciones":["Para crear gráficos vectoriales a partir de XML","Para dar formato visual a un XML, sobre todo en PDF","Para hacer consultas a bases de datos XML","Para validar documentos XML contra un esquema"],"correcta":1,"explicacion":"XSL-FO (Formatting Objects) especifica el formato visual con el que se presenta un documento XML y se usa principalmente para generar PDF. XSLT transforma y XPath localiza nodos."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"Según la tabla CSS vs XSL de los apuntes, ¿qué ventaja tiene XSL?","opciones":["Lo aplican todos los navegadores actuales sin plugins","Se puede usar directamente con documentos HTML","Es un lenguaje de transformación y usa sintaxis XML","Es más sencillo que CSS y no necesita procesador"],"correcta":2,"explicacion":"Según la tabla de los apuntes, CSS se usa con HTML y XML pero no transforma; XSL no se usa con HTML, sí con XML, es un lenguaje de transformación y tiene sintaxis XML."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"¿Por qué los navegadores actuales ya no son buenas herramientas para aplicar XSLT a archivos XML?","opciones":["Solo admiten hojas XSLT de la versión 3.0","XSLT está obsoleto y el W3C lo ha retirado","Necesitan JavaScript activado para aplicarlas","Han dejado de aplicarlas por motivos de seguridad"],"correcta":3,"explicacion":"Solo navegadores antiguos sin soporte de seguridad (p. ej. Internet Explorer) lo admitían; hoy se usan plugins de editores como Notepad++."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"¿Qué ocurre con la parte del documento fuente que no encaja con ninguna plantilla?","opciones":["Se elimina de la salida siempre","Permanece sin modificación","Provoca un error de transformación","Se convierte en un comentario"],"correcta":1,"explicacion":"Durante la transformación, XSLT usa XPath para encontrar las partes del documento que encajan con las plantillas y las transforma. Lo que no encaja con ninguna plantilla queda sin modificar."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"¿Cuál es el elemento raíz de una hoja XSL?","opciones":["<xsl:template>","<xsl:output>","<xsl:root>","<xsl:stylesheet>"],"correcta":3,"explicacion":"Con version y xmlns:xsl=\"http://www.w3.org/1999/XSL/Transform\"."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"¿Cómo se asocia una hoja XSL a un documento XML?","opciones":["<link rel=\"stylesheet\" type=\"text/xsl\" href=\"poema.xsl\">","<!DOCTYPE poema SYSTEM \"poema.xsl\">","<poema xsi:schemaLocation=\"poema.xsl\">","<?xml-stylesheet type=\"text/xsl\" href=\"poema.xsl\"?>"],"correcta":3,"explicacion":"La hoja XSL se asocia con una instrucción de procesamiento en el XML: <?xml-stylesheet type=\"text/xsl\" href=\"poema.xsl\"?>. Para CSS se usaría type=\"text/css\"."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"¿Qué tipo de expresión es el valor del atributo match de <xsl:template>?","opciones":["Un nombre de archivo","Una expresión regular","Una expresión XPath","Un selector CSS"],"correcta":2,"explicacion":"match=\"/\" se aplica a todo el documento."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"¿Qué valores admite el atributo method de <xsl:output>?","opciones":["xml, html o text","css, js o json","pdf, png o svg","strict o lax"],"correcta":0,"explicacion":"<xsl:output method=\"…\"> define el tipo de salida: xml, html o text. También tiene atributos como encoding, indent y omit-xml-declaration."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"¿Qué son los elementos LRE (Literal Result Elements)?","opciones":["Variables globales declaradas en la hoja XSL","Elementos de extensión propios del procesador","Elementos ajenos a XSLT que se copian tal cual","Elementos del espacio de nombres xsl estándar"],"correcta":2,"explicacion":"Los LRE (Literal Result Elements) son elementos que no pertenecen a XSLT, como <html> o <p>, y se copian tal cual al documento de salida."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"¿Qué hace <xsl:value-of select=\"@autor\"/>?","opciones":["Escribe en la salida el valor del atributo autor","Crea un nuevo atributo autor en el elemento de salida","Recorre todos los atributos autor del documento","Ordena los nodos según el valor del atributo autor"],"correcta":0,"explicacion":"<xsl:value-of> añade a la salida el valor de lo que selecciona su expresión XPath; con select=\"@autor\" es el valor del atributo autor del nodo actual."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"¿Para qué sirve <xsl:apply-templates>?","opciones":["Aplica las plantillas que encajan con los nodos indicados","Importa las plantillas de otra hoja de estilo XSL","Crea un bucle con contador sobre los nodos indicados","Define una nueva plantilla con el nombre indicado"],"correcta":0,"explicacion":"<xsl:apply-templates select=\"…\"> pide al procesador que busque y aplique las plantillas que encajen con los nodos seleccionados; así se recorre el árbol de forma recursiva."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"¿Qué elemento recorre todos los nodos que selecciona una expresión XPath?","opciones":["<xsl:for-each>","<xsl:element>","<xsl:if>","<xsl:choose>"],"correcta":0,"explicacion":"<xsl:for-each select=\"XPath\"> recorre todos los nodos seleccionados y aplica su contenido a cada uno, como un bucle."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"¿Qué atributos tiene <xsl:sort> para indicar el tipo y el sentido de la ordenación?","opciones":["type y direction","kind y asc/desc","data-type y order","sort y reverse"],"correcta":2,"explicacion":"<xsl:sort> ordena con select (por qué ordenar), data-type=\"text|number\" (alfabético o numérico) y order=\"ascending|descending\"."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"Sobre <xsl:if> se puede decir:","opciones":["Debe ir siempre dentro de un elemento <xsl:choose>","No tiene else; para varios casos se usa <xsl:choose>","Tiene una parte else con el elemento <xsl:otherwise>","Solo admite el operador = para comparar valores"],"correcta":1,"explicacion":"<xsl:if test=\"condición\"> procesa su contenido solo si se cumple la condición, pero no tiene parte else. Para varios casos con uno por defecto se usa <xsl:choose>."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"En <xsl:choose>, ¿qué elemento es el caso por defecto?","opciones":["<xsl:when test=\"true\">","<xsl:default>","<xsl:else>","<xsl:otherwise>"],"correcta":3,"explicacion":"<xsl:choose> funciona como un CASE: varios <xsl:when test=\"…\"> y un <xsl:otherwise> sin atributos como caso por defecto."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"¿Cómo se escribe «year mayor que 1990» dentro del atributo test?","opciones":["year gt; 1990","year [>] 1990","year > 1990","year &gt; 1990"],"correcta":3,"explicacion":"Dentro de XML el carácter > se escribe como la entidad &gt; (y < como &lt;)."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"¿Qué elementos construyen un elemento y sus atributos en el árbol resultado?","opciones":["<xsl:element> y <xsl:attribute>","<xsl:node> y <xsl:property>","<xsl:copy-of> y <xsl:text>","<xsl:create> y <xsl:attr-set>"],"correcta":0,"explicacion":"<xsl:element name=\"…\"> crea un elemento en el árbol resultado y <xsl:attribute name=\"…\"> le añade atributos; así se puede generar XML a partir de XML."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"¿Qué es un AVT (Attribute Value Template)?","opciones":["Un tipo de variable global que guarda atributos","Expresiones entre llaves en un atributo que se evalúan","Un validador que comprueba los valores de los atributos","Una plantilla para declarar atributos dentro de un DTD"],"correcta":1,"explicacion":"Para escribir llaves literales se ponen dobles."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"Sobre las variables en XSLT se puede decir:","opciones":["Solo pueden ser globales, nunca locales","Se pueden reasignar libremente, como en Java","Se declaran con <xsl:var> y se usan con @nombre","Su valor no se puede cambiar y se usan con $nombre"],"correcta":3,"explicacion":"Dentro de un for-each toman un valor distinto en cada iteración."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"¿Dónde se permite <xsl:with-param>?","opciones":["Solo como hijo directo de <xsl:stylesheet>","Dentro de <xsl:output> y de <xsl:sort>","En <xsl:apply-templates> y <xsl:call-template>","Dentro de <xsl:for-each> y de <xsl:if>"],"correcta":2,"explicacion":"<xsl:with-param> pasa un valor a un <xsl:param> de una plantilla y solo se permite dentro de <xsl:apply-templates> y <xsl:call-template>."},
  {"origen":"ia","tema":"T11 · XSLT","pregunta":"¿Qué versión de XSLT es recomendación del W3C desde junio de 2017?","opciones":["1.0","5.0","2.0","3.0"],"correcta":3,"explicacion":"XSLT 3.0 es recomendación del W3C desde el 8 de junio de 2017."},
  // T12 · Procesamiento de XML
  {"origen":"ia","tema":"T12 · Procesamiento de XML","pregunta":"¿Qué hace un parser (analizador sintáctico) XML?","opciones":["Convierte el documento XML en una página HTML","Comprime el documento XML para enviarlo","Genera automáticamente el DTD del documento","Analiza el XML y comprueba si está bien formado"],"correcta":3,"explicacion":"Un parser o analizador sintáctico lee el documento XML y comprueba que está bien formado y, si valida, que es válido. Es la herramienta base de cualquier aplicación que use XML."},
  {"origen":"ia","tema":"T12 · Procesamiento de XML","pregunta":"¿Qué diferencia hay entre un parser sin validación y uno con validación?","opciones":["El segundo no comprueba la sintaxis, solo el DTD o el XML Schema","El primero solo mira si está bien formado; el segundo, también si es válido","El primero mira si es válido; el segundo, solo si está bien formado","Ninguna: los dos comprueban siempre la sintaxis y el esquema"],"correcta":1,"explicacion":"Un parser sin validación solo comprueba la sintaxis (bien formado). Uno con validación además comprueba que el documento cumple su DTD o XML Schema (válido)."},
  {"origen":"ia","tema":"T12 · Procesamiento de XML","pregunta":"¿Qué dos APIs estandarizadas de procesamiento de XML citan los apuntes, con implementaciones para muchos lenguajes?","opciones":["XSLT y XPath","REST y SOAP","JSON y YAML","SAX y DOM"],"correcta":3,"explicacion":"Lo que no está estandarizado es cómo crear instancias de los parsers."},
  {"origen":"ia","tema":"T12 · Procesamiento de XML","pregunta":"¿Qué es JAXP?","opciones":["La API de Java para usar parsers SAX, DOM y XSL","Un lenguaje derivado de XML para servicios web","Una biblioteca de JavaScript para cargar XML","Un parser de C# incluido en el framework .NET"],"correcta":0,"explicacion":"JAXP (Java API for XML Processing) forma parte de Java desde J2SE 1.4 y ofrece factorías para crear parsers SAX y DOM y transformadores XSL de forma portable."},
  {"origen":"ia","tema":"T12 · Procesamiento de XML","pregunta":"¿Qué parser usaba Mozilla internamente según los apuntes?","opciones":["MSXML","Crimson","EXPAT","Xerces"],"correcta":2,"explicacion":"Según los apuntes, Mozilla usaba internamente el parser EXPAT (escrito en C) e Internet Explorer usaba MSXML. Xerces y Crimson son de Apache."},
  {"origen":"ia","tema":"T12 · Procesamiento de XML","pregunta":"¿Cuál de estas alternativas NO sirve para procesar XML en C# según los apuntes?","opciones":["LINQ to XML (XElement)","XmlDocument","xml.etree.ElementTree","XmlReader / XmlWriter"],"correcta":2,"explicacion":"xml.etree.ElementTree es la biblioteca estándar de Python."},
  {"origen":"ia","tema":"T12 · Procesamiento de XML","pregunta":"¿Qué caracteriza a XmlReader en C#?","opciones":["Carga todo el árbol DOM del documento en memoria","Usa consultas integradas parecidas a SQL","Acceso rápido, sin caché y solo hacia delante","Permite modificar el documento y guardarlo"],"correcta":2,"explicacion":"XmlReader ofrece un acceso rápido, sin caché y solo hacia delante: lee nodo a nodo (Element, Text, EndElement…) sin cargar todo el documento. Para modificarlo se usa XmlDocument."},
  {"origen":"ia","tema":"T12 · Procesamiento de XML","pregunta":"¿Qué método de XmlDocument devuelve una XmlNodeList con los elementos de un nombre dado?","opciones":["FindElementsByName()","QuerySelectorAll()","SelectNodesByName()","GetElementsByTagName()"],"correcta":3,"explicacion":"doc.GetElementsByTagName(\"tres\") devuelve una XmlNodeList con todos los elementos de ese nombre; luego se accede a cada uno con XmlNodeList[0], [1]…"},
  {"origen":"ia","tema":"T12 · Procesamiento de XML","pregunta":"Con XmlDocument, dado <tres>Valor 1</tres>, ¿dónde está el texto «Valor 1»?","opciones":["En nodo.FirstChild.Value","En nodo.Attributes[0].Value","En nodo.ParentNode.Value","En nodo.Value directamente"],"correcta":0,"explicacion":"El texto es un nodo hijo del elemento; el elemento en sí tiene Name pero no Value."},
  {"origen":"ia","tema":"T12 · Procesamiento de XML","pregunta":"¿Qué ventaja tiene LINQ to XML frente a DOM según los apuntes?","opciones":["No necesita cargar el documento en memoria","Un modelo de objetos más ligero y fácil de usar","Funciona sin necesidad del framework .NET","Solo permite leer, lo que lo hace más seguro"],"correcta":1,"explicacion":"LINQ to XML trabaja en memoria con un modelo de objetos (XDocument, XElement) más ligero y fácil que DOM, y permite consultas integradas en C# y Visual Basic."},
  {"origen":"ia","tema":"T12 · Procesamiento de XML","pregunta":"En Python con ElementTree, ¿qué hace raiz.findall('.//')?","opciones":["Devuelve solo el elemento raíz del árbol","Recorre todos los elementos descendientes","Busca todos los atributos del documento","Valida el documento contra su DTD"],"correcta":1,"explicacion":"findall('.//') busca todos los elementos descendientes del nodo raíz, así que permite recorrer todo el árbol y mostrar cada elemento con su contenido y atributos."},
  {"origen":"ia","tema":"T12 · Procesamiento de XML","pregunta":"¿Qué excepción de ElementTree indica que el archivo XML no se ha podido procesar (por ejemplo, mal formado)?","opciones":["ET.ParseError","ET.FormatError","ET.XMLSyntaxError","ET.InvalidXML"],"correcta":0,"explicacion":"ET.ParseError salta cuando el XML no se puede analizar, por ejemplo porque está mal formado. Si el archivo no existe, el error es IOError (FileNotFoundError). Las demás opciones no son excepciones de ElementTree."},
  {"origen":"ia","tema":"T12 · Procesamiento de XML","pregunta":"En el ejemplo con jQuery, ¿cómo se carga un archivo XML del servidor?","opciones":["Con un <iframe> oculto que lo carga","Con <link rel=\"alternate\" type=\"xml\">","Con $.ajax indicando dataType: \"xml\"","Con una transformación XSLT en el navegador"],"correcta":2,"explicacion":"jQuery carga el XML del servidor con AJAX: $.ajax({ dataType: \"xml\", url: …, method: 'GET', success: … }) y después lo recorre con selectores como $('city', datos)."},
  {"origen":"ia","tema":"T12 · Procesamiento de XML","pregunta":"¿Qué formato, además de XML, usan habitualmente los servicios web como OpenWeatherMap?","opciones":["JSON","SVG","YAML","CSV"],"correcta":0,"explicacion":"Los servicios web como OpenWeatherMap ofrecen sus datos en XML y también en JSON (JavaScript Object Notation), que está sustituyendo a XML en muchas aplicaciones."},
  {"origen":"ia","tema":"T12 · Procesamiento de XML","pregunta":"En el ejemplo de generación de XML, ¿qué se obtiene a partir del archivo .LOG de una cámara Nikon con datos GPS (NMEA)?","opciones":["Un PDF con las coordenadas de la ruta","Un archivo SVG con el mapa de la ruta","Un DTD para validar los datos NMEA","Un archivo KML con la ruta del GPS"],"correcta":3,"explicacion":"Se procesan las líneas NMEA ($GPGGA, $GPRMC) del .LOG del GPS de la cámara y se genera un KML con un LineString de coordenadas: la ruta seguida, visible en Google Earth."},
  // S1-2 · Usabilidad
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"Según los seminarios, un sistema usable es…","opciones":["Accesible para todos + adaptable","Bonito a la vista + rápido de cargar","Barato de desarrollar + seguro","Fácil de aprender + fácil de utilizar"],"correcta":3,"explicacion":"Sistema usable = fácil de aprender + fácil de utilizar. Es la definición base de los seminarios de usabilidad."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Cuál de estas cosas incluye la usabilidad además de colores y tipos de letra?","opciones":["Diseño de diálogos, documentación y uso de metáforas","El logotipo y la identidad corporativa","Posicionamiento en buscadores (SEO) y anuncios","Rendimiento del servidor y tiempos de respuesta"],"correcta":0,"explicacion":"La usabilidad es mucho más que colores y tipos de letra: incluye el diseño de los diálogos, el enlace cognitivo entre usuario y sistema, la calidad de la documentación y la incorporación de metáforas."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Qué es la experiencia de usuario (UX)?","opciones":["Una parte de la accesibilidad centrada en el color","La interacción del usuario con el sistema, vista en conjunto","El número de visitas y el tiempo de permanencia","La velocidad de carga y el rendimiento del sitio"],"correcta":1,"explicacion":"Depende de muchos factores: usabilidad, accesibilidad, contenidos, emociones, confianza, imagen de marca…"},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Qué facilita la familiaridad en un sistema nuevo?","opciones":["Esconder la navegación secundaria","Usar nombres técnicos precisos","Usar metáforas del mundo real ya conocidas","Añadir instrucciones detalladas al inicio"],"correcta":2,"explicacion":"Los iconos son metáforas gráficas reducidas. Cuando no hay metáforas, hay que incrementar las pruebas de usabilidad."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Cuál es la primera y fundamental norma de usabilidad de Steve Krug?","opciones":["No me hagas pensar","Usa siempre carruseles","Máximo tres clics","Elimina la mitad de las palabras"],"correcta":0,"explicacion":"«No me hagas pensar» es la norma fundamental de Krug: una página debe ser obvia, evidente y clara, y entenderse sin esfuerzo."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Qué dice la 2ª norma de Krug sobre los clics?","opciones":["Nunca más de tres clics para llegar a cualquier página","Cada clic de más reduce a la mitad las visitas","Cuantos menos enlaces tenga cada página, mejor","No importan los clics si cada elección es mecánica e inequívoca"],"correcta":3,"explicacion":"Regla de oro: tres clics mecánicos e inequívocos equivalen a un clic que requiere cierta reflexión."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Qué dice la 3ª norma de Krug?","opciones":["Pon instrucciones claras y completas en cada formulario","Quita la mitad de las palabras y luego la mitad del resto","Escribe siempre un texto de bienvenida en la portada","Repite lo importante varias veces para que se entienda"],"correcta":1,"explicacion":"La 3ª norma de Krug es eliminar la mitad de las palabras de cada página y después la mitad de lo que quede: así se reduce el ruido, se realza lo útil y se ve más contenido sin desplazarse."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Cómo usamos realmente la Web según Krug?","opciones":["Leemos cada página entera y en orden","Comparamos todas las opciones antes de elegir","Hojeamos y pulsamos lo primero que parece razonable","Leemos las instrucciones antes de hacer nada"],"correcta":2,"explicacion":"Leemos la web como un cartel que pasamos a más de 100 km/h y no tomamos decisiones óptimas."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Qué nos hace pensar innecesariamente en una página web?","opciones":["Nombres ingeniosos o técnicos y no saber qué es clicable","Títulos claros que describen el contenido de cada sección","Migas de pan que indican en qué parte del sitio estamos","Seguir las convenciones de diseño habituales en la Web"],"correcta":0,"explicacion":"Hacen pensar los nombres ingeniosos, específicos de la empresa o técnicos (en vez de «Ofertas de trabajo»), y no saber qué es clicable. Las convenciones, los títulos claros y las migas ayudan."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Cuándo está justificado NO usar una convención según los apuntes?","opciones":["Si la alternativa es igual de clara o aporta mucho valor","Si el sitio es nuevo y quiere diferenciarse de los demás","Nunca: las convenciones se deben seguir en todos los casos","Siempre que el diseñador quiera innovar en la interfaz"],"correcta":0,"explicacion":"Krug dice que se puede romper una convención solo si lo nuevo es igual de claro (sin curva de aprendizaje) o aporta tanto valor que compensa la pequeña curva. Si no, hay que aprovechar las convenciones."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Cuál de estos es un criterio de «diseño de anuncios» de Krug?","opciones":["Evitar las convenciones para parecer original","Crear una jerarquía visual clara en cada página","Llenar la página de elementos para llamar la atención","Ocultar lo que se puede pulsar hasta pasar el ratón"],"correcta":1,"explicacion":"Los criterios son: jerarquía visual clara, uso de convenciones, zonas bien definidas, dejar claro lo que se puede pulsar y minimizar el ruido."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Qué recomienda Krug sobre las instrucciones?","opciones":["Repetirlas en cada página para que no se olviden","Ponerlas largas y al principio de la página","Ponerlas en un PDF aparte para quien las necesite","Que todo se explique solo y, si hacen falta, sean breves"],"correcta":3,"explicacion":"Nadie lee las instrucciones: primero se prueba. Todo debe explicarse por sí mismo y, si hacen falta instrucciones, hay que reducirlas a lo esencial."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Qué porcentaje aproximado de todos los clics en la Web representa el botón Atrás según los apuntes?","opciones":["Alrededor del 75%","Entre el 30 y el 40%","Menos del 5%","El 100%"],"correcta":1,"explicacion":"El botón Atrás supone entre el 30 y el 40% de todos los clics en la Web. En la web no hay sensación de escala ni de dirección, por eso Atrás, los favoritos y la página principal son tan importantes."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Qué elementos forman la navegación constante o global?","opciones":["Anuncios, banners, enlaces patrocinados, novedades y ofertas","Logotipo, pie de página, aviso legal, contacto y redes sociales","Identificación, página principal, secciones, búsqueda y utilidades","Migas de pan, mapa del sitio, etiquetas, filtros y paginación"],"correcta":2,"explicacion":"Debe aparecer siempre en el mismo lugar y con la misma apariencia (salvo quizá en la página principal y en formularios)."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Dónde debe ubicarse la identificación del sitio en culturas occidentales?","opciones":["En el centro del pie de página","Abajo a la derecha","Arriba a la izquierda","Oculta en un menú"],"correcta":2,"explicacion":"En culturas que leen de izquierda a derecha, la identificación del sitio (logotipo) va arriba a la izquierda, en todas las páginas. En idiomas que se leen de derecha a izquierda va a la derecha."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Cuántas utilidades debería albergar como máximo la navegación global?","opciones":["Todas las que haya","Cuatro o cinco","Una","Doce"],"correcta":1,"explicacion":"La navegación global solo debe albergar cuatro o cinco utilidades (ayuda, carrito, contacto…); si hay más, deben agruparse en la página principal."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Qué etiqueta debe tener el cuadro de búsqueda?","opciones":["«Encontrar rápidamente»","No debe tener etiqueta","«Buscar»","«Introduzca unas palabras clave»"],"correcta":2,"explicacion":"Los usuarios buscan la palabra «Buscar». Hay que evitar variantes elaboradas («Encontrar rápidamente») y las instrucciones del tipo «Introduzca unas palabras clave»."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Qué recomiendan los apuntes sobre las migas de pan?","opciones":["Solo en la página principal, junto al logotipo","En lugar del nombre de la página, en negrita","Arriba, pequeñas, separadas con > y la última en negrita","Abajo, grandes, separadas con / y la última enlazada"],"correcta":2,"explicacion":"Las migas van arriba, en letra pequeña (son un accesorio), separadas con > (sugiere avanzar por los niveles) y con el último término en negrita. No sustituyen al nombre de la página."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Cuál es el principal problema de las etiquetas o solapas (tabs)?","opciones":["No escalan bien cuando hay muchas","Son difíciles de entender para el usuario","No separan la navegación del contenido","No se pueden adaptar a los colores del sitio"],"correcta":0,"explicacion":"Las solapas son claras y separan bien navegación y contenido, pero, pasado cierto número, no escalan: no caben y dejan de funcionar."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Qué preguntas debe responder la página principal de un vistazo?","opciones":["Quién la programó, con qué tecnología y cuándo se actualizó","Cuántas visitas tiene, desde qué países y en qué horario","Cuánto cuesta cada producto, cómo pagarlo y cuándo llega","Qué es, qué puedo hacer y por qué aquí y no en otro sitio"],"correcta":3,"explicacion":"La página principal debe responder de un vistazo y sin ambigüedad: qué es esto, qué puedo hacer aquí, qué tienen y por qué debería estar aquí y no en otro sitio."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Qué es el «pliegue» de una página?","opciones":["La zona del pie de página","Lo que se ve sin desplazarse","La línea entre cabecera y contenido","El menú desplegable principal"],"correcta":1,"explicacion":"El pliegue, término que viene de los periódicos, es la parte de la página que se ve sin desplazarse. Lo importante de la página principal debe quedar por encima."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Qué características debe tener una tagline?","opciones":["Clara, de unas 6-8 palabras y que caracterice al sitio","Un lema publicitario largo y llamativo","Igual que el nombre del sitio, para reforzarlo","Situada solo en el pie, junto al copyright"],"correcta":0,"explicacion":"La tagline resume qué es el sitio y qué lo hace especial: clara, informativa, de unas seis a ocho palabras, junto al identificador del sitio. No es un lema publicitario."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Para qué listas son eficaces los menús desplegables?","opciones":["Listas de nombres desconocidos y sin un orden concreto","Listas alfabéticas de nombres conocidos (países, ciudades…)","Cualquier lista larga que necesite desplazamiento","Menús principales con muchas secciones y sub-secciones"],"correcta":1,"explicacion":"Los menús desplegables cuesta revisarlos y no llaman la atención. Solo son eficaces con listas alfabéticas de nombres conocidos (países, ciudades, productos); no cuando no sabes cómo se llama lo que buscas."},
  {"origen":"ia","tema":"S1-2 · Usabilidad","pregunta":"¿Cuál de estos detalles puede arruinar la página principal?","opciones":["Tener un cuadro de búsqueda visible","Tener una tagline debajo del logotipo","Obligar a registrarse antes de poder navegar","Mostrar el nombre del sitio arriba"],"correcta":2,"explicacion":"También: un banner innecesario, intentar promocionarlo todo o dejar que el negocio dirija el diseño."},
  // S3 · Adaptabilidad
  {"origen":"ia","tema":"S3 · Adaptabilidad","pregunta":"¿Qué es el diseño web adaptable (Responsive Web Design)?","opciones":["Usar solo medidas fijas en píxeles","Diseñar la web únicamente para móviles","Crear una versión distinta para cada dispositivo","Que una misma web se adapte a cada dispositivo y pantalla"],"correcta":3,"explicacion":"Es una aplicación práctica de los principios de usabilidad y experiencia de usuario."},
  {"origen":"ia","tema":"S3 · Adaptabilidad","pregunta":"¿Qué ventaja tiene la adaptabilidad para desarrolladores y organizaciones?","opciones":["Un solo sitio para todos los dispositivos, más fácil de mantener","No tener que probar nunca la web en dispositivos móviles","Evitar el uso de CSS y de media queries en el proyecto","Mantener varios sitios separados y sincronizados a la vez"],"correcta":0,"explicacion":"Para desarrolladores y organizaciones, la adaptabilidad supone un único sitio web para todos los dispositivos, menos esfuerzo de mantenimiento y más alcance y accesibilidad."},
  {"origen":"ia","tema":"S3 · Adaptabilidad","pregunta":"¿Cómo era la web de escritorio hasta mediados de los 2000?","opciones":["Solo era accesible desde los primeros móviles","Navegación táctil y gran variedad de pantallas","Maquetación basada en Flexbox y Grid","Resoluciones homogéneas, ancho fijo, teclado y ratón"],"correcta":3,"explicacion":"Hasta mediados de los 2000 se accedía casi solo desde ordenadores de escritorio, con resoluciones homogéneas (640x480, 800x600), diseños de ancho fijo y navegación con teclado y ratón."},
  {"origen":"ia","tema":"S3 · Adaptabilidad","pregunta":"¿Qué hito de 2007 inicia la «revolución móvil» según los apuntes?","opciones":["Los primeros teléfonos Android","La publicación de HTML5","El primer iPhone","El primer iPad"],"correcta":2,"explicacion":"2008: primeros Android; 2010: primer iPad."},
  {"origen":"ia","tema":"S3 · Adaptabilidad","pregunta":"¿Qué hace <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">?","opciones":["Desactiva el zoom para que no se deforme","Usa el ancho del dispositivo con escala inicial 1:1","Fija el ancho de la página a 1024px siempre","Oculta la barra de direcciones del navegador"],"correcta":1,"explicacion":"width=device-width hace que la página use el ancho real del dispositivo e initial-scale=1.0 evita que aparezca ampliada o reducida al cargarse. Es la base del diseño adaptable en móviles."},
  {"origen":"ia","tema":"S3 · Adaptabilidad","pregunta":"¿Qué regla CSS hace una imagen flexible sin ampliarla por encima de su tamaño original?","opciones":["img { min-width: 100%; height: auto; }","img { width: 100%; height: auto; }","img { max-width: 100%; height: auto; }","img { width: 600px; height: auto; }"],"correcta":2,"explicacion":"max-width: 100% impide que la imagen sea más ancha que su contenedor sin ampliarla por encima de su tamaño real, y height: auto mantiene sus proporciones."},
  {"origen":"ia","tema":"S3 · Adaptabilidad","pregunta":"Una imagen de 300px en un contenedor de 500px con width: 100%; height: auto; ocupará…","opciones":["300px, porque nunca supera su tamaño original","250px, la mitad del ancho del contenedor","0px, porque height: auto anula el ancho","500px, ampliándose y pudiendo perder calidad"],"correcta":3,"explicacion":"Con max-width: 100% ocuparía 300px, su tamaño máximo."},
  {"origen":"ia","tema":"S3 · Adaptabilidad","pregunta":"¿Qué se suele hacer con el ancho del reproductor de audio en un diseño adaptable?","opciones":["width: 100%; max-width: 600px;","height: 100%; min-width: 600px;","display: none; en los móviles","width: 600px; height: 100%;"],"correcta":0,"explicacion":"El reproductor de audio tiene controles de tamaño casi fijo, así que se le pone doble restricción: width: 100% para adaptarse y max-width: 600px para que no crezca indefinidamente."},
  {"origen":"ia","tema":"S3 · Adaptabilidad","pregunta":"¿Qué caracteriza a un diseño fluido?","opciones":["Necesita JavaScript para recalcular tamaños","Usa unidades relativas que se ajustan al espacio","Usa tablas para maquetar las columnas","Usa medidas fijas en píxeles para todo"],"correcta":1,"explicacion":"Un diseño fluido usa unidades relativas (%, em, rem, vw…) en lugar de medidas fijas, para que los elementos crezcan o encojan con el espacio disponible y no haya desplazamiento horizontal."},
  {"origen":"ia","tema":"S3 · Adaptabilidad","pregunta":"¿Por qué rem produce resultados más predecibles que em?","opciones":["Se basa en la fuente del elemento padre directo","Depende del ancho del viewport, igual que vw","Se basa en la fuente raíz y no se acumula al anidar","Es una unidad absoluta, equivalente a los píxeles"],"correcta":2,"explicacion":"em es relativo a la fuente del elemento padre, así que se multiplica en elementos anidados. rem siempre se calcula sobre la fuente raíz (html), por lo que el resultado es predecible."},
  {"origen":"ia","tema":"S3 · Adaptabilidad","pregunta":"¿En qué consiste Mobile First?","opciones":["Crear una app nativa antes que la versión web","Diseñar primero para escritorio y luego reducir","Hacer solo la versión móvil del sitio","Diseñar primero para pantallas pequeñas y luego ampliar"],"correcta":3,"explicacion":"Obliga a priorizar el contenido esencial y es la estrategia predominante hoy."},
  {"origen":"ia","tema":"S3 · Adaptabilidad","pregunta":"Según el seminario, ¿qué rango de ancho corresponde a una tableta?","opciones":["Entre 768px y 1024px","Entre 320px y 600px","Menos de 480px","Más de 1440px"],"correcta":0,"explicacion":"Móvil: menos de 768px; tablet: 768–1024px; escritorio: más de 1024px."},
  {"origen":"ia","tema":"S3 · Adaptabilidad","pregunta":"¿Por qué hoy se necesitan menos media queries que antes?","opciones":["Casi todos los dispositivos tienen la misma pantalla","Flexbox y Grid reorganizan sin necesidad de breakpoints","Los navegadores ya no las soportan bien","Ahora se maqueta con tablas adaptables"],"correcta":1,"explicacion":"Siguen siendo necesarias para cambiar número de columnas, tipografías, menús, mostrar u ocultar contenido…"},
  {"origen":"ia","tema":"S3 · Adaptabilidad","pregunta":"Sobre los frameworks como Bootstrap o Tailwind se puede decir:","opciones":["Solo sirven para sitios de escritorio","Son técnicas de diseño adaptable en sí mismas","Implementan las técnicas, pero no son técnicas","El W3C desaconseja usarlos"],"correcta":2,"explicacion":"Bootstrap, Tailwind, Foundation, Bulma, React… no son técnicas en sí: implementan las técnicas (viewport, diseño fluido, media queries) y facilitan su uso con componentes ya preparados."},
  {"origen":"ia","tema":"S3 · Adaptabilidad","pregunta":"¿Qué recomendación del W3C sobre adaptabilidad se aprobó el 29 de julio de 2008?","opciones":["Mobile Web Best Practices 1.0","CSS Media Queries Level 3","HTML5 Responsive Images","Web Content Accessibility Guidelines 2.0"],"correcta":0,"explicacion":"El W3C aprobó el 29 de julio de 2008 las Mobile Web Best Practices 1.0, dentro de su iniciativa de Web móvil."},
  {"origen":"ia","tema":"S3 · Adaptabilidad","pregunta":"¿Qué herramienta integrada en el navegador permite simular dispositivos móviles?","opciones":["Chrome DevTools (F12) o Responsive Design Mode de Firefox","El validador de CSS del W3C en su modo de vista móvil","xmllint con la opción de simulación de pantallas móviles","Notepad++ con un plugin de vista previa de dispositivos"],"correcta":0,"explicacion":"Chrome DevTools (F12 → icono de dispositivos) y el Responsive Design Mode de Firefox simulan móviles, tabletas y resoluciones. Edge y Opera usan las herramientas de Chrome."},
  {"origen":"ia","tema":"S3 · Adaptabilidad","pregunta":"¿Por qué los sitios web para móviles suelen ser más largos y profundos que los de escritorio?","opciones":["Porque los usuarios leen más en el móvil","Por la falta de espacio en pantalla","Porque usan un HTML diferente","Porque tienen más contenido que en escritorio"],"correcta":1,"explicacion":"Como hay poco espacio en pantalla, los sitios móviles reparten el contenido en más pantallas y niveles: son más largos y profundos, y el usuario tiene que hacer más clics y desplazarse más."},
  // S4 · Accesibilidad
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Qué es el diseño universal?","opciones":["Usar exactamente el mismo diseño en todos los países","Productos pensados solo para personas con alguna discapacidad","Productos usables por el mayor número de personas y situaciones","Diseñar pensando en las necesidades del usuario medio"],"correcta":2,"explicacion":"El diseño universal busca productos usables por el rango más amplio de personas, en el rango más amplio de situaciones y que sean comercialmente viables. La Web debe tener un diseño universal."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Cuál de estos NO es uno de los 7 principios del diseño universal?","opciones":["Máxima densidad de información","Esfuerzo físico mínimo","Uso equitativo","Tolerancia para el error"],"correcta":0,"explicacion":"Son: uso equitativo, uso flexible, uso simple e intuitivo, información perceptible, tolerancia al error, esfuerzo físico mínimo y tamaño y espacio adecuados."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"Según el estudio de Microsoft de 2000 citado en los apuntes, ¿qué proporción de estadounidenses tiene alguna necesidad especial?","opciones":["Uno de cada cien","La mitad","Uno de cada mil","Uno de cada cinco"],"correcta":3,"explicacion":"Según un estudio de Microsoft de 2000, uno de cada cinco estadounidenses tiene algún tipo de necesidad especial. Por eso la accesibilidad afecta a muchos usuarios."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿A qué porcentaje de hombres y mujeres afecta la ceguera al color según los apuntes?","opciones":["1% de los hombres y 0,5% de las mujeres","0,5% de los hombres y 8% de las mujeres","8% de los hombres y 8% de las mujeres","8% de los hombres y 0,5% de las mujeres"],"correcta":3,"explicacion":"La ceguera al color se debe a la falta de algún tipo de cono (rojo, verde o azul) y afecta al 8% de los hombres y al 0,5% de las mujeres."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Cuál es la conclusión principal sobre el uso del color en interfaces?","opciones":["No codificar nada importante solo con el color","Usar siempre fondo negro y texto claro","Usar solo rojo y verde para los estados","Evitar los colores en la interfaz"],"correcta":0,"explicacion":"Por ejemplo, los campos obligatorios se marcan con un asterisco o icono, no solo en rojo."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Qué es la protanopia?","opciones":["Carencia de sensibilidad al color verde","Ceguera total para los colores","Carencia de sensibilidad al color azul","Carencia de sensibilidad al color rojo"],"correcta":3,"explicacion":"Deuteranopia: dificultad para distinguir verde y rojo; tritanopia: carencia de sensibilidad al azul."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Cuál es una barrera para personas con visión reducida?","opciones":["La posibilidad de navegar por la página con el teclado","El uso de encabezados para estructurar el contenido","Tamaños de letra absolutos que no se pueden ampliar","Los textos alternativos que acompañan a las imágenes"],"correcta":2,"explicacion":"Las personas con visión reducida necesitan ampliar el texto. Los tamaños de letra absolutos que no se pueden cambiar, el poco contraste y las páginas que pierden el contexto al ampliarse son barreras."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Qué canales usa un ordenador para personas con ceguera?","opciones":["Colores de alto contraste","Voz sintetizada y líneas Braille","Pantallas más grandes y lupas","El ratón con avisos sonoros"],"correcta":1,"explicacion":"Cuando no se puede usar la pantalla, la información se transmite por otro canal: voz sintetizada (lectores de pantalla) y líneas Braille actualizables. Por eso los gráficos necesitan descripciones de texto."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Qué es JAWS?","opciones":["Un validador de HTML","Un estándar de accesibilidad","Un lector de pantalla para Windows","Un navegador de texto"],"correcta":2,"explicacion":"JAWS (Job Access With Speech) es un lector de pantalla para Windows: lee el texto de la pantalla mediante voz sintetizada o un dispositivo Braille."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"Para un usuario invidente, ¿qué elemento de entrada es fundamental?","opciones":["La pantalla táctil","El teclado","El lápiz óptico","El ratón"],"correcta":1,"explicacion":"Todos los elementos de la interfaz deben poder usarse mediante teclado."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Qué cuidado hay que tener con los mensajes de alerta sonoros?","opciones":["Solo funcionan bien en los móviles","Ninguno: bastan por sí solos","Deben sonar más alto para que se oigan","Que no sean el único canal: no todos los oyen"],"correcta":3,"explicacion":"Si una alerta importante solo se comunica con sonido, una persona con discapacidad auditiva no se entera del riesgo. Hay que reforzarla con señales visuales."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Qué lenguaje basado en XML se usa para la escritura de signos en aplicaciones web?","opciones":["SVG (Scalable Vector Graphics)","SWML (SignWriting Markup Language)","MathML (Mathematical Markup Language)","VoiceXML (Voice Extensible Markup Language)"],"correcta":1,"explicacion":"SWML (SignWriting Markup Language) es un lenguaje basado en XML para la escritura de las lenguas de signos, en el que se basan la mayoría de las aplicaciones web de este tipo."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Cuál es un inconveniente importante para personas con discapacidades motoras?","opciones":["Imágenes sin texto alternativo que las describa","Vídeos sin subtítulos ni transcripción del audio","Tiempos de respuesta limitados y sin alternativa al ratón","Páginas con demasiado texto seguido y sin apartados"],"correcta":2,"explicacion":"A las personas con discapacidades motoras les cuesta mover el puntero o pulsar varias teclas a la vez. Las barreras principales son no tener alternativa de teclado al ratón y los tiempos de respuesta limitados."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Qué dificultades tienen las personas con síndrome de Down relacionadas con la memoria a largo plazo?","opciones":["Entender iconos, metáforas y cualquier abstracción","Ninguna dificultad relacionada con la memoria","Usar el teclado o el ratón para escribir y navegar","Distinguir los colores y contrastes de la interfaz"],"correcta":0,"explicacion":"Los iconos y metáforas deben completarse con etiquetas de texto."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Cuál es la mejor forma de comprobar la accesibilidad según los apuntes?","opciones":["Pedir la opinión del diseñador y del cliente del sitio","Usar solo herramientas automáticas como TAW","Validar el HTML y el CSS con los validadores del W3C","Que personas con discapacidad evalúen las interfaces"],"correcta":3,"explicacion":"Lo mejor es que personas con discapacidad evalúen nuestras interfaces. En su defecto se usan listas de recomendaciones, normativas (AENOR, WAI) y herramientas."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Qué normas de AENOR tratan la accesibilidad del hardware y del software respectivamente?","opciones":["UNE 139.801 (hardware) y UNE 139.802 (software)","EN 301549 (hardware) y RD 1112/2018 (software)","UNE 139.803 (hardware) y UNE 139.804 (software)","ISO 8879 (hardware) e ISO 40500 (software)"],"correcta":0,"explicacion":"AENOR tiene la norma UNE 139.801 para el hardware (CPU, periféricos, teclado, ratón, pantalla) y la UNE 139.802 para el software (sistema operativo, aplicaciones e Internet). La UNE 139.803 es la de contenidos web."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Cuál es actualmente la norma de referencia en España para la accesibilidad de contenidos web?","opciones":["UNE 139803:2004, alineada con las WCAG 1.0","UNE-EN 301549:2022, alineada con las WCAG 2.1","WCAG 1.0 del W3C, sin norma propia","Ley 56/2007 de la sociedad de la información"],"correcta":1,"explicacion":"La norma de referencia actual es la UNE-EN 301549:2022, alineada con las WCAG 2.1. Sustituye a las UNE 139803 de 2004 (basada en WCAG 1.0) y 2012 (WCAG 2.0)."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Qué Real Decreto regula la accesibilidad de los sitios web y apps móviles del sector público en España?","opciones":["RD 1112/2018","RD 2016/2102","RD 56/2007","RD 1494/2007"],"correcta":0,"explicacion":"El Real Decreto 1112/2018 regula la accesibilidad de los sitios web y las apps móviles del sector público y traslada a España la Directiva (UE) 2016/2102."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Antes de qué fecha debían ser accesibles todas las aplicaciones móviles del sector público según la Directiva (UE) 2016/2102?","opciones":["23 de junio de 2021","1 de enero de 2016","31 de diciembre de 2008","12 de diciembre de 2024"],"correcta":0,"explicacion":"La Directiva (UE) 2016/2102 amplió los requisitos a las aplicaciones móviles del sector público, que debían ser accesibles antes del 23 de junio de 2021."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"En WCAG 1.0, ¿qué significa el nivel de conformidad «Doble A»?","opciones":["Se cumplen los puntos de prioridad 1, 2 y 3","Se cumplen solo los de prioridad 2","Se cumplen los puntos de prioridad 1","Se cumplen los puntos de prioridad 1 y 2"],"correcta":3,"explicacion":"En WCAG 1.0: nivel A = se cumplen los puntos de prioridad 1; Doble A (AA) = prioridades 1 y 2; Triple A (AAA) = prioridades 1, 2 y 3."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Cuáles son los cuatro principios de las WCAG 2.x?","opciones":["Usabilidad, adaptabilidad, accesibilidad y seguridad","Prioridad, conformidad, nivel y criterio","Perceptibilidad, operabilidad, comprensibilidad y robustez","Color, contraste, tamaño y tipografía"],"correcta":2,"explicacion":"Las WCAG 2.x se basan en cuatro principios: perceptible, operable, comprensible y robusto. Debajo están las pautas y los criterios de éxito verificables, con niveles A, AA y AAA."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Cuál es la versión más reciente de las WCAG que es recomendación del W3C según los apuntes?","opciones":["WCAG 1.0","WCAG 2.2","WCAG 2.1","WCAG 3"],"correcta":1,"explicacion":"WCAG 2.2 es recomendación desde diciembre de 2024; WCAG 3 está en desarrollo."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Qué es ISO/IEC 40500?","opciones":["Un validador de contraste de colores","La estandarización por ISO de las WCAG 2.2","Una norma de accesibilidad del hardware","La norma ISO del lenguaje SGML"],"correcta":1,"explicacion":"ISO/IEC 40500 es la normalización internacional por ISO de las WCAG del W3C; en su versión actual corresponde a las WCAG 2.2."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Para qué sirven navegadores como Lynx o ELinks en accesibilidad?","opciones":["Para comprobar la navegación con solo texto, sin gráficos","Para generar automáticamente informes WCAG","Para comprobar el contraste entre el texto y el fondo","Para validar las hojas de estilo CSS del sitio"],"correcta":0,"explicacion":"Lynx y ELinks son navegadores de solo texto: permiten comprobar si un sitio se puede usar sin imágenes ni gráficos, de forma parecida a como lo recorre un lector de pantalla."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Cuál de estas herramientas es un analizador automático de accesibilidad de HTML y CSS?","opciones":["Notepad++","Colour Contrast Analyser","Lynx","TAW"],"correcta":3,"explicacion":"Otros analizadores: AChecker, WAVE y el Analizador Web. TAW no analiza el interior del código JavaScript."},
  {"origen":"ia","tema":"S4 · Accesibilidad","pregunta":"¿Qué nivel de las WCAG deben cumplir en España las administraciones públicas y grandes empresas según el resumen del seminario?","opciones":["Ninguno","Nivel AA","Nivel A","Nivel AAA"],"correcta":1,"explicacion":"Según el resumen del seminario, en España las administraciones públicas y las grandes empresas deben cumplir el nivel AA de las WCAG."}
]);
